window.HT=[["الصلاة",0,[["وجوب الصلاة وحكم تاركها",[["عن عبد الله بن عمر أن رسول الله صلى الله عليه وسلم قال: «الذي تفوته صلاة العصر كأنما وُتِرَ أهله وماله».","متفق عليه","صحيح"],["عن جابرٍ رضي الله عنه قال: سمعت النبي صلى الله عليه وسلم يقول: «إِنَّ بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْكِ وَالْكُفْرِ تَرْكَ الصَّلَاةِ».","رواه مسلم","صحيح"],["عن بريدة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إِنَّ الْعَهْدَ الَّذِي بَيْنَنَا وَبَيْنَهُمُ الصَّلَاةُ، فَمَنْ تَرَكَهَا فَقَدْ كَفَرَ».","رواه الترمذي والنسائي وابن ماجه وأحمد","صحيح"],["عن أنس بن مالك رضي الله عنه عن النبي صلى الله عليه وسلم قال: «مَنْ نَسِيَ صَلَاةً فَلْيُصَلِّ إِذَا ذَكَرَهَا، لَا كَفَّارَةَ لَهَا إِلَّا ذَلِكَ: {وَأَقِمِ الصَّلاةَ لِذِكْرِي} [طه: 14]».","متفق عليه","صحيح"],["عَنْ عَبْدِ اللهِ بنِ عُمَر رضي الله عنهما قال: قال رسولُ الله صلى الله عليه وسلم: «بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ الْبَيْتِ، وَصَوْمِ رَمَضَانَ».","متفق عليه","صحيح"],["عن مِحْجَن بن أبي محجن أنه كان في مجلسٍ مع رسول الله صلى الله عليه وسلم فأُذِّنَ بالصلاة، فقام رسول الله صلى الله عليه وسلم، ثم رجع ومحجن في مجلسه فقال له رسول الله صلى الله عليه وسلم: «ما منعك أن تصلي؟ ألستَ برجلٍ مسلمٍ؟» قال: بلى، ولكني كنت قد صليت في أهلي. فقال له رسول الله صلى الله عليه وسلم: «إذا جئت فصلِّ مع الناس وإن كنتَ قد صليتَ».","رواه النسائي","صحيح"]]],["فضل الصلاة",[["وعن جابر رضي الله عنه قال: سُئِل رسول الله صلى الله عليه وسلم أي الصلاة أفضل؟ قال: «طُول القُنُوتِ».","رواه مسلم","صحيح"],["عن عائشة عن النبي صلى الله عليه وسلم قال: «ما من ميت تصلي عليه أُمَّةٌ من المسلمين يبلغون مائة، كلهم يشفعون له، إلا شفعوا فيه».","رواه مسلم","صحيح"],["عن أَبِي مُوسَى الأَشْعَرِيِّ رضي الله عنه: أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم قَالَ: «مَنْ صَلَّى ‌الْبَرْدَيْنِ دَخَلَ الْجَنَّةَ»","متفق عليه","صحيح"],["عن سالم بن أبي الجَعْدِ قال: قال رجل: ليتني صَلَّيتُ فاسترحْتُ، فكأنّهم عابُوا ذلك عليه، فقال: سمعتُ رسولَ الله صلى الله عليه وسلم يقول: «يا بلالُ، أقِمِ الصَّلاةَ، أرِحْنا بها».","رواه أبو داود","صحيح"],["عَنِ أبي زُهير عُمَارَةَ بْنِ رُؤَيْبَةَ رضي الله عنه قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: «لَنْ يَلِجَ النَّارَ أَحَدٌ صَلَّى قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا»","رواه مسلم","صحيح"],["عن جندب بن سفيان البجلي رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «مَنْ صلَّى الصبحَ فهو في ذِمَّةِ اللهِ، فانظُرْ يا ابنَ آدمَ، لا يَطْلُبَنَّكَ اللهُ مِنْ ذِمَّتِهِ بِشَيء».","رواه مسلم بلفظ: «من صلى الصبح فهو في ذمة الله، فلا يطلبنكم الله من ذمته بشيء فيدركه فيكبه في نار جهنم»، وهذا لفظ أحمد","صحيح"],["عن ربيعة بن كعب الأسلمي قال: كنتُ أبيتُ مع رسول الله صلى الله عليه وسلم فأتيتُه بوَضوئه وحاجته فقال لي: «سل» فقلت: أسألك مرافقتك في الجنة. قال: «أو غير ذلك؟» قلت: هو ذاك. قال: «فأعني على نفسك بكثرة السجود».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم كان يقول: «الصَّلَوَاتُ الْخَمْسُ، وَالْجُمُعَةُ إِلَى الْجُمُعَةِ، وَرَمَضَانُ إِلَى رَمَضَانَ، مُكَفِّرَاتٌ مَا بَيْنَهُنَّ إِذَا اجْتَنَبَ الْكَبَائِرَ».","رواه مسلم","صحيح"],["عن عقبة بن عامر قال: سمعت رسول الله صلى الله عليه وسلم يقول: \"يعجب ربك عز وجل من راعي غنم في رأس شَظِيَّة بجبل، يؤذن للصلاة ويصلي، فيقول الله عز وجل: انظروا إلى عبدي هذا يؤذن ويقيم للصلاة، يخاف مني، قد غفرت لعبدي، وأدخلته الجنة\".","رواه أبو داود والنسائي","صحيح"],["عن أبي هريرة أن رسول الله صلى الله عليه وسلم قال: \"يتعاقبون فيكم ملائكةٌ بالليل وملائكةٌ بالنهار، ويجتمعون في صلاة الفجر وصلاة العصر، ثم يعرج الذين باتوا فيكم، فيسألهم وهو أعلم بهم: كيف تركتم عبادي؟ فيقولون: تركناهم وهم يصلون، وأتيناهم وهم يصلون\".","متفق عليه","صحيح"],["عن نافع قال: حُدِّث ابن عمر أن أبا هريرة رضي الله عنهم يقول: «من تبع جنازة فله قيراط» فقال: أكثرَ أبو هريرة علينا، فصدَّقت يعني عائشة أبا هريرة، وقالت: سمعت رسول الله صلى الله عليه وسلم يقوله، فقال ابن عمر رضي الله عنهما: لقد فرَّطنا في قراريط كثيرة.","متفق عليه","صحيح"]]],["الأذان والإقامة",[["عن ابن عمر قال: كان لرسول الله صلى الله عليه وسلم مؤذنان بلال وابن أم مكتوم الأعمى.","رواه مسلم","صحيح"],["عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم : \"الإمام ضامن، والمؤذن مؤتمن، اللهم أرشد الأئمة، واغفر للمؤذنين\" .","رواه أبو داود والترمذي","صحيح"],["عن عثمان بن أبي العاص رضي الله عنه قال: يا رسول الله، اجعلني إمام قومي، قال: «أنت إمامهم، وَاقْتَدِ بأضعفهم، وَاتَّخِذْ مُؤَذِّناً لا يأخذ على أذانه أجرا».","رواه أبو داود والنسائي وأحمد","صحيح"],["عن عبدالله بن عمر رضي الله عنهما أن بلالا أذَّنَ قبل طلوع الفجر، فأمره النبي صلى الله عليه وسلم أن يرجع فينادي: «ألا إن العبد قد نام، ألا إن العبد قد نام».","رواه أبو داود","صحيح"],["عن البراء بن عازب أن نبي الله صلى الله عليه وسلم قال: «إن الله وملائكته يصلون على الصف المقدَّم، والمؤذن يغفر له بمد صوته ويصدقه من سمعه من رطب ويابس، وله مثل أجر من صلى معه».","رواه النسائي","صحيح"]]],["أوقات النهي عن الصلاة",[["عن يسار مَولى ابن عمر قال: رَآني ابن عمر وأنا أصلِّي، بعد طلوع الفَجر، فقال: يا يَسار، إن رسول الله صلى الله عليه وسلم خرج علينا ونحن نُصلِّي هذه الصلاة، فقال: «لِيُبَلِّغْ شِاهِدُكُم غَائِبَكم، لا تُصلُّوا بعد الفجر إلا سَجْدَتَيْن».","رواه أبو داود والترمذي وأحمد","صحيح"],["عن أبي سلمة أنه سأل عائشة عن السجدتين اللتين كان رسول الله صلى الله عليه وسلم يصليهما بعد العصر، فقالت: كان يصليهما قبل العصر، ثم إنه شُغل عنهما، أو نسيهما فصلاهما بعد العصر، ثم أثبتهما، وكان إذا صلى صلاة أثبتها. قال إسماعيل: تعني داوم عليها.","رواه مسلم","صحيح"],["عن ابن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «إذا طلعَ حاجبُ الشمس فدَعُوا الصلاةَ حتى تَبْرُزَ، وإذا غاب حاجبُ الشمس فدَعُوا الصلاةَ حتى تغيبَ، ولا تَحَيَّنُوا بصلاتِكم طُلُوعَ الشمسِ ولا غروبَها، فإنَّها تطلُعُ بيْن قَرْنَيْ شيطان، أو الشيطان».","متفق عليه","صحيح"],["عن عبد الله بن عباس رضي الله عنه قال: «شَهِد عِندِي رِجَال مَرْضِيُون - وأَرْضَاهُم عِندِي عُمر- أنَّ النَبِي صلى الله عليه وسلم نَهَى عن الصَّلاة بَعد الصُّبح حتَّى تَطلُعَ الشَّمسُ، وبعد العصر حتَّى تَغرُب». وعن أبي سعيد رضي الله عنه عن رسول الله صلى الله عليه وسلم أنه قال: «لا صَلاَة بعد الصُّبح حتَّى تَرتَفِعَ الشَّمسُ، ولا صَلاَة بعد العَصرِ حتَّى تَغِيبَ الشَّمس».","حديث ابن عباس رضي الله عنه: متفق عليه.\nحديث أبي سعيد رضي الله عنه: متفق عليه","صحيح"],["عن عمرو بن عَبَسة رضي الله عنه قال: كنت وأنا في الجاهلية أظن أن الناس على ضَلالة، وأنهم لَيْسُوا على شيء، وهم يَعبدون الأوثان، فسمعت برجل بمكة يُخبر أخبارًا، فَقَعَدتُ على راحلتي، فقدِمتُ عليه، فإذا رسول الله صلى الله عليه وسلم مُسْتَخْفِيًا ، جُرَءآءٌ عليه قومه، فتَلطَّفتُ حتى دخلت عليه بمكة، فقلت له: ما أنت؟ قال: «أنا نَبيٌّ» قلت: وما نَبِيٌّ؟ قال: «أرسلني الله» قلت: وبِأَيِّ شيء أرسلك؟ قال: «أرسلني بصلة الأرحام، وكسر الأوثان، وأن يُوَحَّد الله لا يُشرك به شيءٌ»، قلت: فمن معك على هذا؟ قال: «حُرٌّ وعَبْدٌ»، ومعه يومئذ أبو بكر وبلال رضي الله عنهما ، قلت: إني مُتَّبِعُكَ، قال: «إنك لن تستطيع ذلك يَوْمَك هذا، ألا ترى حالي وحال الناس؟ ولكن ارجع إلى أهلك، فإذا سمعت بِي قد ظهرت فأتني». قال: فذهبت إلى أهلي، وقدم رسول الله صلى الله عليه وسلم المدينة حتى قدم نَفرٌ من أهلي المدينة، فقلت: ما فعل هذا الرجل الذي قَدِم المدينة؟ فقالوا: الناس إليه سِرَاعٌ، وقد أراد قومُه قتلَه، فلم يستطيعوا ذلك، فقدمت المدينة، فدخلت عليه، فقلت: يا رسول الله أَتَعْرِفُني؟ قال: «نعم، أنت الذي لَقَيْتَنِي بمكة» قال: فقلت: يا رسول الله، أخبرني عما عَلَّمَك الله وأَجْهَلُهُ، أخبرني عن الصلاة؟ قال: «صَلِّ صلاةَ الصبح، ثم اقْصُرْ عن الصلاة حتى ترتفع الشمس قِيْدَ رمح، فإنها تَطْلُعُ حين تَطلُعُ بين قرني شيطان، وحينئذ يَسجدُ لها الكفار، ثم صلِ فإن الصلاة مشهُودةٌ محضُورةٌ حتى يَسْتَقِلَّ الظِّلُ بالرُّمْح، ثم اقْصُرْ عن الصلاة، فإنه حينئذ تُسْجَرُ جهنم، فإذا أقبل الفيء فَصَلِّ، فإن الصلاة مشهُودةٌ محضُورةٌ حتى تُصلي العصر، ثم اقْصُرْ عن الصلاة حتى تغرب الشمس، فإنها تَغْرُبُ بين قَرْنَيْ شيطان، وحينئذ يسجدُ لها الكفار» قال: فقلت: يا نبي الله، فالوضوء حدثني عنه؟ فقال: «ما مِنكم رجلٌ يُقَرِّبُ وضوءه، فيتمضمض ويستنشق فيستنثر، إلا خرَّت خطايا وجهه من أطراف لحيته مع الماء، ثم يغسل يديه إلى المرفقين، إلا خرَّت خطايا يديه من أنامله مع الماء، ثم يمسح رأسه، إلا خرَّت خطايا رأسه من أطراف شعره مع الماء، ثم يغسل قدميه إلى الكعبين، إلا خرَّت خطايا رجليه من أنامله مع الماء، فإن هو قام فصلى، فحمد الله تعالى ، وأثنى عليه ومجَّدَه بالذي هو له أهل، وفرَّغَ قلبه لله تعالى ، إلا انصرف من خطيئته كهيئته يومَ ولدَتْه أمه». فحدث عمرو بن عبسة بهذا الحديث أبا أمامة صاحب رسول الله صلى الله عليه وسلم فقال له أبو أمامة: يا عمرو بن عبسة، انظر ما تقول! في مقام واحد يُعطى هذا الرجل؟ فقال عمرو: يا أبا أُمَامة، لقد كَبِرَتْ سِنِّي، ورقَّ عظمي، واقترب أجلي، وما بِي حاجة أن أَكْذِبَ على الله تعالى ، ولا على رسول الله صلى الله عليه وسلم لو لم أسمعه من رسول الله صلى الله عليه وسلم إلا مرة أو مرتين أو ثلاثًا -حتى عدَّ سبع مرات- ما حدَّثْت أبدًا به، ولكني سمعته أكثر من ذلك.","رواه مسلم","صحيح"]]],["شروط الصلاة",[["عن سلمة قال: كنا نصلي مع النبي صلى الله عليه وسلم المغرب إذا توارت بالحجاب.","متفق عليه","صحيح"],["عن جابر قال: رأيت النبي صلى الله عليه وسلم يصلي في ثوبٍ واحدٍ متوشِّحًا به.","متفق عليه","صحيح"],["عن عائشة قالت: قال النبي صلى الله عليه وسلم: \"إذا أحدث أحدكم في صلاته فليأخذ بأنفه ثم لينصرف\".","رواه أبو داود وابن ماجه","صحيح"],["عن عائشة رضي الله عنها عن النبي صلى الله عليه وسلم أنه قال: «لا يَقْبَل الله صلاة حَائض إلا بِخِمَار».","رواه أبو داود والترمذي وابن ماجه وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ما بَيْن المَشْرِق والمَغْرِب قِبْلة».","رواه الترمذي وابن ماجه ومالك","صحيح"],["عن رافع بن خديج رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «أَصْبِحُوا بالصبح؛ فإنه أعظم لِأُجُورِكُم، أو أعظم للأجر».","رواه أبو داود وابن ماجه وأحمد","صحيح"],["عن أبي مَرْثَدٍ الغَنَوِيّ رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «لَا تَجْلِسُوا عَلَى الْقُبُورِ، وَلَا تُصَلُّوا إِلَيْهَا».","رواه مسلم","صحيح"],["عن جابر رضي الله عنه قال: «كان رسول الله صلى الله عليه وسلم يُصلِّي على راحِلَته، حيث تَوَجَّهَت فإذا أراد الفَرِيضة نَزل فاسْتَقبل القِبْلة».","رواه البخاري","صحيح"],["عن رافع بن خَديج الأنصاري الأوسي رضي الله عنه قال: كنا نصلي المغرب مع النبي صلى الله عليه وسلم ، فينصرف أحدنا وإنه لَيُبْصِرُ مَوَاقِعَ نَبْلِهِ.","متفق عليه","صحيح"],["عن رافع بن خديج رضي الله عنه قال: كنا نصلي مع النبي صلى الله عليه وسلم العصر، فننحر جزورًا، فتُقسم عشرَ قِسَمٍ، فنأكل لحمًا نضيجًا قبل أن تغرب الشمس.","متفق عليه","صحيح"]]],["أركان الصلاة",[["عن عبادة بن الصامت رضي الله عنه قال: كُنَّا خَلْفَ رسول الله صلى الله عليه وسلم في صلاة الفجر فَقَرأ رسول الله صلى الله عليه وسلم ، فَثَقُلَتْ عليه القراءة، فلمَّا فَرَغَ قال: «لعلَّكم تَقْرَءُون خلف إِمَامِكُم» قلنا: نعم هذا يا رسول الله، قال: «لا تفعلوا إلا بفاتحة الكتاب فإنه لا صلاة لِمَنْ لم يَقْرَأ بها».","رواه أبو داود والترمذي وأحمد","حسن"]]],["سنن الصلاة",[["عن سهل بن سعد قال: «كان بين مُصلَّى رسول الله صلى الله عليه وسلم وبين الجدار ممر الشاة».","متفق عليه","صحيح"],["عن عبد الله بن السائب قال: رأيت النبي صلى الله عليه وسلم يصلي يومَ الفتح ووضع نعليه عن يساره.","رواه أبو داود والنسائي وابن ماجه وأحمد","صحيح"],["عن سَبْرة بن معبد الجهني رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إذا صلى أحدكم، فليسْتَتِر لصلاته، ولو بسهم».","رواه أحمد","صحيح"],["عن مَسْلَمَةَ سَعِيدِ بْنِ يَزِيد قال: سألت أنس بن مالك: أكان النبي صلى الله عليه وسلم يُصَلِّي في نَعْلَيْهِ؟ قال: «نعم».","رواه البخاري","صحيح"],["عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم: «يقطع الصلاة المرأة والحمار والكلب، ويَقِي ذلك مثل مُؤْخِرة الرَّحْل».","رواه مسلم","صحيح"],["عن سهل بن أبي حَثْمة قال: قال رسول الله صلى الله عليه وسلم: «إذا صلى أحدكم إلى سترة فليدن منها، لا يقطع الشيطان عليه صلاته».","رواه أبو داود والنسائي وأحمد","صحيح"],["عن جابر بن سمرة أن رسول الله صلى الله عليه وسلم كان يقرأ في الظهر والعصر بالسماء والطارق، والسماء ذات البروج، ونحوهما من السور.","رواه أبو داود والترمذي والنسائي","صحيح"],["عن ابن عباس قال: قرأ النبي صلى الله عليه وسلم فيما أُمر وسكت فيما أُمر، {وما كان ربك نسيا} [مريم: 64] {لقد كان لكم في رسول الله أسوة حسنة} [الأحزاب: 21].","رواه البخاري","صحيح"],["عن ابن عباس رضي الله عنهما أن رفع الصوت بالذكر حين ينصرف الناس من المكتوبة كان على عهد النبي صلى الله عليه وسلم. وقال: كنتُ أعلم إذا انصرفوا بذلك إذا سمعته.","متفق عليه","صحيح"]]],["صفة الصلاة",[["كان ابن عمر يَضع يديه قبل رُكْبَتَيِه، وقال: كان رسول الله صلى الله عليه وسلم يَفعل ذلك.","رواه ابن خزيمة","صحيح"],["عن جُبَيْرُ بْنُ مُطْعِم رضي الله عنه قال: «سمعت النبي صلى الله عليه وسلم يقرأ في المغرب بِالطُّور».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «اقتلوا الأسودَين في الصلاة: الحيَّة، والعقرب».","رواه أبو داود والترمذي والنسائي وابن ماجه وأحمد والدارمي","صحيح"],["عن وائل بن حجر رضي الله عنه قال: «صلَّيت مع رسول الله صلى الله عليه وسلم ، ووضع يَدَه اليُمْنَى على يَدِه اليُسْرى على صَدْرِه».","رواه ابن خزيمة","صحيح"],["عن أَنَس بن مالك رضي الله عنه عَنْ النَّبِيِّ صلى الله عليه وسلم قَالَ: «اعْتَدِلُوا في السجود، ولا يَبْسُطْ أحدكم ذِرَاعَيْهِ انْبِسَاطَ الكلب».","متفق عليه","صحيح"],["عن وائل بن حُجْر قال: كان رسول الله صلى الله عليه وسلم إذا قرأ {ولا الضالين} قال: \"آمين\" ورفع بها صوته. وفي رواية الترمذي: فقال: \"آمين\" ومد بها صوته.","رواه أبو داود والترمذي وابن ماجه","صحيح"],["عن عائشة رضي الله عنها قالت: ما رأيتُ النبي صلى الله عليه وسلم يقرأ في شيء من صلاة الليل جالسًا، حتى إذا كبر قرأ جالسًا، فإذا بقي عليه من السورة ثلاثون أو أربعون آية، قام فقرأهن، ثم ركع.","متفق عليه","صحيح"]]],["أذكار الصلاة",[["عن عائشة رضي الله عنها أنّ رسولَ اللهِ صلى الله عليه وسلم كانَ يقول في ركوعه وسجودِه: «سبُّوحٌ قُدُّوسٌ رَبُّ المَلاَئِكَةِ وَالرُّوحِ».","رواه مسلم","صحيح"],["عن البراء قال: كنا إذا صلينا خلف رسول الله صلى الله عليه وسلم أحببنا أن نكون عن يمينه، يُقبِلُ علينا بوجهه، قال: فسمعته يقول: «ربِّ قِنِي عذابَك يومَ تَبعث -أو تَجمع- عبادك».","رواه مسلم","صحيح"],["عن عقبة بن عامر قال: أمرني رسول الله صلى الله عليه وسلم أن أقرأ بالمعوِّذات دبر كل صلاة. ولفظ الترمذي: أمرني رسول الله صلى الله عليه وسلم أن أقرأ بالمعوِّذتين في دبر كل صلاة.","رواه أبو داود والترمذي والنسائي","صحيح"],["عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم لرجلٍ: \"ما تقول في الصلاة؟\" قال: أتشهد، ثم أسأل الله الجنة، وأعوذ به من النار، أَمَا والله ما أُحسن دَنْدَنَتَكَ ولا دَنْدَنَةَ معاذ. فقال: \"حولها نُدَنْدِنُ\".","رواه أبو داود وابن ماجه وأحمد","صحيح"],["عن أبي بكر الصديق رضي الله عنه: أنه قال لرسول الله صلى الله عليه وسلم: علمني دعاء أدعو به في صلاتي، قال: \"قل: اللهم إني ظلمت نفسي ظلما كثيرا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني إنك أنت الغفور الرحيم\".","متفق عليه","صحيح"],["عن أبي سعيد الخُدْرِي رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا قام من الليل كَبَّر، ثم يقول: «سُبْحَانك اللَّهم وبحَمْدِك وتبارك اسْمُك، وتعالى جَدُّك، ولا إله غَيْرك»، ثم يقول: «لا إله إلا الله» ثلاثا، ثم يقول: «الله أكبر كبيرا» ثلاثا، «أعُوذُ بالله السَّميع العليم من الشَّيطان الرَّجيم من هَمْزِه، ونَفْخِه، ونَفْثِه»، ثم يقرأ.","رواه أبو داود وابن ماجه والنسائي وأحمد","صحيح"],["عن ابن عمر قال: بينما نحن نصلي مع رسول الله صلى الله عليه وسلم إذ قال رجل من القوم: الله أكبر كبيرًا، والحمد لله كثيرًا، وسبحان الله بكرةً وأصيلًا، فقال رسول الله صلى الله عليه وسلم: «من القائلُ كلمة كذا وكذا؟» قال رجل من القوم: أنا، يا رسول الله. قال: «عجبتُ لها، فتحت لها أبواب السماء» قال ابن عمر: «فما تركتهن منذ سمعتُ رسول الله صلى الله عليه وسلم يقول ذلك».","رواه مسلم","صحيح"]]],["مبطلات الصلاة",[["عن أنس بن مالك: أن النبي صلى الله عليه وسلم كان يُشيرُ في الصلاة.","رواه أبو داود","صحيح"],["عن عائشة قالت: قال النبي صلى الله عليه وسلم: \"إذا أحدث أحدكم في صلاته فليأخذ بأنفه ثم لينصرف\".","رواه أبو داود وابن ماجه","صحيح"],["عن عبد الله بن زيد بن عاصم المازني رضي الله عنه قال: (شُكِيَ إلى النبيِّ صلى الله عليه وسلم الرَّجلُ يُخَيَّلُ إِليه أنَّه يَجِد الشَّيء في الصَّلاة، فقال: لا ينصرف حتَّى يَسمعَ صَوتًا، أو يَجِد رِيحًا).","متفق عليه","صحيح"]]],["أخطاء المصلين",[["عن أبي هريرة رضي الله عنه ، قال: «نهى النبي صلى الله عليه وسلم أن يصلي الرَّجُلُ مُخْتَصِرًا».","متفق عليه","صحيح"],["عن أبي رافع قال: رآني رسول الله صلى الله عليه وسلم وأنا ساجد، وقد عَقَصْتُ شعري -أو قال: عَقَدْت- فأطلقه.","رواه ابن أبي شيبة والدارمي","صحيح"],["عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم: «يقطع الصلاة المرأة والحمار والكلب، ويَقِي ذلك مثل مُؤْخِرة الرَّحْل».","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها قالت: سَألتُ رسول الله صلى الله عليه وسلم عن الالتِفَات في الصلاة؟ فقال: «هو اخْتِلاس يَختَلِسُهُ الشَّيطان من صلاة العَبْد».","رواه البخاري","صحيح"],["عن عَائِشَةَ رضيَ الله عنها قالت: إِنِّي سمعْتُ رسولَ الله صلى الله عليه وسلم يقول: «لَا صَلَاةَ بِحَضْرَةِ الطَّعَامِ، وَلَا هُوَ يُدَافِعُهُ الْأَخْبَثَانِ».","رواه مسلم","صحيح"],["عن أنس بن مالك رضي الله عنه عن النبي صلى الله عليه وسلم قال: «مَنْ نَسِيَ صَلَاةً فَلْيُصَلِّ إِذَا ذَكَرَهَا، لَا كَفَّارَةَ لَهَا إِلَّا ذَلِكَ: {وَأَقِمِ الصَّلاةَ لِذِكْرِي} [طه: 14]».","متفق عليه","صحيح"],["عن البراء بن عازب قال: كان رسول الله صلى الله عليه وسلم يتخلل الصف من ناحية إلى ناحية، يمسح صدورنا ومناكبنا ويقول: \"لا تختلفوا فتختلف قلوبكم\" وكان يقول: \"إن الله عز وجل وملائكته يصلون على الصفوف الأول\".","رواه أبو داود والنسائي وابن ماجه","صحيح"],["عن أبي ذر رضي الله عنه مرفوعًا: «إذا قام أَحَدُكُمْ إلى الصلاة؛ فإنَّ الرَّحمة تُوَاجِهُهُ، فلا يَمْسَح الحَصَى». وعن معيقيب رضي الله عنه أن النبي صلى الله عليه وسلم قال: في الرجل يُسَوِّي التُّراب حيث يسجُد، قال: «إِنْ كُنْت فاعِلا فَوَاحِدة».","حديث أبي ذر رواه أبو داود.\nحديث معيقيب متفق عليه","حديث أبي ذر ضعيف، وحديث معيقيب صحيح"],["عن عبد الله بن سَرْجِس قال: دخل رجل المسجد ورسول الله صلى الله عليه وسلم في صلاة الغداة، فصلى ركعتين في جانب المسجد، ثم دخل مع رسول الله صلى الله عليه وسلم، فلما سلم رسول الله صلى الله عليه وسلم قال: «يا فلان، بأي الصلاتين اعتددت؟ أبصلاتك وحدك، أم بصلاتك معنا؟».","رواه مسلم","صحيح"],["عن قيس بن طلق، قال: زارنا طلْق بن علي في يوم من رمضان، وأَمْسى عندنا، وأفطر، ثم قام بنا الليلة، وأَوْتَرَ بنا، ثم انحدر إلى مسجده، فصلى بأصحابه، حتى إذا بقي الوتر قَدَّمَ رجلا، فقال: أَوْتِرْ بأصحابك، فإني سمعت النبي صلى الله عليه وسلم يقول: «لا وِتْرَانِ في ليلة».","رواه أبو داود والترمذي والنسائي وأحمد","صحيح"]]],["سجود السهو والتلاوة والشكر",[["عن أبي هريرة قال: «سجدنا مع النبي صلى الله عليه وسلم في إذا السماء انشقت واقرأ باسم ربك».","رواه مسلم","صحيح"],["عن زيد بن ثابت رضي الله عنه قال: «قَرأت على النبي صلى الله عليه وسلم والنَّجم فلم يسجد فيها».","رواه البخاري","صحيح"],["عن ابن عباس رضي الله عنهما قال: «ص ليس من عَزَائِمِ السُّجود، وقد رأيت النبي صلى الله عليه وسلم يَسجد فيها».","رواه البخاري","صحيح"],["عن أبي بكرة، عن النبي صلى الله عليه وسلم أنه كان «إذا جاءه أمرُ سرورٍ، أو بُشِّرَ به خَرَّ ساجدًا شاكرًا لله».","رواه أبو داود وابن ماجه والترمذي وأحمد","صحيح"],["عن ابن عمر رضي الله عنهما قال: «كان النبي صلى الله عليه وسلم يقرأ علينا السورة فيها السجدة، فيسجد ونسجد، حتى ما يجد أحدنا موضع جبهته».","متفق عليه","صحيح"],["عن أبي رافع أن أبا هريرة رضي الله عنه قرأ لهم: «إذا السماء انْشَقَّتْ» فسجد فيها، فلما انصَرَفَ أخبرهم أن رسول الله صلى الله عليه وسلم سجد فيها.","متفق عليه","صحيح"],["عن عُقْبَة بن عامر رضي الله عنه قال: قلت لرسول الله صلى الله عليه وسلم : أفِي سورة الحج سَجدَتَان؟ قال: «نعم، ومن لم يَسْجُدْهما؛ فلا يَقْرَأْهما».","رواه أبو داود","صحيح"],["عن عبد الله بن مسعود رضي الله عنه قال: \"قرأ النبي صلى الله عليه وسلم النجم بمكة، فسجد فيها وسجد مَن معه غير شيخ أخذ كفًّا من حصى أو تراب فرفعه إلى جبهته وقال: يكفيني هذا \"، فرأيته بعد ذلك قتل كافرًا.","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إذا قَرَأ ابنُ آدم السجدةَ فسجد اعْتَزَل الشيطانُ يبكي، يقول: يا وَيْلَه -وفي روايةٍ: يا وَيْلي- أُمِر ابنُ آدمَ بالسجودِ فسجدَ فله الجنة، وأُمِرتُ بالسجود فأبَيْتُ فَلِيَ النارُ».","رواه مسلم","صحيح"],["عن زياد بن علاقة قال: صَلَّى بِنَا المغيرة بنُ شُعْبَةَ فَنَهَضَ في الركعتين، قلنا: سبحان الله، قال: سبحان الله وَمَضَى، فَلَمَّا أَتَمَّ صَلَاتَهُ وَسَلَّمَ، سَجَدَ سَجْدَتَيِ السَّهْوِ، فَلَمَّا انْصَرَفَ، قَالَ: «رَأَيْتُ رسول الله صلى الله عليه وسلم يَصْنَعُ كَمَا صَنَعْتُ».","رواه أبو داود والترمذي وأحمد والدارمي","صحيح"],["عن عبد الله بن بُحَيْنَةَ رضي الله عنه وكان من أصحاب النبي صلى الله عليه وسلم «أن النبي صلى الله عليه وسلم صلَّى بهم الظهر فقام في الركعتين الأُولَيَيْنِ، ولم يَجْلِسْ، فقام الناس معه، حتى إذا قضى الصلاة وانتظر الناس تسليمه: كَبَّرَ وهو جالس فسجد سجدتين قبل أن يُسَلِّمَ ثُمَّ سَلَّمَ».","متفق عليه","صحيح"]]],["فضل صلاة الجماعة وأحكامها",[["عن أبي سعيد الخدري أن رسول الله صلى الله عليه وسلم أبصر رجلًا يصلي وحده فقال: \"أَلَا رجلٌ يتصدق على هذا فيصلي معه\".","رواه أبو داود والترمذي","صحيح"],["عن ابن عباس رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «من سمِع النِّدَاء فلم يَأتِه؛ فلا صلاة له إلا من عُذْر».","رواه ابن ماجه","صحيح"],["عن عبد الله بن عمر رضي الله عنهما أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ: «صلاةُ الجَمَاعَة أَفضَلُ من صَلاَة الفَذِّ بِسَبعٍ وعِشرِين دَرَجَة».","متفق عليه","صحيح"],["عن أبي موسى قال: قال النبي صلى الله عليه وسلم: «أعظم الناس أجرًا في الصلاة أبعدهم فأبعدهم ممشى، والذي ينتظر الصلاة حتى يصليها مع الإمام أعظم أجرًا من الذي يصلي ثم ينام».","متفق عليه","صحيح"],["عن أبي هريرة قال: أقيمت الصلاة وعدلت الصفوف قيامًا، فخرج إلينا رسول الله صلى الله عليه وسلم، فلما قام في مصلاه، ذكر أنه جنب، فقال لنا: «مكانكم» ثم رجع فاغتسل، ثم خرج إلينا ورأسه يقطر، فكبر فصلينا معه.","متفق عليه","صحيح"],["عن البراء بن عازب قال: كان رسول الله صلى الله عليه وسلم يتخلل الصف من ناحية إلى ناحية، يمسح صدورنا ومناكبنا ويقول: \"لا تختلفوا فتختلف قلوبكم\" وكان يقول: \"إن الله عز وجل وملائكته يصلون على الصفوف الأول\".","رواه أبو داود والنسائي وابن ماجه","صحيح"],["عن أم سلمة رضي الله عنها قالت: كان رسول الله صلى الله عليه وسلم إذا سلم قام النساء حين يقضي تسليمه، ومكث يسيرًا قبل أن يقوم. قال ابن شهاب: فأرى والله أعلم أن مكثه لكي ينفذ النساء قبل أن يدركهن من انصرف من القوم.","رواه البخاري","صحيح"],["عن عبد الله بن عمر أن رسول الله صلى الله عليه وسلم قال: \"أقيموا الصفوف، وحاذوا بين المناكب، وسُدُّوا الخَلَلَ، ولِيْنُوا بأيدي إخوانكم، ولا تذروا فُرُجاتٍ للشيطان، ومن وصل صفًّا وصله الله، ومن قطع صفًّا قطعه الله\".","رواه أبو داود","صحيح"]]],["أحكام الإمام والمأموم",[["عن أنس رضي الله عنه : أن النبي صلى الله عليه وسلم اسْتَخْلَفَ ابن أُمِّ مَكْتُومٍ يَؤُم الناس وهو أعْمَى.","رواه أبو داود واللفظ له وأحمد","صحيح"],["عن أنس بن مالك قال: أقيمت الصلاة والنبي صلى الله عليه وسلم يناجي رجلًا في جانب المسجد، فما قام إلى الصلاة حتى نام القوم.","متفق عليه","صحيح"],["عن أَنَس بن مالك رضي الله عنه مرفوعاً: «ما صَلَّيْتُ خلف إمام قَطُّ أَخَفَّ صلاة، ولا أَتَمَّ صلاة من النبي صلى الله عليه وسلم ».","متفق عليه","صحيح"],["عن أنس بن مالك رضي الله عنه ، قال: «صَلَّيْتُ أنا ويَتِيمٌ، في بَيْتِنَا خَلْف النبي صلى الله عليه وسلم ، وَأُمِّي أُمُّ سُليم خَلْفَنَا».","متفق عليه، واللفظ للبخاري","صحيح"],["أن رسول الله صلى الله عليه وسلم رأى في أصحابه تأخُّرًا فقال لهم: «تَقَدَّمُوا فَأْتَمُّوا بي، وليأتمَّ بكم مَن بعدكم، لا يزال قومٌ يتأخرون حتى يؤخرَّهم اللهُ».","رواه مسلم","صحيح"],["عن عبد الله بن مسعود أنه قال: لا يجعلْ أحدُكم للشيطان شيئًا من صلاته، يَرَى أن حقًّا عليه ألا ينصرف إلا عن يمينه، لقد رأيت النبي صلى الله عليه وسلم كثيرًا ينصرف عن يساره.","متفق عليه","صحيح"]]],["صلاة أهل الأعذار",[["عن عائشة رضي الله عنها قالت: رأيت رسول الله صلى الله عليه وسلم يصلِّي متربِّعًا.","رواه النسائي","صحيح"],["عن أنس أن رسول الله صلى الله عليه وسلم صلى الظهر بالمدينة أربعًا، وصلى العصر بذي الحليفة ركعتين.","متفق عليه","صحيح"],["عن أم قيس بنت مِحْصن: أن رسول الله صلى الله عليه وسلم لما أَسَنَّ وحمل اللحم اتخذ عمودًا في مصلاه يعتمد عليه.","رواه أبو داود","صحيح"],["عن ابن عباس قال: فرض الله الصلاة على لسان نبيكم صلى الله عليه وسلم في الحضر أربعًا، وفي السفر ركعتين، وفي الخوف ركعة.","رواه مسلم","صحيح"],["عن معاذ قال: خرجنا مع رسول الله صلى الله عليه وسلم في غزوة تبوك، فكان يصلي الظهر والعصر جميعًا، والمغرب والعشاء جميعًا.","رواه مسلم","صحيح"],["عن ابن عباس رضي الله عنهما قال: أقام النبي صلى الله عليه وسلم تسعة عشر يقصر، فنحن إذا سافرنا تسعة عشر قصرنا، وإن زدنا أتممنا.","رواه البخاري","صحيح"],["عن عبد الله بن عمر رضي الله عنهما قال: صليتُ مع النبي صلى الله عليه وسلم بمنى ركعتين، وأبي بكر، وعمر ومع عثمان صدرًا من إمارته ثم أتمها.","متفق عليه","صحيح"],["عن ابن عباس قال: صلى رسول الله صلى الله عليه وسلم الظهر والعصر جميعا بالمدينة، في غير خوف ولا سفر. وفي رواية: بالمدينة، في غير خوف ولا مطر.","رواه مسلم","صحيح"],["عن ابن عمر رضي الله عنهما ، قال: «جمع رسول الله صلى الله عليه وسلم بين المغرب والعشاء بجمع: صلى المغرب ثلاثاً، والعشاء ركعتين، بإقامة واحدة».","رواه مسلم","صحيح"],["عن عبد الله بن عُمر رضي الله عنهما قال: «صحبت رسول الله صلى الله عليه وسلم فكان لا يزيد في السَّفَر على ركعتين، وأبا بكر وعُمر وعُثْمان كذلك».","متفق عليه","صحيح"]]],["صلاة الجمعة",[["عن أنس بن مالك رضي الله عنه أن النبي صلى الله عليه وسلم كان يصلي الجمعة حين تميل الشمس.","رواه البخاري","صحيح"],["عن جابر بن سمرة قال: كانت للنبي صلى الله عليه وسلم خطبتان يجلس بينهما يقرأ القرآن، ويذكر الناس.","رواه مسلم","صحيح"],["عن أبي عبد الله جابر بن سمرة رضي الله عنهما قال: كنت أصلي مع النبي صلى الله عليه وسلم الصلوات، فكانت صلاته قَصْدًا وخطبته قَصْدًا.","رواه مسلم","صحيح"],["عن طارق بن شهاب عن النبي صلى الله عليه وسلم قال: \"الجمعة حق واجب على كل مسلم في جماعة إلا أربعة: عبد مملوك أو امرأة أو صبي أو مريض\".","رواه أبو داود","صحيح"],["عن جابر بن عبد الله رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم وهو يخطب: «إذا جاء أحدكم والإمام يخطب أو قد خرج فليصل ركعتين».","متفق عليه","صحيح"],["عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم: «إذا صليتم بعد الجمعة فصلُّوا أربعًا، فإن عَجِلَ بك شيءٌ فَصَلِّ ركعتين في المسجد، وركعتين إذا رجعت».","رواه مسلم","صحيح"],["عن عَبْدِ اللهِ بْنِ عُمَرَ رضي الله عنهما قَالَ: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ: «‌مَنْ ‌جَاءَ ‌مِنْكُمُ ‌الْجُمُعَةَ فَلْيَغْتَسِلْ».","متفق عليه","صحيح"],["عن أبِي هُرَيرةَ رضي الله عنه أنَّ رسول الله صلى الله عليه وسلمَ قال: «إذا قُلْتَ لِصَاحِبِكَ: أَنْصِتْ، يومَ الجمعةِ، والْإِمامُ يَخْطُبُ، فَقَدْ لَغَوْتَ».","متفق عليه","صحيح"],["عن جابر بن عبد الله عن رسول الله صلى الله عليه وسلم قال: «يوم الجمعة ثنتا عشرة -يريد ساعة- لا يوجد مسلم يسأل الله شيئًا إلا آتاه إياه، فالتمسوها آخر ساعة بعد العصر».","رواه أبو داود والنسائي","صحيح"],["عن أبي هريرة أن رسول الله صلى الله عليه وسلم ذكر يوم الجمعة، فقال: «فيه ساعة، لا يوافقها عبدٌ مسلمٌ، وهو قائم يصلي، يسأل الله تعالى شيئًا، إلا أعطاه إياه» وأشار بيده يقللها.","متفق عليه","صحيح"],["عن جابِر بن عبد الله رضي الله عنهما قال: «جاء رجل والنبي صلى الله عليه وسلم يَخْطُبُ الناس يوم الجمعة، فقال: صليت يا فلان؟ قال: لا، قال: قم فاركع ركعتين، -وفي رواية: فصل ركعتين-».","متفق عليه","صحيح"],["عن أبي هريرة عن النبي صلى الله عليه وسلم قال: «من اغتسل ثم أتى الجمعة، فصلى ما قدر له، ثم أنصت حتى يفرغ من خطبته، ثم يصلي معه، غفر له ما بينه وبين الجمعة الأخرى، وفضل ثلاثة أيام».","رواه مسلم","صحيح"]]],["صلاة التطوع",[["عن ابن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم قال: «بادروا الصبح بالوتر».","رواه مسلم","صحيح"],["عن أبي سعيد الخدري رضي الله عنه أن النبي صلى الله عليه وسلم قال: «أَوْتِرُوا قبل أن تُصبحِوُا».","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان يَنَام أول اللَّيل، ويقوم آخره فَيُصلِّي.","متفق عليه","صحيح"],["عن ابن عمر رضي الله عنهما ، عن النبي صلى الله عليه وسلم قال: «صلاة الليل والنَّهار مثْنَى مثْنَى».","رواه أبو داود وأحمد والترمذي والنسائي وابن ماجه","صحيح"],["عن علي رضي الله عنه : أن النبي صلى الله عليه وسلم طَرَقَه وفاطمة ليلاً، فقال: «ألا تُصَلِّيَانِ؟».","متفق عليه","صحيح"],["عن عبد الله بن عُمر رضي الله عنهما قال: «كان النبي صلى الله عليه وسلم وأبو بكر وعُمر يصلون العيدين قبل الخُطْبة».","متفق عليه","صحيح"],["عن عائشة رضي الله عنها ، قالت: «كان النبي صلى الله عليه وسلم يصلي من الليل ثلاث عشرة ركعة منها الوِتر، وركعتا الفجر».","متفق عليه","صحيح"],["عن عائشةَ أُمِّ المُؤْمِنينَ رضي الله عنها: أن النبي صلى الله عليه وسلم كان لا يَدع أربعا قَبل الظهر وركعتين قبل الغَدَاة.","رواه البخاري","صحيح"],["عن حفصة رضي الله عنها «أن النبي صلى الله عليه وسلم كان يُصلي ركعتين خَفيفتين بعد ما يَطلع الفجر»، وفي رواية: قبل أن تُقام الصلاة.","رواه البخاري","صحيح"],["عن عائشة رضي الله عنها قالت: «من كلِّ الليل أَوْتَرَ رسول الله صلى الله عليه وسلم : من أول الليل، وأوسطه، وآخره، وانتهى وِتْرُهُ إلى السَّحَرِ».","متفق عليه","صحيح"]]],["صلاة الخوف",[["عن ابن عباس قال: فرض الله الصلاة على لسان نبيكم صلى الله عليه وسلم في الحضر أربعًا، وفي السفر ركعتين، وفي الخوف ركعة.","رواه مسلم","صحيح"],["عن عبد الله بن عمر أن رسول الله صلى الله عليه وسلم صلى بإحدى الطائفتين، والطائفة الأخرى مواجهة العدو، ثم انصرفوا فقاموا في مقام أصحابهم أولئك، فجاء أولئك، فصلى بهم ركعة، ثم سلم عليهم، ثم قام هؤلاء فقضوا ركعتهم، وقام هؤلاء فقضوا ركعتهم.","متفق عليه","صحيح"],["عن عبد الله بن عمر بن الخطاب رضي الله عنهما قال: « صَلَّى بنا رسولُ الله صلى الله عليه وسلم صلاة الخوف في بعض أيامه، فقامت طائفة معه، وطائفة بِإِزَاءِ العدو، فصلَّى بالذين معه ركعة، ثم ذهبوا، وجاء الآخرون، فصَلَّى بهم ركعة، وقَضَتِ الطائفتان ركعة ركعة».","متفق عليه","صحيح"],["عن صالح بن خَوَّاتِ بْنِ جُبَيْرٍ رضي الله عنه عمّن صلَّى مع رسول الله صلى الله عليه وسلم صلاة ذَاتِ الرِّقَاعِ صلاةَ الخوف: أن طائفة صفَّت معه، وطائفة وِجَاهَ الْعَدُوِّ، فصلَّى بالذين معه ركعة، ثم ثبت قائما، وأتموا لأنفسهم، ثم انصرفوا، فصفُّوا وِجَاهَ الْعَدُوِّ، وجاءت الطائفة الأخرى، فصلَّى بهم الركعة التي بقيت، ثم ثبت جالسا، وأتموا لأنفسهم، ثم سلَّم بهم.","متفق عليه","صحيح"],["عن جابر قال: غزونا مع رسول الله صلى الله عليه وسلم قومًا من جهينة، فقاتلونا قتالًا شديدًا، فلما صلينا الظهر قال المشركون: لو ملنا عليهم ميلة لاقتطعناهم، فأخبر جبريل رسول الله صلى الله عليه وسلم ذلك، فذكر ذلك لنا رسول الله صلى الله عليه وسلم، قال: وقالوا: إنه ستأتيهم صلاة هي أحب إليهم من الأولاد. فلما حضرت العصر قال: صفنا صفين، والمشركون بيننا وبين القبلة، قال: فكبر رسول الله صلى الله عليه وسلم وكبرنا، وركع فركعنا، ثم سجد، وسجد معه الصف الأول، فلما قاموا سجد الصف الثاني، ثم تأخر الصف الأول، وتقدم الصف الثاني، فقاموا مقام الأول، فكبر رسول الله صلى الله عليه وسلم، وكبرنا، وركع، فركعنا، ثم سجد وسجد معه الصف الأول، وقام الثاني، فلما سجد الصف الثاني، ثم جلسوا جميعًا، سلم عليهم رسول الله صلى الله عليه وسلم.","رواه مسلم","صحيح"],["عن جابر بن عبد الله الأنصاري رضي الله عنهما قال: «شَهِدْتُ مع رسول الله صلى الله عليه وسلم صلاة الخوف فَصَفَفْنَا صَفَّيْنِ خلف رسول الله صلى الله عليه وسلم والعدو بيننا وبين القبلة، وكَبَّرَ النبي صلى الله عليه وسلم وكَبَّرنا جميعا، ثم ركع ورَكَعْنا جميعا، ثم رفع رأسه من الركوع ورفعنا جميعا، ثم انحدر بالسجود والصف الذي يليه، وقام الصَّفُّ الْمُؤَخَّرُ في نَحْرِ الْعَدُوِّ، فلما قضى النبي صلى الله عليه وسلم السجود، وقام الصفّ الذي يليه انْحَدَرَ الصَّفُّ الْمُؤَخَّرُ بالسجود، وقاموا، تَقَدَّمَ الصَّفُّ الْمُؤَخَّرُ، وَتَأَخَّرَ الصَّفُّ الْمُقَدَّمُ، ثم ركع النبي صلى الله عليه وسلم وركعنا جميعا، ثم رفع رأسه من الركوع ورفعنا جميعا، ثم انحدر بالسجود، والصفّ الذي يليه -الذي كان مُؤَخَّرا في الركعة الأولى- فقام الصَّفُّ الْمُؤَخَّرُ فِي نَحْرِ الْعَدُوِّ، فلما قضى النبي صلى الله عليه وسلم السجود والصف الذي يليه: انْحَدَرَ الصَّفُّ الْمُؤَخَّرُ بالسجود، فسجدوا ثم سلَّم صلى الله عليه وسلم وسَلَّمْنا جميعا، قال جابر: كما يصنع حَرَسُكُمْ هؤلاء بأُمرائهم». وذكر البخاري طرفا منه: «وأنه صلى صلاة الخوف مع النبي صلى الله عليه وسلم في الغزوة السابعة، غزوة ذات الرِّقَاعِ».","متفق عليه","صحيح"]]],["صلاة الكسوف والخسوف",[["عن عائشة رضي الله عنها «أن الشمس خَسَفَتْ على عهد رسول الله صلى الله عليه وسلم فبعث مُناديا ينادي: الصلاة جامعة، فاجْتَمَعوا، وتقَدَّم، فكَبَّر وصلَّى أربعَ ركعات في ركعتين، وأربعَ سجَدَات».","متفق عليه","صحيح"],["عن أبي موسى الأشعري رضي الله عنه قال: خَسَفَت الشمس على زمان رسول الله صلى الله عليه وسلم . فقام فَزِعًا، ويخشى أن تكون الساعة، حتى أتى المسجد، فقام، فصلى بأطول قيام وسجود، ما رأيته يفعله في صلاته قطُّ، ثم قال: إن هذه الآيات التي يُرْسِلُهَا الله عز وجل : لا تكون لموت أحد ولا لحياته، ولكن الله يُرْسِلُهَا يُخَوِّفُ بها عباده، فإذا رأيتم منها شيئا فَافْزَعُوا إلى ذكر الله و دُعَائِهِ وَاسْتِغْفَارِهِ.","متفق عليه","صحيح"],["عن أسماء بنت أبي بكر رضي الله عنهما قالت: كَسَفَتِ الشمسُ على عهد النبي صلى الله عليه وسلم، ففزع فأَخطأَ بدِرْعٍ حتى أُدرِكَ بردائه بعد ذلك، قالت: فقضيت حاجتي، ثم جئت ودخلت المسجد، فرأيت رسول الله صلى الله عليه وسلم قائمًا، فقمتُ معه، فأطال القيام، حتى رأيتني أريد أن أجلس، ثم أَلْتَفِتُ إلى المرأة الضعيفة، فأقول: هذه أضعف مني، فأقوم، فركع فأطال الركوع، ثم رفع رأسه فأطال القيام، حتى لو أن رجلًا جاء خُيِّل إليه أنه لم يركع.","متفق عليه","صحيح"],["عن عائشة رضي الله عنها قالت: « خَسَفَتِ الشمس على عهد رسول الله صلى الله عليه وسلم فصَلَّى رسول الله صلى الله عليه وسلم بالناس. فأطال القيام، ثم ركع، فأطال الركوع، ثم قام، فأطال القيام -وهو دون القيام الأول- ثم ركع، فأطال الركوع -وهو دون الركوع الأول- ثم رفع فأطال القيام -وهو دون القيام الأول- ثم سجد، فأطال السجود، ثم فعل في الركعة الأخرى مثل ما فَعَل في الرَّكعة الأولى، ثم انصرف، وقد تَجَلَّتْ الشمس، فخَطَب الناس، فحَمِد الله وأَثْنَى عليه، ثُمَّ قال: إِنَّ الشَّمس والقمَر آيَتَان مِن آيات الله، لا ينْخَسِفَانِ لموت أحد ولا لِحَيَاته، فَإِذا رَأَيتُم ذلك فَادْعُوا اللَّه وكَبِّرُوا ، وصَلُّوا وتَصَدَّقُوا. ثم قال: يا أُمَّة مُحمَّد، واللهِ ما من أحد أغْيَرُ من الله أن يَزْنِيَ عبده أو تَزْنِيَ أَمَتُهُ. يا أُمَّةَ محمد، والله لو تعلمون ما أعلم لَضَحِكْتُمْ قليلا ولَبَكَيْتم كثيرا». وفي لفظ: «فاسْتَكَمَل أَرْبَع رَكَعَاتٍ وَأَرْبَع سَجَدَاتٍ».","متفق عليه","صحيح"]]],["صلاة الاستسقاء",[["عن أنس بن مالك أن النبي صلى الله عليه وسلم استسقى، فأشار بظهر كفيه إلى السماء.","رواه مسلم","صحيح"],["عن أنس بن مالك قال: كان النبي صلى الله عليه وسلم لا يرفع يديه في شيء من دعائه إلا في الاستسقاء، وإنه يرفع حتى يرى بياض إبطيه.","متفق عليه","صحيح"],["عن أبي هريرة أن رسول الله صلى الله عليه وسلم قال: «ليست السَّنَة بألا تمطروا، ولكن السنة أن تمطروا وتمطروا، ولا تنبت الأرض شيئًا».","رواه مسلم","صحيح"],["عن عبد الله بن زيد بن عَاصِم المازِنِي رضي الله عنه قال: «خرج النبي صلى الله عليه وسلم يَسْتَسْقِي، فتَوَجَّه إلى القبلة يدْعو، وحَوَّل رِدَاءه، ثم صلَّى ركعتين، جَهَرَ فيهما بالقِراءة». وفي لفظ «إلى الْمُصَلَّى».","متفق عليه","صحيح"],["عن عبد الله بن عمرو بن العاص قال: كان رسول الله صلى الله عليه وسلم إذا استسقى قال: \"اللهم اسق عبادك وبهائمك، وانشر رحمتك، وأحي بلدك الميت\".","رواه أبو داود","حسن"]]],["أحكام المساجد",[["عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «البُزَاق في المسجد خَطيئة، وَكَفَّارَتُهَا دَفْنُها».","رواه البخاري","صحيح"],["عن عائشة رضي الله عنها قالت: أَمَر رسول الله صلى الله عليه وسلم بِبناء المساجد في الدُّورِ، وأن تُنظَّف، وتُطيَّب.","رواه أبو داود","صحيح"],["عن عبد الله بن الحارث بن جَزء الزَّبيدي يقول: كنا نأكل على عهد رسول الله صلى الله عليه وسلم في المسجد الخبز واللحم.","رواه ابن ماجه","صحيح"],["عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم: «مَن أكل مِن هذه الشجرة فلا يقربن مسجدنا، ولا يؤذينا بريح الثوم».","رواه مسلم","صحيح"],["عن جابر بن عبد الله أن رسول الله صلى الله عليه وسلم قال: \"من بنى مسجدًا لله كمَفْحَص قطاة، أو أصغر، بنى الله له بيتا في الجنة\".","رواه ابن ماجه","صحيح"],["عن عبد الله عن النبي صلى الله عليه وسلم قال: \"صلاة المرأة في بيتها أفضل من صلاتها في حجرتها، وصلاتها في مخدعها أفضل من صلاتها في بيتها\".","رواه أبو داود","صحيح"],["عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم: «اللهُمَّ لَا تَجْعَلْ قَبْرِي وَثَنًا، لَعَنَ اللهُ قَوْمًا اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ».","رواه أحمد","صحيح"],["عن ابن عباس رضي الله عنهما ، قال: قال رسول الله صلى الله عليه وسلم : «ما أُمِرْتُ بِتَشْيِيد المساجد»، قال ابن عباس: لتُزَخْرِفُنَّها كما زَخْرَفَت اليهود والنصارى.","رواه أبو داود","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من سمِع رجُلا يَنْشُدُ ضَالَّةً في المسجد فليقُل: لا رَدَّهَا الله عليك، فإنَّ المساجد لم تُبْنَ لهذا».","رواه مسلم","صحيح"],["عن بُريدة رضي الله عنه : أن رجُلاً نَشَدَ في المسجد فقال: من دَعَا إلى الجَمَل الأحمر؟ فقال رسول الله صلى الله عليه وسلم : «لا وجَدْتَ؛ إنما بُنِيَتِ المساجد لما بُنِيَتْ له».","رواه مسلم","صحيح"]]]]],["الطهارة",0,[["أحكام المياه",[["عن عبد الله بن عباس رضي الله عنهما أن النبي صلى الله عليه وسلم كان يغتسل بفضل ميمونة رضي الله عنها .","رواه مسلم","صحيح"],["عن أبي سعيد الخدري رضي الله عنه أنه قيل لرسول الله صلى الله عليه وسلم : أنتوضأ من بِئر بُضَاعَةَ وهي بئر يُطرحُ فيها الحَيضُ ولحم الكلاب والنَّتَنُ؟ فقال رسول الله صلى الله عليه وسلم : «الماء طهور لا ينجسه شيء».","رواه أبو داود والنسائي وأحمد","صحيح"],["عن عبد الله بن عباس رضي الله عنهما قال: اغتسل بعض أزواج النبي صلى الله عليه وسلم في جَفْنَةٍ، فجاء النبي صلى الله عليه وسلم ليتوضأ منها أو يغتسل، فقالت: له يا رسول الله، إني كنت جُنُبًا؟ فقال رسول الله صلى الله عليه وسلم : «إن الماء لا يَجْنُبُ».","رواه أبو داود والترمذي وابن ماجه","صحيح"]]],["إزالة النجاسات",[["عن عبد الله بن عباس قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إذا دبغ الإهاب فقد طَهُرَ».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إذا وَطِئَ الأَذَى بِخُفَّيْه، فَطَهُورُهُمَا التُّرَاب».","رواه أبو داود","صحيح"],["عن ابن عباس عن ميمونة أن رسول الله صلى الله عليه وسلم سئل عن فأرة سقطت في سمن فقال: «ألقوها وما حولها فاطرحوه، وكلوا سمنكم».","رواه البخاري","صحيح"],["عن عائشة زوج النبي صلى الله عليه وسلم أن رسول الله صلى الله عليه وسلم كان يُؤْتَى بالصبيان فيُبرِّكُ عليهم ويُحنِّكُهم، فأتي بصبي فبال عليه، فدعا بماء، فأتبعه بوله ولم يغسله.","رواه مسلم","صحيح"],["عن أسماءَ رضي الله عنها قالت: جاءت امرأةٌ النبيَّ صلى الله عليه وسلم فقالت: أرأَيْتَ إحدانا تَحِيضُ في الثَّوب، كيف تصنعُ؟ قال: «تَحُتُّهُ، ثم تَقْرُصُه بالماء، وتَنْضَحُه، وتُصَلِّي فيه».","متفق عليه","صحيح"],["عَنْ أَبِي هُرَيْرَةَ رضي الله عنه قَالَ: إِنَّ رَسُولَ اللهِ صلى الله عليه وسلم قَالَ: «إِذَا شَرِبَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعًا». ولمسلم: « أولاهُنَّ بالتُراب».","متفق عليه","صحيح"],["عن أنس بن مالك رضي الله عنه قال: «جاء أعرابِيُّ، فبَالَ في طَائِفَة المَسجد، فَزَجَرَه النَّاسُ، فَنَهَاهُمُ النبِيُّ صلى الله عليه وسلم فَلمَّا قَضَى بَولَه أَمر النبي صلى الله عليه وسلم بِذَنُوب من ماء، فَأُهرِيقَ عليه».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: بال أعرابي في المسجد، فقام الناس إليه لِيَقَعُوا فيه، فقال النبي صلى الله عليه وسلم : «دعوه وأريقوا على بوله سَجْلاً من ماء، أو ذَنُوبًا من ماء، فإنما بُعِثْتُمْ مُيَسِّرِينَ، ولم تُبْعَثُوا مُعَسِّرِينَ».","متفق عليه، واللفظ للبخاري","صحيح"],["عن أبي السَّمْح قال: كنت أخْدُم النبي صلى الله عليه وسلم ، فكان إذا أراد أن يغتسل قال: «وَلِّني قَفَاك». فأوَلِّيه قَفَايَ فأَسْتُره به، فأُتِيَ بحسن أو حسين رضي الله عنهما فَبَال على صدره فجئتُ أغسله فقال: «يُغسَلُ مِنْ بوْل الجاريَة، ويُرَشُّ مِنْ بوْل الغُلام».","رواه أبو داود والنسائي وابن ماجه","صحيح"],["عن أسماء بنت أبي بكر الصديق أنها قالت: سألت امرأة رسول الله صلى الله عليه وسلم فقالت: يا رسول الله، أرأيت إحدانا إذا أصاب ثوبها الدم من الحيضة كيف تصنع؟ فقال رسول الله صلى الله عليه وسلم: «إذا أصاب ثوبَ إحداكن الدمُ من الحَيضة فلتقرُصْه، ثم لتنضَحه بماء، ثم لتصلي فيه».","متفق عليه","صحيح"],["عن كبشة بنت كعب بن مالك -وكانت تحت ابن أبي قتادة-: أن أبا قتادة دخل فسَكَبَتْ له وَضُوءًا، فجاءت هرة فشربت منه، فأصغى لها الإناء حتى شربت، قالت كبشة: فرآني أنظر إليه، فقال: أتعجبين يا ابنة أخي؟ فقلت: نعم، فقال: إن رسول الله صلى الله عليه وسلم قال: «إنها ليست بنجس، إنها من الطوافين عليكم والطوافات».","رواه أبو داود والترمذي والنسائي وأحمد والدارمي","صحيح"]]],["الآنية",[["عن أنس بن مالك رضي الله عنه أن قَدَحَ النبي صلى الله عليه وسلم انْكَسَرَ، فاتَّخَذَ مكان الشَّعْبِ سِلْسِلَةً من فِضة.","رواه البخاري","صحيح"],["عن أم سلمة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم : «مَنْ شَرِبَ وفي رواية: «إنَّ الذي يَأكُل أو يَشرَب» في إناءٍ من ذهبٍ أو فضةٍ، فإنما يُجَرْجِرُ في بطنه نارًا مِن جهنَّم».","متفق عليه","صحيح"],["عَنْ أَبِي هُرَيْرَةَ رضي الله عنه قَالَ: إِنَّ رَسُولَ اللهِ صلى الله عليه وسلم قَالَ: «إِذَا شَرِبَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعًا». ولمسلم: « أولاهُنَّ بالتُراب».","متفق عليه","صحيح"],["عن ابن عباس رضي الله عنهما قال: وجد النبي صلى الله عليه وسلم شاةً ميتةً أُعْطِيَتْها مولاة لميمونة من الصدقة، فقال النبي صلى الله عليه وسلم: «هلَّا انتفعتم بجلدها؟» قالوا: إنها ميتة، قال: «إنما حَرُمَ أكلُها».","متفق عليه","صحيح"],["عن كبشة بنت كعب بن مالك -وكانت تحت ابن أبي قتادة-: أن أبا قتادة دخل فسَكَبَتْ له وَضُوءًا، فجاءت هرة فشربت منه، فأصغى لها الإناء حتى شربت، قالت كبشة: فرآني أنظر إليه، فقال: أتعجبين يا ابنة أخي؟ فقلت: نعم، فقال: إن رسول الله صلى الله عليه وسلم قال: «إنها ليست بنجس، إنها من الطوافين عليكم والطوافات».","رواه أبو داود والترمذي والنسائي وأحمد والدارمي","صحيح"],["عن عاصم الأحول، قال: رأيت قَدَحَ النبي صلى الله عليه وسلم عند أنس بن مالك، وكان قد انصدع فسلسله بفضة، قال: وهو قدح جيد عريض من نُضَارٍ، قال: قال أنس: لقد سقيت رسول الله صلى الله عليه وسلم في هذا القدح أكثر من كذا وكذا. قال: وقال ابن سيرين: إنه كان فيه حلْقة من حديد، فأراد أنس أن يجعل مكانها حلْقة من ذهب أو فضة، فقال له أبو طلحة: لا تُغَيِّرَنَّ شيئًا صنعه رسول الله صلى الله عليه وسلم فتركه.","رواه البخاري","صحيح"],["عن العالية بنت سُبَيع قالت: كان لي غنم بأُحُدٍ، فوقَع فيها الموت، فدَخَلْتُ على ميمونة زوج النبي صلى الله عليه وسلم ، فذَكَرْتُ ذلك لها، فقالت لي ميمونة: لو أَخَذْتِ جُلُوَدها فَانْتَفَعْتِ بها. فقالت: َأو يَحِلُّ ذلك؟ قالت: نعم، مرَّ على رسول الله صلى الله عليه وسلم رجال من قريش يَجُرُّون شاة لهم مثل الحمار، فقال لهم رسول الله صلى الله عليه وسلم : «لو أخذتم إِهَابَهَا». قالوا: إنها مَيْتَة. فقال رسول الله صلى الله عليه وسلم : «يُطَهِّرها الماء والقَرَظ».","رواه أبو داود وأحمد","حسن"]]],["آداب قضاء الحاجة",[["عن ابن عمر أن رجلًا مَرَّ ورسول الله صلى الله عليه وسلم يبول، فسلم، فلم يرد عليه.","رواه مسلم","صحيح"],["عن حذيفة قال: أتى النبيُّ صلى الله عليه وسلم سُبَاطة قومٍ فبال قائمًا، ثم دعا بماء فجئته بماءٍ فتوضأ.","متفق عليه","صحيح"],["عن عائشة، قالت: مُرْنَ أزواجَكن أن يستطيبوا بالماء، فإني أستحييهم، فإن رسول الله صلى الله عليه وسلم كان يفعله.","رواه الترمذي والنسائي","صحيح"],["عن أبي هريرة رضي الله عنه مرفوعًا: «اتقوا اللَّعَّانَيْن» قالوا: وما اللَّعَّانَانِ يا رسول الله؟ قال: «الذي يَتَخَلَّى في طريق الناس، أو في ظِلِّهم».","رواه مسلم","صحيح"],["عن عبد الله بن عمر رضي الله عنهما قال: ((رَقيت يومًا على بيت حفصة، فرَأَيتُ النبيَّ -صلَّى الله عليه وسلَّم-يَقضِي حاجته مُسْتَقبِل الشام، مُسْتَدبِر الكعبة)). وفي رواية: ((مُسْتَقبِلا بَيتَ المَقدِس)) .","متفق عليه","صحيح"]]],["سنن الفطرة",[["عن عائشة أن النبي صلى الله عليه وسلم كان إذا دخل بيته بدأ بالسواك.","رواه مسلم","صحيح"],["عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «أكْثَرْتُ عليكم في السِّوَاك».","رواه البخاري","صحيح"],["عن ابن عمر رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «أحْفُوا الشَّوَارِبَ وأَعْفُوا اللِّحَى».","متفق عليه","صحيح"],["عن عائشة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم: «السِّوَاكُ مَطْهَرَةٌ لِلْفَمِ، مَرْضَاةٌ لِلرَّبِّ».","رواه النسائي وأحمد","صحيح"],["عن أبِي هريرة رضي اللَّه عنه: سمعتُ النبِيّ صلى الله عليه وسلم يقول: «الفِطْرَةُ خمسٌ: الخِتَانُ والاستحدادُ وقصُّ الشَّارِبِ وتقليمُ الأظفارِ وَنَتْفُ الآبَاطِ».","متفق عليه","صحيح"],["عن أبي موسى الأشعري رضي الله عنه قال: ((أتَيتُ النبي صلى الله عليه وسلم وهو يَسْتَاكُ بِسِوَاك رَطْب، قال: وطَرَفُ السِّوَاك على لسانه، وهو يقول: أُعْ، أُعْ، والسِّوَاك في فِيه، كأنَّه يَتَهَوَّع)).","متفق عليه.\nملحوظة: لفظه أخذ من الجمع بين الصحيحين للحميدي","صحيح"]]],["الوضوء",[["عن جابر بن عبد الله رضي الله عنهما قال: كان النبي صلى الله عليه وسلم إذا توضأ أدار الماء على مِرْفَقَيْهِ.","رواه الدارقطني والبيهقي","صحيح"],["عن المغيرة بن شعبة رضي الله عنه : أن النبي صلى الله عليه وسلم توضأ، فمسح بِنَاصِيَتِهِ، وعلى العِمَامة والخُفَّين.","رواه مسلم","صحيح"],["عن عبد الله بن زيد رضي الله عنه مرفوعاً: «أن النبي صلى الله عليه وسلم أُتِيَ بِثُلُثَيْ مُدٍّ فجعل يَدْلُكُ ذِرَاعَه».","رواه ابن خزيمة وأحمد","صحيح"],["عن أبي هريرة وعبد الله بن عمرو وعائشة رضي الله عنهم عن رسول الله صلى الله عليه وسلم : أنه قال: (ويلٌ للأعْقَاب من النَّار).","حديث عبد الله بن عمرو بن العاص: متفق عليه.\nحديث أبي هريرة: متفق عليه.\nحديث عائشة: رواه مسلم","صحيح"],["عن أبي هريرة، قال: قال رسول الله صلى الله عليه وسلم : «لا صلاةَ لِمن لا وُضوءَ له، ولا وُضوءَ لِمن لم يَذْكر اسم الله تعالى عليه».","رواه أبو داود وابن ماجه وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه : أن رسول الله صلى الله عليه وسلم قال: «مَنْ غَسَّل الميـِّت فلْيَغْتَسلْ، ومَنْ حَمَلَه فلْيَتَوضَّأْ».","رواه أبو داود والترمذي وابن ماجه وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لَوْلا أنْ أَشُقِّ على أُمَّتِي لَأَمَرْتُهم بالسِّواكِ مع كلِّ وُضُوء».","رواه مالك والنسائي في الكبرى وأحمد","صحيح"],["عَنْ أَبِي هُرَيْرَةَ رضي الله عنه عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: «لَا يَقْبَلُ اللهُ صَلَاةَ أَحَدِكُمْ إِذَا أَحْدَثَ حَتَّى يَتَوَضَّأَ».","متفق عليه","صحيح"],["عن أنس بن مالك رضي الله عنه قال: كان أصحاب رسول الله صلى الله عليه وسلم على عَهدِه ينتظرون العشاء حتى تَخْفِقَ رُءُوسُهُمْ، ثم يصلُّون ولا يَتَوَضَّئُونَ.","رواه مسلم وأبو داود واللفظ له","صحيح"]]],["الغسل",[["عن ميمونة قالت: وضعتُ للنبي صلى الله عليه وسلم ماء، وسترته فاغتسل.","متفق عليه","صحيح"],["عن أنس: «أن النبي صلى الله عليه وسلم كان يطوف على نسائه بِغُسْلٍ واحد».","متفق عليه","صحيح"],["عن عائشة قالت: كان النبي صلى الله عليه وسلم إذا أراد أن ينام، وهو جنب، غسل فرجه، وتوضأ للصلاة.","متفق عليه","صحيح"],["عن عبد الله بن عباس رضي الله عنهما أن النبي صلى الله عليه وسلم كان يغتسل بفضل ميمونة رضي الله عنها .","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها قالت: «كان رسول الله صلى الله عليه وسلم يَنَام وهو جُنُب من غِير أن يَمَسَّ ماء».","رواه أبو داود والترمذي والنسائي في الكبرى وابن ماجه وأحمد","صحيح"],["عن قيس بن عاصم رضي الله عنه قال: أتيتُ النبيَّ صلى الله عليه وسلم أُريدُ الإسلامَ، فأَمَرَني أن أغتَسِلَ بماءٍ وسِدرٍ.","رواه أبو داود والترمذي والنسائي","صحيح"],["عن أبي بن كعب أن الفتيا التي كانوا يفتون أن الماء من الماء، كانت رخصة رخصها رسول الله صلى الله عليه وسلم في بدء الإسلام، ثم أمر بالاغتسال بعد.","رواه أبو داود والترمذي وابن ماجه","صحيح"],["عن عائشة رضي الله عنها قالت: \"إن أم حبيبة اسْتُحِيضَتْ سبع سنين، فسألت رسول الله صلى الله عليه وسلم عن ذلك؟ فأمرها أن تغتسل، قالت: فكانت تغتسل لكل صلاة\".","متفق عليه","صحيح"],["عن عَبْدِ اللهِ بْنِ عُمَرَ رضي الله عنهما قَالَ: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ: «‌مَنْ ‌جَاءَ ‌مِنْكُمُ ‌الْجُمُعَةَ فَلْيَغْتَسِلْ».","متفق عليه","صحيح"],["عن عائشة رضي الله عنها قالت: «كُنت أغْتَسِل أنا ورسول الله صلى الله عليه وسلم من إناء واحد، تَخْتَلِفُ أَيْدِينَا فيه من الجَنَابة». وفي رواية: «وتَلْتَقِي».","متفق عليه، والرواية الثانية رواها ابن حبان","صحيح"]]],["التيمم",[["عن عمران بن حصين رضي الله عنهما أن رسول الله صلى الله عليه وسلم رأى رجلًا مُعتزلًا، لم يُصَلِّ في القوم، فقال: (يا فلان، ما منعك أن تصلي في القوم؟) فقال: يا رسول الله أصابتني جنابةٌ، ولا مَاءَ، فقال: (عليك بالصَّعِيدِ، فإنه يَكْفِيَكَ).","متفق عليه","صحيح"],["عن علي بن أبي طالب رضي الله عنه مرفوعاً: قال رسول الله صلى الله عليه وسلم : \"أُعطِيتُ ما لم يُعطَ أحدٌ من الأنبياءِ\". فقلنا: يارسول الله، ما هو؟ قال: \"نُصِرتُ بالرُّعبِ، وأُعطِيتُ مَفَاتِيحَ الأرضِ، وسُمِّيتُ أحمدَ، وجُعِلَ التُّرابُ لي طَهُوراً، وجُعِلَتْ أمَّتي خيرَ الأممِ\".","رواه أحمد","صحيح"],["عن أبي سعيد الخدري رضي الله عنه قال: خرج رَجُلَان في سفر، فَحَضَرَتِ الصلاة وليس معهما ماء؛ فَتَيَمَّمَا صَعيدا طيِّبا فَصَلَّيَا، ثمَّ وجَدَا الماء في الوقت، فأعاد أَحَدُهُمَا الصلاة وَالوُضُوءَ ولم يُعِدِ الآخر، ثم أتَيَا رسول الله صلى الله عليه وسلم فذكَرَا ذلك له فقال لِلَّذِي لَمْ يُعِدْ: «أَصَبْتَ السنة، وَأَجْزَأَتْكَ صَلَاتُكَ». وقال للذي توضأ وأعاد: «لك الأجر مرَّتَين».","رواه أبو داود والنسائي والدارمي","صحيح"],["عن أبي ذر جندب بن جنادة رضي الله عنه قال: اجتمعت غنيمة عند رسول الله صلى الله عليه وسلم فقال: «يا أبا ذر اُبْدُ فيها» فبَدَوْتُ إلى الرَّبذَة فكانت تُصيبني الجنابة فأمكث الخَمْسَ والسِّتَّ، فأتيتُ النبي صلى الله عليه وسلم فقال: «أبو ذر» فَسَكَتُّ فقال: «ثَكِلَتْكَ أمك أبا ذر لأمِّكَ الوَيْلُ» فدعا لي بجارية سوداء فجاءت بِعُسٍّ فيه ماء فستَرتْنِي بثَوب واستَتَرْتُ بالرَّاحلة، واغتسلتُ فكأني أَلقَيْتُ عني جَبَلًا فقال «الصعيدُ الطيِّبُ وُضُوءُ المسلم ولو إلى عشر سنين، فإذا وجدتَ الماء فأَمِسَّهُ جِلدَكَ فإن ذلك خَيرٌ».","رواه أبو داود والترمذي والنسائي وأحمد","صحيح"],["عن عائشة زوج النبي صلى الله عليه وسلم قالت: خرجنا مع رسول الله صلى الله عليه وسلم في بعض أسفاره، حتى إذا كنا بالبيداء أو بذات الجيش انقطع عقد لي، فأقام رسول الله صلى الله عليه وسلم على التماسه، وأقام الناس معه وليسوا على ماء، فأتى الناس إلى أبي بكر الصديق، فقالوا: ألا ترى ما صنعت عائشة؟ أقامت برسول الله صلى الله عليه وسلم والناسِ وليسوا على ماء، وليس معهم ماء. فجاء أبو بكر ورسول الله صلى الله عليه وسلم واضع رأسه على فخذي قد نام، فقال: حبستِ رسول الله صلى الله عليه وسلم والناس، وليسوا على ماء، وليس معهم ماء، فقالت عائشة: فعاتبني أبو بكر، وقال ما شاء الله أن يقول، وجعل يطعنني بيده في خاصرتي، فلا يمنعني من التحرك إلا مكان رسول الله صلى الله عليه وسلم على فخذي، فقام رسول الله صلى الله عليه وسلم حين أصبح على غير ماء، فأنزل الله آية التيمم فتيمموا، فقال أسيد بن الحضير: ما هي بأول بركتكم يا آل أبي بكر، قالت: فبعثنا البعير الذي كنت عليه، فأصبنا العقد تحته.","متفق عليه","صحيح"]]],["الحيض والنفاس والاستحاضة",[["عن ميمونة زوج النبي صلى الله عليه وسلم قالت: كان رسول الله صلى الله عليه وسلم يضطجع معي وأنا حائض، وبيني وبينه ثوب.","رواه مسلم","صحيح"],["عن عَائِشَة رضي الله عنها قالت: «كان رسول الله صلى الله عليه وسلم يَتَكِّئُ فِي حِجرِي، فَيَقرَأُ القرآن وأنا حَائِض».","متفق عليه","صحيح"],["عن ابن عباس رضي الله عنهما ، عن النبي صلى الله عليه وسلم في الذي يأتي امرأته وهي حائض قال: «يتصدق بدينار أو نصف دينار».","رواه أبو داود وابن ماجه والنسائي وأحمد والدارمي","صحيح"],["عن أُمِّ عَطِيَّةَ رَضي الله عنها، وكَانَتْ بايَعَت النبيَّ صلى الله عليه وسلم، قالت: كُنَّا لا نَعُدّ الكُدرَةَ والصُّفْرَةَ بعدَ الطُّهرِ شيئًا.","رواه أبو داود بهذا اللفظ، ورواه البخاري  بدون زيادة (بعد الطهر)","صحيح"],["عن عائشة رضي الله عنها قالت: \"إن أم حبيبة اسْتُحِيضَتْ سبع سنين، فسألت رسول الله صلى الله عليه وسلم عن ذلك؟ فأمرها أن تغتسل، قالت: فكانت تغتسل لكل صلاة\".","متفق عليه","صحيح"],["عن عائشة رضي الله عنها قالت: اعتكفتْ مع رسول الله صلى الله عليه وسلم امرأةٌ من أزواجه مستحاضة، فكانت ترى الحُمرة والصُّفرة، فربما وضعنا الطِّسْت تحتها وهي تصلي.","رواه البخاري","صحيح"],["عن عائشة أنها كانت تُرَجِّل -تعني رأس رسول الله صلى الله عليه وسلم- وهي حائض، ورسول الله صلى الله عليه وسلم حينئذ مجاور في المسجد، يدني لها رأسه، وهي في حجرتها، فتُرَجِّله وهي حائض.","متفق عليه","صحيح"],["عن عائشة قالت: كنت أشرب وأنا حائض، ثم أناوله النبي صلى الله عليه وسلم فيضع فاه على موضع فيَّ، فيشرب، وأتعرق العرق وأنا حائض، ثم أناوله النبي صلى الله عليه وسلم فيضع فاه على موضع فيَّ.","رواه مسلم","صحيح"],["عن أسماءَ رضي الله عنها قالت: جاءت امرأةٌ النبيَّ صلى الله عليه وسلم فقالت: أرأَيْتَ إحدانا تَحِيضُ في الثَّوب، كيف تصنعُ؟ قال: «تَحُتُّهُ، ثم تَقْرُصُه بالماء، وتَنْضَحُه، وتُصَلِّي فيه».","متفق عليه","صحيح"],["عن عائشة أن امرأة سألت النبي صلى الله عليه وسلم عن غسلها من المحيض، فأمرها كيف تغتسل، قال: «خذي فُرْصَةً من مسك، فتطهري بها» قالت: كيف أتطهر؟ قال: «تطهري بها»، قالت: كيف؟ قال: «سبحان الله، تطهري» فاجتبذتُها إليَّ، فقلت: تتبعي بها أثر الدم.","متفق عليه","صحيح"],["عن أسماء بنت أبي بكر الصديق أنها قالت: سألت امرأة رسول الله صلى الله عليه وسلم فقالت: يا رسول الله، أرأيت إحدانا إذا أصاب ثوبها الدم من الحيضة كيف تصنع؟ فقال رسول الله صلى الله عليه وسلم: «إذا أصاب ثوبَ إحداكن الدمُ من الحَيضة فلتقرُصْه، ثم لتنضَحه بماء، ثم لتصلي فيه».","متفق عليه","صحيح"]]],["المسح على الخفين ونحوهما",[["عن عمرو بن أمية قال: رأيت النبي صلى الله عليه وسلم يمسح على عمامته وخفيه.","رواه البخاري","صحيح"],["عن بريدة أن النبي صلى الله عليه وسلم صلى الصلوات يوم الفتح بوضوء واحد، ومسح على خفيه. فقال له عمر: لقد صنعت اليوم شيئًا لم تكن تصنعه، قال: «عمدًا صنعتُه يا عمر».","رواه مسلم","صحيح"],["عن عبد خير، عن علي رضي الله عنه ، قال: لو كان الدين بالرأي لكان أسفل الخُفِّ أولى بالمسح من أعلاه، وقد «رأيت رسول الله صلى الله عليه وسلم يمسح على ظَاهر خُفَيْهِ».","رواه أبو داود","صحيح"],["عن ثوبان رضي الله عنه ، قال: «بعث رسول الله صلى الله عليه وسلم سَرِيَّةً، فأصابهم البَرْد فلما قَدِموا على رسول الله صلى الله عليه وسلم أمَرَهُم أن يَمْسَحوا على الْعَصَائِب والتَّسَاخِين».","رواه أبو داود وأحمد","صحيح"],["عن شريح بن هانئ، قال: أتيتُ عائشة أسألها عن المسح على الخُفَّين، فقالت: عَلَيْكَ بِابْنِ أبِي طالب، فَسَلْهُ فإِنَّه كان يُسَافِرُ مع رسول الله صلى الله عليه وسلم فسألناه فقال: «جَعَلَ رسول الله صلى الله عليه وسلم ثَلَاثَةَ أَيَّامٍ وَلَيَالِيَهُنَّ للمسافر، ويوما وليلة للمُقيم».","رواه مسلم","صحيح"],["عن أبي بكرة نُفيع بن الحارث الثقفي رضي الله عنه عن النبي صلى الله عليه وسلم أنه رَخَّصَ للمسَافر ثلاثةَ أيَّام ولَيَالِيهنَّ، وللمُقِيم يوما وليلة، إذا تطَهَّر فَلَبِسَ خُفَّيه: أَن يَمسَحَ عليهما.","رواه ابن ماجه والدارقطني","حسن"],["عن جابر رضي الله عنه قال: خرجنا في سَفَر فأصاب رجُلا مِنَّا حَجَرٌ فَشَجَّهُ في رأسه، ثم احتلم فسأل أصحابه فقال: هل تجدون لي رُخْصَة في التَّيمم؟ فقالوا: ما نَجِد لك رُخْصَة وأنت تَقْدِرُ على الماء فاغْتَسَل فمات، فلمَّا قَدِمْنَا على النبي صلى الله عليه وسلم أخبر بذلك فقال: «قَتَلُوه قَتَلَهُم الله ألا سَألُوا إذ لم يعلموا فإنَّما شِفَاء العِيِّ السؤال، إنما كان يَكفيه أن يَتيمَّم ويَعْصِر-أو يَعْصِب- على جُرحِه خِرقَة، ثم يمسح عليها، ويَغسل سائر جسده».","رواه أبو داود","حسن لغيره"]]]]],["الصيام",0,[["وجوب الصيام وحكم تاركه",[["عن حفصة زوج النبي صلى الله عليه وسلم أن رسول الله صلى الله عليه وسلم قال: \"من لم يُجْمِع الصيام قبل الفجر فلا صيام له\".","رواه أبو داود والترمذي والنسائي وابن ماجه","صحيح"],["عَنْ عَبْدِ اللهِ بنِ عُمَر رضي الله عنهما قال: قال رسولُ الله صلى الله عليه وسلم: «بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ الْبَيْتِ، وَصَوْمِ رَمَضَانَ».","متفق عليه","صحيح"],["عن ابن عباس {يا أيها الذين آمنوا كتب عليكم الصيام كما كتب على الذين من قبلكم} [البقرة: 183] فكان الناس على عهد النبي صلى الله عليه وسلم إذا صلوا العتمة حرم عليهم الطعام والشراب والنساء، وصاموا إلى القابلة، فاختان رجل نفسه، فجامع امرأته وقد صلى العشاء ولم يفطر، فأراد الله عز وجل أن يجعل ذلك يسرًا لمن بقي ورخصة ومنفعة، فقال سبحانه: {علم الله أنكم كنتم تختانون أنفسكم} الآيه [البقرة: 187]. وكان هذا مما نفع الله به الناس، ورخص لهم ويسر.","رواه أبو داود","صحيح"],["عن البراء رضي الله عنه قال: \"كان أصحاب محمد صلى الله عليه وسلم إذا كان الرجل صائمًا فحضر الإفطار فنام قبل أن يفطر لم يأكل ليلته ولا يومه حتى يمسي، وإن قيس بن صِرْمة الأنصاري كان صائمًا، فلما حضر الإفطار أتى امرأته، فقال لها: أعندك طعام؟ قالت: لا، ولكن أنطلق فأطلب لك. وكان يومه يعمل، فغلبته عيناه، فجاءته امرأته، فلما رأته قالت: خيبة لك. فلما انتصف النهار غشي عليه، فذُكر ذلك للنبي صلى الله عليه وسلم فنزلت هذه الآية: {أحل لكم ليلة الصيام الرفث إلى نسائكم} [البقرة: 187] ففرحوا بها فرحًا شديدًا، ونزلت: {وكلوا واشربوا حتى يتبين لكم الخيط الأبيض من الخيط الأسود} [البقرة: 187]\".","رواه البخاري","صحيح"],["عن أَنَسَ بْنَ مَالِكٍ رضي الله عنه قال: بينما نحن جلوس مع النبي صلى الله عليه وسلم في المسجد دخل رجل على جمل، فأناخه في المسجد ثم عقله، ثم قال لهم: أيكم محمد؟ والنبي صلى الله عليه وسلم متكئ بين ظهرانيهم، فقلنا: هذا الرجل الأبيض المتكئ. فقال له الرجل: يا ابن عبد المطلب فقال له النبي صلى الله عليه وسلم: «قد أجبتك». فقال الرجل للنبي صلى الله عليه وسلم: إني سائلك فمشدد عليك في المسألة، فلا تجد علي في نفسك؟ فقال: «سل عما بدا لك» فقال: أسألك بربك ورب من قبلك، آلله أرسلك إلى الناس كلهم؟ فقال: «اللهم نعم». قال: أنشدك بالله، آلله أمرك أن نصلي الصلوات الخمس في اليوم والليلة؟ قال: «اللهم نعم». قال: أنشدك بالله، آلله أمرك أن نصوم هذا الشهر من السنة؟ قال: «اللهم نعم». قال: أنشدك بالله، آلله أمرك أن تأخذ هذه الصدقة من أغنيائنا فتقسمها على فقرائنا؟ فقال النبي صلى الله عليه وسلم: «اللهم نعم». فقال الرجل: آمنت بما جئت به، وأنا رسول من ورائي من قومي، وأنا ضمام بن ثعلبة أخو بني سعد بن بكر.","متفق عليه","صحيح"]]],["فضل الصيام",[["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ»","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إذا دخل رمضان فُتِحت أبواب الجنة وغُلِّقت أبواب جهنم وسُلْسِلَت الشياطين»، وفي رواية للبخاري: «أبواب السماء»، وفي رواية لمسلم: «أبواب الرحمة».","متفق عليه","صحيح"],["عن أم المؤمنين عائشة رضي الله عنها قالت: دخل علي النبي صلى الله عليه وسلم ذات يوم فقال: «هل عندكم شيء؟» فقلنا: لا. قال: «فإني إذن صائم» ثم أتانا يومًا آخر فقلنا: يا رسول الله، أهدي لنا حيس. فقال: «أَرِينيه، فلقد أصبحت صائمًا» فأكل.","رواه مسلم","صحيح"]]],["سنن الصيام",[["عن سهل بن سعد قال: كنت أتسحر في أهلي، ثم يكونُ سرعةٌ بي أن أدرك صلاة الفجر مع رسول الله صلى الله عليه وسلم.","رواه البخاري","صحيح"],["عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: (إذا دعي أحدكم إلى طعام وهو صائم فليقل: إني صائم).","رواه مسلم","صحيح"],["عن عمرو بن العاص رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «فَصْلُ مَا بَيْنَ صِيَامِنَا وصِيَامِ أهْلِ الكِتَابِ، أكْلَةُ السَّحَرِ».","رواه مسلم","صحيح"],["عن زيد بن خالد الجهني رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: «مَنْ فَطَّرَ صائمًا، كان له مِثْلُ أجْرِهِ، غَيْرَ أنَّهُ لاَ يُنْقَصُ مِنْ أجْرِ الصَّائِمِ شَيْءٌ».","رواه الترمذي وابن ماجه والنسائي في الكبرى والدارمي وأحمد","صحيح"],["عن سهل بن سعد قال: قال رسول الله صلى الله عليه وسلم: \"لا تزال أمتي على سنتي ما لم تنتظر بفطرها النجوم\"، قال: وكان النبي صلى الله عليه وسلم إذا كان صائمًا أمر رجلًا، فأوفى على شيء، فإذا قال: غابت الشمس أفطر.","رواه ابن خزيمة وابن حبان والحاكم","صحيح"],["عن أبي عطية، قال: دخلت أنا ومسروق على عائشة رضي الله عنها ، فقالَ لها مسروقٌ: رجلانِ من أصحابِ محمدٍ صلى الله عليه وسلم كِلاَهُمَا لا يَألُو عَنِ الخَيْرِ؛ أحَدُهُمَا يُعَجِّلُ المَغْرِبَ وَالإفْطَارَ، وَالآخر يؤخِّر المغرب وَالإفْطَارَ؟ فَقَالَتْ: مَنْ يُعَجِّلُ المَغْرِبَ وَالإفْطَار؟ قالَ: عبدُ اللهِ -يعني: ابن مسعود- فقالتْ: هَكذا كانَ رسولُ اللهِ يَصْنَعُ.","رواه مسلم","صحيح"],["عن ابن عمر قال: كان رسول الله صلى الله عليه وسلم إذا أفطر قال: \"ذهب الظمأُ، وابتلت العروق، وثبت الأجر إن شاء الله\".","رواه أبو داود","حسن"],["عن أنس بن مالك رضي الله عنه قال: كان رسولُ اللهِ صلى الله عليه وسلم يُفطِر قبْل أن يصلي على رُطَبات، فإن لم تكنْ رُطَباتٌ فَتُمَيْراتٌ، فإن لم تكنْ تُمَيْراتٌ، حَسَا حَسَواتٍ مِن ماء.","رواه أبو داود والترمذي وأحمد","حسن"]]],["رؤية الهلال",[["عن أبي هريرة ذكر النبي صلى الله عليه وسلم فيه قال: \"وفطركم يوم تفطرون، وأضحاكم يوم تضحون، وكل عرفة موقف، وكل منى منحر، وكل فجاج مكة منحر، وكل جمع موقف\".","رواه أبو داود والترمذي وابن ماجه","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال النبي صلى الله عليه وسلم أو قال: قال أبو القاسم صلى الله عليه وسلم: «صوموا لرؤيته وأفطروا لرؤيته، فإن غبي عليكم فأكملوا عدة شعبان ثلاثين».","متفق عليه، واللفظ للبخاري","صحيح"],["عن ربعى بن حراش عن رجل من أصحاب النبي صلى الله عليه وسلم قال: اختلف الناس في آخر يوم من رمضان، فقدم أعرابيان فشهدا عند النبي صلى الله عليه وسلم بالله لَأهلَّا الهلال أمس عشية، فأمر رسول الله صلى الله عليه وسلم الناس أن يفطروا. زاد خلف أحد شيخي أبي داود في حديثه: وأن يغدوا إلى مصلاهم.","رواه أبو داود","صحيح"],["عن كُريب أن أم الفضل بنت الحارث بعثته إلى معاوية بالشام، قال: فقدمت الشام، فقضيت حاجتها، واستهل علي رمضان وأنا بالشام، فرأيت الهلال ليلة الجمعة، ثم قدمت المدينة في آخر الشهر، فسألني عبد الله بن عباس رضي الله عنهما، ثم ذكر الهلال فقال: متى رأيتم الهلال؟ فقلت: رأيناه ليلة الجمعة، فقال: أنت رأيته؟ فقلت: نعم، ورآه الناس، وصاموا وصام معاوية. فقال: لكنا رأيناه ليلة السبت، فلا نزال نصوم حتى نكمل ثلاثين أو نراه. فقلت: أو لا تكتفي برؤية معاوية وصيامه؟ فقال: لا، هكذا أمرنا رسول الله صلى الله عليه وسلم.","رواه مسلم","صحيح"]]],["صيام يوم الشك",[["عن صِلَة بن زُفَر، قال: كنا عند عمار في اليوم الذي يشك فيه، فأتي بشاة، فتنحى بعض القوم، فقال عمار: من صام هذا اليوم فقد عصى أبا القاسم صلى الله عليه وسلم.","رواه أبو داود والترمذي والنسائي وابن ماجه","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال النبي صلى الله عليه وسلم أو قال: قال أبو القاسم صلى الله عليه وسلم: «صوموا لرؤيته وأفطروا لرؤيته، فإن غبي عليكم فأكملوا عدة شعبان ثلاثين».","متفق عليه، واللفظ للبخاري","صحيح"]]],["قضاء الصيام",[["عن عائشة رضي الله عنها أن رسول الله صلى الله عليه وسلم قال: «من مات وعليه صِيَامٌ صَامَ عنه وَلِيُّهُ».","متفق عليه","صحيح"],["عن عائشة رضي الله عنها قالت: كان يكون علي الصوم من رمضان، فما أستطيع أن أقضي إلا في شعبان، الشغل من النبي أو بالنبي صلى الله عليه وسلم.","متفق عليه","صحيح"],["عن هشام بن عروة عن فاطمة عن أسماء بنت أبي بكر الصديق رضي الله عنهما قالت: أفطرنا على عهد النبي صلى الله عليه وسلم يوم غيم، ثم طلعت الشمس. قيل لهشام: فأمروا بالقضاء؟ قال: لا بد من قضاء. وقال معمر: سمعت هشاما لا أدري أقضوا أم لا.","رواه البخاري","صحيح"],["عن عبد الله بن عباس رضي الله عنهما قال: «جاء رجل إلى النبي صلى الله عليه وسلم فقال: يا رسول الله، إن أمي ماتت وعليها صوم شهر. أَفَأَقْضِيهِ عنها؟ فقال: لو كان على أمك دَيْنٌ أَكُنْتَ قَاضِيَهُ عنها؟ قال: نعم. قال: فَدَيْنُ اللهِ أَحَقُّ أن يُقْضَى ». وفي رواية: «جاءت امرأة إلى رسول الله صلى الله عليه وسلم فقالت: يا رسول الله، إن أمي ماتت وعليها صوم نذر. أفأصوم عنها؟ فقال: أرأيت لو كان على أمك دَيْنٌ فَقَضَيْتِيهِ ، أكان ذلك يُؤَدِّي عنها؟ فقالت: نعم. قال: فَصُومِي عن أمك».","متفق عليه","صحيح"]]],["صيام أهل الأعذار",[["عن أنس بن مالك قال: كنا نسافر مع النبي صلى الله عليه وسلم فلم يَعِبْ الصائم على المفطر، ولا المفطر على الصائم.","متفق عليه","صحيح"],["عن أَبِي الدَّرْدَاءِ رضي الله عنه قال: «خَرَجْنَا مع رسول الله صلى الله عليه وسلم في شهر رمضان، في حَرٍّ شَدِيدٍ ، حتى إن كان أَحَدُنَا لَيَضَعُ يَدَهُ على رأسهِ من شِدَّةِ الْحَرِّ. وما فِينَا صائمٌ إلا رسولُ الله صلى الله عليه وسلم وعبد ُالله بن رَوَاحَةَ».","متفق عليه","صحيح"],["عن ابن عباس رضي الله عنهما قال: خرج رسول الله صلى الله عليه وسلم من المدينة إلى مكة، فصام حتى بلغ عُسْفان، ثم دعا بماءٍ فرفعه إلى يديه؛ ليريه الناس، فأفطر حتى قدم مكة، وذلك في رمضان، فكان ابن عباس يقول: قد صام رسول الله صلى الله عليه وسلم وأفطر، فمن شاء صام ومن شاء أفطر.","متفق عليه","صحيح"],["عن ابن عباس رضي الله عنهما أن النبي صلى الله عليه وسلم خرج في رمضان من المدينة ومعه عشرة آلاف، وذلك على رأس ثمانِ سنينَ ونصفٍ من مَقْدَمه المدينة، فسار هو ومَن معه مِن المسلمين إلى مكة، يصوم ويصومون، حتى بلغ الكَدِيدَ، وهو ماءٌ بين عُسْفانَ وقُدَيدٍ أفطر وأفطروا، قال الزهري: وإنما يؤخذ من أمر رسول الله صلى الله عليه وسلم الآخِر فالآخِر.","متفق عليه","صحيح"],["عن أنس بن مالك رضي الله عنه قال: كنَّا مع النبي صلى الله عليه وسلم في السفر فمنَّا الصائم، وَمِنَّا المُفطر، قال: فنزلنا مَنْزِلًا فِي يوم حارٍّ، وأكثرنا ظِلًّا صاحب الْكِسَاءِ، وَمِنَّا من يَتَّقِي الشمس بيده، قال: فَسقط الصُّوَّامُ، وقام المُفْطِرُونَ فَضربوا الْأَبْنِيَةِ، وَسَقَوْا الرِّكَاب، فقال رسول الله صلى الله عليه وسلم : \"ذهب المُفْطِرُونَ اليوم بالأجر\".","متفق عليه","صحيح"]]],["مفسدات الصيام",[["عن ابن عباس رضي الله عنهما قال: احتجم النبي صلى الله عليه وسلم وهو صائم.","رواه البخاري","صحيح"],["عن أبي هريرة رضي الله عنه قال: بينما نحن جلوس عند النبي صلى الله عليه وسلم إذ جاءه رجل، فقال: يا رسول الله هلكت. قال: «ما لك؟» قال: وقعت على امرأتي وأنا صائم. فقال رسول الله صلى الله عليه وسلم: «هل تجد رقبة تعتقها؟» قال: لا. قال: «فهل تستطيع أن تصوم شهرين متتابعين؟»، قال: لا. فقال: «فهل تجد إطعام ستين مسكينًا.». قال: لا. قال: فمكث النبي صلى الله عليه وسلم، فبينا نحن على ذلك أتي النبي صلى الله عليه وسلم بعَرَق فيها تمر -والعَرَق المكتل- قال: «أين السائل؟» فقال: أنا. قال: «خذها، فتصدق به» فقال الرجل: أعلى أفقر مني يا رسول الله؟ فوالله ما بين لابتيها -يريد الحرتين- أهل بيت أفقر من أهل بيتي. فضحك النبي صلى الله عليه وسلم حتى بدت أنيابه، ثم قال: «أطعمه أهلك».","متفق عليه","صحيح"],["عن أبي هريرة أن النبي صلى الله عليه وسلم قال: «من أفطر في رمضان ناسيا فلا قضاء عليه ولا كفارة».","رواه ابن خزيمة وابن حبان والحاكم","حسن"]]],["ما يجب على الصائم",[["عن عمر بن الخطاب رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إذا أقبل الليل من هَهُنا، وأَدْبَرَالنهار من ههنا، فقد أفطر الصائم».","متفق عليه","صحيح"],["عن هشام بن عروة عن فاطمة عن أسماء بنت أبي بكر الصديق رضي الله عنهما قالت: أفطرنا على عهد النبي صلى الله عليه وسلم يوم غيم، ثم طلعت الشمس. قيل لهشام: فأمروا بالقضاء؟ قال: لا بد من قضاء. وقال معمر: سمعت هشاما لا أدري أقضوا أم لا.","رواه البخاري","صحيح"],["عن عدي بن حاتم رضي الله عنه قال: لما نزلت: {حتى يتبين لكم الخيط الأبيض من الخيط الأسود} [البقرة: 187] عَمَدتُ إلى عقال أسود وإلى عقال أبيض، فجعلتهما تحت وسادتي، فجعلت أنظر في الليل، فلا يستبين لي، فغدوت على رسول الله صلى الله عليه وسلم، فذكرت له ذلك فقال: «إنما ذلك سواد الليل وبياض النهار».","متفق عليه","صحيح"]]],["ما يجوز للصائم",[["عن عائشة رضي الله عنها قالت: كان النبي صلى الله عليه وسلم يقبل ويباشر وهو صائم، وكان أملككم لإِرْبِه.","متفق عليه","صحيح"],["عن أنس بن مالك قال: كنا نسافر مع النبي صلى الله عليه وسلم فلم يَعِبْ الصائم على المفطر، ولا المفطر على الصائم.","متفق عليه","صحيح"],["عن عائشة وأم سلمة رضي الله عنهما «أن رسول الله صلى الله عليه وسلم كان يُدْرِكُهُ الفجر وهو جُنٌبٌ من أهله، ثم يغتسل ويصوم ».","متفق عليه","صحيح"],["عن عائشة رضي الله عنها : \"أن حَمْزَةَ بن عَمْرٍو الأَسْلَمِيَّ قال للنبي صلى الله عليه وسلم : أصوم في السفر؟ - وكان كثير الصيام- فقال: \"إن شئتَ فصُم، وإن شئت فَأَفْطِرْ\".","متفق عليه","صحيح"]]],["ما يحرم على الصائم",[["عن عمران بن حُصين قال: قيل: يا رسول الله، إن فلانًا لا يفطر نهارًا الدهرَ. قال: «لا صام ولا أفطر».","رواه النسائي","صحيح"],["عن محمد بن عباد بن جعفر قال: «سألت جابر بن عبد الله رضي الله عنهما : أَنَهَى النبي صلى الله عليه وسلم عن صوم يوم الجمعة ؟ قال: نعم». وفي رواية: «وَرَبِّ الْكَعْبَة».","رواه البخاري ومسلم  -ولفظ مسلم: (نعم وَرَبِّ هذا البيت) أما لفظ : \"ورب الكعبة\" فهذا لفظ النسائي في الكبرى، نبه على ذلك الشيخ ابن عثيمين -رحمه الله","صحيح"],["عن أبي سعيد الخدري رضي الله عنه قال: «نهى رسول الله صلى الله عليه وسلم عن صوم يومين: الفطر والنحر، وعن اشْتِمَالِ الصَّمَّاءِ، وأن يَحْتَبِيَ الرجل في الثوب الواحد، وعن الصلاة بعد الصبح والعصر».","متفق عليه","صحيح"],["عن عبد الله بن عَمْرِو بن العاص رضي الله عنهما قال: «أُخبِر رسول الله صلى الله عليه وسلم أني أقول: والله لَأَصُومَنَّ النهار، وَلَأَقُومَنَّ الليل مَا عِشْتُ. فقال رسول الله صلى الله عليه وسلم : أنت الذي قلتَ ذلك؟ فقلتُ له: قد قُلتُه -بأبي أنت وأمي-. فقال: فإنك لا تستطيع ذلك، فصُم وأفطِر، وَقُمْ وَنَمْ ، الشَّهْرِ ثَلاَثَةَ أَيَّامٍ، فَإِنَّ الحَسَنَةَ بِعَشْرِ أَمْثَالِهَا، وذلك مثل صيام الدَّهْرِ. قلت: فإني أُطِيقُ أفضل من ذلك. قال: فصم يوما وأَفطر يومين. قلت: أُطِيقُ أفضل من ذلك. قال: فصم يوما وأفطر يوما، فذلك مثل صيام داود، وهو أفضل الصيام. فقلت: إني أُطِيقُ أفضل من ذلك. قال: لا أفضل من ذلك»، وفي رواية: «لا صوم فوق صوم أخي داود -شَطْرَ الدَّهَرِ-، صم يوما وأفطر يوما».","متفق عليه","صحيح"]]],["ما يكره للصائم",[["عن عبد الله بن عمر رضي الله عنهما قال: «نهى رسول الله صلى الله عليه وسلم عن الْوِصَالِ، قالوا: إنك تواصل؟ قال: إني لَسْتُ كَهَيْئَتِكُمْ، إني أُطْعَمُ وَأُسْقَى». وفي رواية أبي سعيد الخدري رضي الله عنه : «فَأَيُّكُمْ أراد أن يواصل فليواصل إلى السَّحَرِ».","متفق عليه","صحيح"]]],["صيام التطوع",[["عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم صام يوم عاشوراء وأمر بصيامه.","متفق عليه","صحيح"],["عن عائشة رضي الله عنها قالت: كانَ رسولُ اللهِ صلى الله عليه وسلم يَتَحرّى صومَ الإثنينِ والخميسِ.","رواه الترمذي والنسائي وابن ماجه وأحمد","صحيح"],["عن عبدالله بن عباس رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «لَئِن بَقِيتُ إلى قابلٍ لأصومنّ التاسِع».","رواه مسلم","صحيح"],["عن أبي أيوب الأنصاري رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «من صام رمضان ثم أتبعه ستًّا من شوال كان كصيام الدهر».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «لا يَصُومَنَّ أحدكم يوم الجمعة، إلا أن يصومَ يومًا قبله أو بعده».","متفق عليه","صحيح"],["عن عائشة رضي الله عنها قالت: لم يكن النبي صلى الله عليه وسلم يصوم مِنْ شهر أكثر من شعبان، فإنّه كان يصوم شعبان كله. وفي رواية: كان يصوم شعبان إلا قليلا.","متفق عليه","صحيح"],["عن جُوَيرِيَة بنت الحارث رضي الله عنها أن النبي صلى الله عليه وسلم دخل عليها يوم الجمعة وهي صائمة، فقال: «أصمتِ أمس؟» قالت: لا. قال: «تريدين أن تصومي غدًا؟» قالت: لا. قال: «فأفطري».","رواه البخاري","صحيح"],["عن أم الفضل بنت الحارث أن ناسًا اختلفوا عندها يوم عرفة في صوم النبي صلى الله عليه وسلم فقال بعضهم: هو صائم، وقال بعضهم: ليس بصائم، فأرسلتْ إليه ‌بقَدَحِ ‌لبنٍ وهو واقف على بعيره، فشربه.","متفق عليه","صحيح"],["عن عائشة رضي الله عنها قالت: كان رسول الله صلى الله عليه وسلم يصوم حتى نقول: لا يفطر، ويفطر حتى نقول: لا يصوم، فما رأيت رسول الله صلى الله عليه وسلم استكمل صيام شهر إلا رمضان، وما رأيته أكثر صيامًا منه في شعبان.","متفق عليه","صحيح"],["عن أنس رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم يُفْطِرُ من الشهر حتى نظن أن لا يصوم منه، ويصوم حتى نظن أن لا يُفْطِرَ منه شيئا، وكان لا تَشَاءُ أن تراه من الليل مُصَلِيًا إلا رأيتَه، ولا نائما إلا رأيتَه.","رواه البخاري","صحيح"]]],["الاعتكاف",[["عن أنس بن مالك قال: كان النبي صلى الله عليه وسلم يعتكف في العشر الأواخر من رمضان، فلم يعتكف عامًا، فلما كان في العام المقبل اعتكف عشرين.","رواه الترمذي","صحيح"],["عن أبي هريرة رضي الله عنه قال: كان النبي صلى الله عليه وسلم يعتكف في كل رمضان عشرة أيام، فلما كان العام الذي قُبِضَ فيه اعتكف عشرين يوماً.","رواه البخاري","صحيح"],["عن عائشة رضي الله عنها قالت: اعتكفتْ مع رسول الله صلى الله عليه وسلم امرأةٌ من أزواجه مستحاضة، فكانت ترى الحُمرة والصُّفرة، فربما وضعنا الطِّسْت تحتها وهي تصلي.","رواه البخاري","صحيح"],["عن عمر بن الخطاب رضي الله عنه قال: قلت: يا رسول الله، إني كنت نَذَرْتُ في الجَاهلية أن أعتكف ليلة -وفي رواية: يومًا- في المسجد الحرام ؟ قال: «فَأَوْفِ بِنَذْرِكَ».","متفق عليه","صحيح"],["عن أبي هريرة، قال: كان يعرض على النبي صلى الله عليه وسلم القرآن كل عام مرة، فعرض عليه مرتين في العام الذي قبض فيه، وكان يعتكف كل عام عشرا، فاعتكف عشرين في العام الذي قبض فيه.","رواه البخاري","صحيح"],["عن عائشة أنها كانت تُرَجِّل -تعني رأس رسول الله صلى الله عليه وسلم- وهي حائض، ورسول الله صلى الله عليه وسلم حينئذ مجاور في المسجد، يدني لها رأسه، وهي في حجرتها، فتُرَجِّله وهي حائض.","متفق عليه","صحيح"],["عن عائشة رضي الله عنها قالت: كان النبي صلى الله عليه وسلم يعتكف في العشر الأواخر من رمضان، فكنت أضرب له خِباءً، فيصلي الصبح ثم يدخله، فاستأذنت حفصة عائشة أن تضرب خباء، فأذنت لها، فضربت خباء، فلما رأته زينب ابنة جحش ضربت خباء آخر، فلما أصبح النبي صلى الله عليه وسلم رأى الأخبية، فقال: «ما هذا؟» فأُخبِر، فقال النبي صلى الله عليه وسلم: «ألبِرَّ ترون بهن؟» فترك الاعتكاف ذلك الشهر، ثم اعتكف عشرًا من شوال. وفي رواية: «آلبر تُرِدْنَ؟».","متفق عليه","صحيح"],["عن أبي سعيد الخُدْري رضي الله عنه : «أن رسول الله صلى الله عليه وسلم كان يَعْتَكِفُ في العَشْرِ الأَوْسَطِ من رمضان. فاعتكف عامًا، حتى إذا كانت لَيْلَةَ إِحْدَى وَعِشْرِينَ -وهي اللَّيْلَةُ التي يخرج من صَبِيحَتِهَا من اعتكافه- قال: من اعتكف معي فَلْيَعْتَكِفِ العَشْرَ الأَوَاخِرَ فقد أُرِيتُ هَذِهِ اللَّيْلَةَ ثم أُنْسِيتُهَا، وقد رَأَيْتُنِي أَسْجُدُ فِي مَاءٍ وَطِينٍ من صَبِيحَتِهَا، فَالْتَمِسُوهَا فِي العَشْرِ الأَوَاخِرِ، والتمسوها في كل وِتْرٍ. فَمَطَرَتِ السَّمَاءُ تلك الليلة، وكان المسجد على عَرِيشٍ، فَوَكَفَ المسجد، فَأبْصَرَتْ عَيْنَايَ رسول الله صلى الله عليه وسلم وعلى جَبْهَتِهِ أَثَرُ المَاءِ وَالطِّين من صُبْحِ إحْدَى وَعشْرِيْنَ».","متفق عليه","صحيح"],["عن صَفِيَّةُ بِنْتُ حُيَيٍّ رضي الله عنها قالت: «كان النبي صلى الله عليه وسلم مُعْتَكِفًا، فَأَتَيْتُهُ أَزُورُهُ ليلا، فَحَدَّثْتُهُ، ثمَّ قُمْتُ لِأَنْقَلِبَ، فقام معي لِيَقْلِبَنِي -وكان مسكنها في دار أُسَامَةَ بن زَيْدٍ-، فَمَرَّ رَجُلاَنِ من الأنصار، فلما رأيا رسول الله صلى الله عليه وسلم أسرعا، فقال النبي صلى الله عليه وسلم : على رِسْلِكُمَا، إنها صَفِيَّةَ بِنْتُ حُيَيٍّ، فقالا: سبحان الله يا رسول الله، فقال: إن الشَّيْطَانَ يَجْرِي من ابن آدم مَجْرَى الدَّمِ، وإني خَشِيتُ أن يَقْذِفَ في قُلُوبِكُمَا شرا -أو قال شيئا-». وفي رواية: «أنها جاءَت تَزُورُهُ في اعْتِكَافِهِ في الْمَسْجِدِ، فِي العَشْرِ الأوَاخِرِ من رمضان، فتَحدَّثَتْ عنده ساعة، ثم قامت تَنقَلِبُ، فقام النبي صلى الله عليه وسلم معها يَقْلِبُهَا ، حتى إذا بَلَغَتْ باب المسجد عند باب أم سلمة...» ثم ذكره بمعناه.","متفق عليه","صحيح"]]],["العشر الأواخر من رمضان",[["عن أنس بن مالك قال: كان النبي صلى الله عليه وسلم يعتكف في العشر الأواخر من رمضان، فلم يعتكف عامًا، فلما كان في العام المقبل اعتكف عشرين.","رواه الترمذي","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «مَنْ يَقُمْ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ»","متفق عليه","صحيح"],["عن أبي سعيد الخُدْري رضي الله عنه : «أن رسول الله صلى الله عليه وسلم كان يَعْتَكِفُ في العَشْرِ الأَوْسَطِ من رمضان. فاعتكف عامًا، حتى إذا كانت لَيْلَةَ إِحْدَى وَعِشْرِينَ -وهي اللَّيْلَةُ التي يخرج من صَبِيحَتِهَا من اعتكافه- قال: من اعتكف معي فَلْيَعْتَكِفِ العَشْرَ الأَوَاخِرَ فقد أُرِيتُ هَذِهِ اللَّيْلَةَ ثم أُنْسِيتُهَا، وقد رَأَيْتُنِي أَسْجُدُ فِي مَاءٍ وَطِينٍ من صَبِيحَتِهَا، فَالْتَمِسُوهَا فِي العَشْرِ الأَوَاخِرِ، والتمسوها في كل وِتْرٍ. فَمَطَرَتِ السَّمَاءُ تلك الليلة، وكان المسجد على عَرِيشٍ، فَوَكَفَ المسجد، فَأبْصَرَتْ عَيْنَايَ رسول الله صلى الله عليه وسلم وعلى جَبْهَتِهِ أَثَرُ المَاءِ وَالطِّين من صُبْحِ إحْدَى وَعشْرِيْنَ».","متفق عليه","صحيح"]]],["رمضان",[["عن أبي بكرة عن النبي صلى الله عليه وسلم قال: \"شهران لا ينقصان، شهرا عيد: رمضان، وذو الحجة\".","متفق عليه","صحيح"],["عن أبي هريرة أن رسول الله صلى الله عليه وسلم قال: «من قام رمضان إيمانًا واحتسابًا غفر له ما تقدم من ذنبه».","متفق عليه","صحيح"],["عن أبي هريرة، قال: كان يعرض على النبي صلى الله عليه وسلم القرآن كل عام مرة، فعرض عليه مرتين في العام الذي قبض فيه، وكان يعتكف كل عام عشرا، فاعتكف عشرين في العام الذي قبض فيه.","رواه البخاري","صحيح"]]]]],["الزكاة والصدقة",0,[["وجوب الزكاة وحكم تاركها",[["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: \"مَن آتاه الله مالًا فلم يؤدِّ زكاتَه مُثِّلَ له مالُه يوم القيامة شجاعًا أقرعَ له زَبِيبتان يُطَوَّقُه يوم القيامة، ثم يأخذ بلهزمَيه -يعني بشدقيه- ثم يقول: أنا مالك، أنا كنزك، ثم تلا: (لا يحسبن الذين يبخلون)\" الآية.","رواه البخاري","صحيح"],["عَنْ عَبْدِ اللهِ بنِ عُمَر رضي الله عنهما قال: قال رسولُ الله صلى الله عليه وسلم: «بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ الْبَيْتِ، وَصَوْمِ رَمَضَانَ».","متفق عليه","صحيح"],["عن أَنَسَ بْنَ مَالِكٍ رضي الله عنه قال: بينما نحن جلوس مع النبي صلى الله عليه وسلم في المسجد دخل رجل على جمل، فأناخه في المسجد ثم عقله، ثم قال لهم: أيكم محمد؟ والنبي صلى الله عليه وسلم متكئ بين ظهرانيهم، فقلنا: هذا الرجل الأبيض المتكئ. فقال له الرجل: يا ابن عبد المطلب فقال له النبي صلى الله عليه وسلم: «قد أجبتك». فقال الرجل للنبي صلى الله عليه وسلم: إني سائلك فمشدد عليك في المسألة، فلا تجد علي في نفسك؟ فقال: «سل عما بدا لك» فقال: أسألك بربك ورب من قبلك، آلله أرسلك إلى الناس كلهم؟ فقال: «اللهم نعم». قال: أنشدك بالله، آلله أمرك أن نصلي الصلوات الخمس في اليوم والليلة؟ قال: «اللهم نعم». قال: أنشدك بالله، آلله أمرك أن نصوم هذا الشهر من السنة؟ قال: «اللهم نعم». قال: أنشدك بالله، آلله أمرك أن تأخذ هذه الصدقة من أغنيائنا فتقسمها على فقرائنا؟ فقال النبي صلى الله عليه وسلم: «اللهم نعم». فقال الرجل: آمنت بما جئت به، وأنا رسول من ورائي من قومي، وأنا ضمام بن ثعلبة أخو بني سعد بن بكر.","متفق عليه","صحيح"],["عن بهز بن حكيم قال: حدثني أبي عن جدي قال: سمعت النبي صلى الله عليه وسلم يقول: «في كل إبل سائمة في كل أربعين ابنة لبون، لا يُفرَّق إبلٌ عن حسابها، من أعطاها مؤتجرًا فله أجرها، ومن أبى فإنا آخذوها وشطر إبله، عزمة من عزمات ربنا، لا يحل لآل محمد صلى الله عليه وسلم منها شيء».","رواه أبو داود والنسائي","حسن"]]],["فضل الزكاة",[["عن سلمان بن عامر عن النبي صلى الله عليه وسلم قال: «إن الصدقة على المسكين صدقةٌ، وعلى ذي الرَّحِمِ اثنتان: صدقةٌ وصِلَةٌ».","رواه الترمذي والنسائي وابن ماجه","صحيح"]]],["شروط الزكاة",[["عن موسى بن طلحة قال: عندنا كتاب معاذ عن النبي صلى الله عليه وسلم أنه إنما أخذ الصدقة من الحنطة والشعير والزبيب والتمر.","رواه أحمد","صحيح"]]],["أحكام ومسائل الزكاة",[["عن سلمان بن عامر عن النبي صلى الله عليه وسلم قال: «إن الصدقة على المسكين صدقةٌ، وعلى ذي الرَّحِمِ اثنتان: صدقةٌ وصِلَةٌ».","رواه الترمذي والنسائي وابن ماجه","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «ليس على المُسلِم في عبدِهِ وَلاَ فَرَسهِ صَدَقَة». وفي لفظ: «إلا زكاة الفِطر في الرقيق».","متفق عليه","صحيح"],["عن جرير بن عبد الله قال: جاء ناس من الأعراب إلى رسول الله صلى الله عليه وسلم فقالوا: إن ناسًا من المُصَدِّقِينَ يأتوننا فيظلموننا، قال: فقال رسول الله صلى الله عليه وسلم: «أرضوا مُصَدِّقِيكُم» قال جرير: ما صدر عني مصدق منذ سمعت هذا من رسول الله صلى الله عليه وسلم إلا وهو عني راض.","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه قال: «بعث رسول الله صلى الله عليه وسلم عمر رضي الله عنه على الصدقة. فقيل: منع ابن جميل وخالد بن الوليد، والعباس عم رسول الله صلى الله عليه وسلم . فقال رسول الله صلى الله عليه وسلم ما يَنْقِم ابن جميل إلا أن كان فقيرا: فأغناه الله؟ وأما خالد: فإنكم تظلمون خالدا؛ فقد احْتَبَسَ أَدْرَاعَهُ وَأَعْتَادَهُ في سبيل الله. وأما العباس: فهي عليَّ ومثلها. ثم قال: يا عمر، أما شَعَرْتَ أن عمَّ الرجل صِنْوُ أبيه؟».","متفق عليه","صحيح"],["عن علي قال: قال رسول الله صلى الله عليه وسلم: \"قد عفوتُ عن الخيل والرقيق، فهاتوا صدقة الرِّقَةِ، من كل أربعين درهمًا درهمًا، وليس في تسعين ومائة شيء، فإذا بلغت مائتين ففيها خمسة دراهم\".","رواه أبو داود والترمذي والنسائي وابن ماجه","حسن"],["عن عوف بن مالك قال: دخل علينا رسول الله صلى الله عليه وسلم المسجد، وبيده عصا، وقد علق رجل قِنًا حَشَفًا، فطعن بالعصا في ذلك القِنْو، وقال: \"لو شاء رب هذه الصدقة تصدق بأطيب منها\" وقال: \"إن رب هذه الصدقة يأكل الحشف يوم القيامة\".","رواه أبو داود والنسائي وابن ماجه","حسن"]]],["زكاة النقدين",[["عن أبي سعيد الْخُدْرِي رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ليس فيما دون خمس أَوَاقٍ صدقة، ولا فيما دون خمس ذَوْدٍ صدقة، ولا فيما دُونَ خمسة أَوْسُقٍ صدقة».","متفق عليه","صحيح"],["عن علي قال: قال رسول الله صلى الله عليه وسلم: \"قد عفوتُ عن الخيل والرقيق، فهاتوا صدقة الرِّقَةِ، من كل أربعين درهمًا درهمًا، وليس في تسعين ومائة شيء، فإذا بلغت مائتين ففيها خمسة دراهم\".","رواه أبو داود والترمذي والنسائي وابن ماجه","حسن"],["عن عبد الله بن شداد بن الهاد، أنه قال: دخلنا على عائشة زوج النبي صلى الله عليه وسلم، فقالت: دخل علي رسول الله صلى الله عليه وسلم، فرأى في يدي فَتَخَات من وَرِق، فقال: \"ما هذا يا عائشة؟\" فقلت: صنعتهن أتزين لك يا رسول الله، قال: \"أتؤدين زكاتهن؟\" قلت: لا، أو ما شاء الله، قال: \"هو حسبك من النار\".","رواه أبو داود","حسن"]]],["زكاة بهيمة الأنعام",[["عن أبي سعيد الْخُدْرِي رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ليس فيما دون خمس أَوَاقٍ صدقة، ولا فيما دون خمس ذَوْدٍ صدقة، ولا فيما دُونَ خمسة أَوْسُقٍ صدقة».","متفق عليه","صحيح"]]],["زكاة الخارج من الأرض",[["عن ابن عمر عن النبي صلى الله عليه وسلم قال: «فيما سقت السماء والعيون أو كان عَثَرِيًّا العشر، وما سقي بالنَّضْحِ نصف العشر».","رواه البخاري","صحيح"],["عن أبي سعيد الْخُدْرِي رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ليس فيما دون خمس أَوَاقٍ صدقة، ولا فيما دون خمس ذَوْدٍ صدقة، ولا فيما دُونَ خمسة أَوْسُقٍ صدقة».","متفق عليه","صحيح"]]],["زكاة الفطر",[["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «ليس على المُسلِم في عبدِهِ وَلاَ فَرَسهِ صَدَقَة». وفي لفظ: «إلا زكاة الفِطر في الرقيق».","متفق عليه","صحيح"],["عن ابن عباس قال: فرض رسول الله صلى الله عليه وسلم زكاة الفطر طُهرةً للصائم من اللغو والرفث، وطعمةً للمساكين، من أداها قبل الصلاة، فهي زكاة مقبولة، ومن أداها بعد الصلاة، فهي صدقة من الصدقات.","رواه أبو داود وابن ماجه","حسن"]]],["مصارف الزكاة",[["عن أنس رضي الله عنه قال: مَرَّ النبي صلى الله عليه وسلم بتمرةٍ في الطريق، قال: «لولا أني أخاف أن تكون من الصدقة لأكلتها».","متفق عليه","صحيح"],["عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم: «مَن سأل الناس أموالهم تكثُّرًا فإنما يسأل جمرًا فليَستقلَّ أو ليستكثرْ».","رواه مسلم","صحيح"],["عن عبد الله بن عمر رضي الله عنه قال: قال النبي صلى الله عليه وسلم: «ما يزال الرجل يسأل الناس حتى يأتي يوم القيامة ليس في وجهه مُزْعَة لحم».","متفق عليه","صحيح"],["عن عبد الله بن أبي أوفى قال: كان النبي صلى الله عليه وسلم إذا أتاه قوم بصدقتهم قال: «اللهم صل على آل فلان»، فأتاه أبي بصدقته، فقال: «اللهم صل على آل أبي أوفى».","متفق عليه","صحيح"],["عن ابن عمر أن النبي صلى الله عليه وسلم بعث سعدَ بنَ عُبادة مُصَدِّقًا، وقال: «إياك يا سعد أن تجيء يوم القيامة ببعير له رُغَاءٌ»، فقال: لا أجده ولا أجيء به، فأعفاه.","رواه ابن حبان","صحيح"],["عن معاوية بن أبي سفيان رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «لا تُلْحِفُوا في المسأَلة، فوالله لا يَسْألني أحدٌ منكم شيئًا، فَتُخْرِجَ له مسألته منِّي شيئًا وأنا له كارِهٌ، فيُبَارَك له فيما أَعْطَيتُه».","رواه مسلم","صحيح"],["عن أبي رافع: أن النبي صلى الله عليه وسلم بعث رجلًا على الصدقة من بني مخزوم، فقال لأبي رافع: اصحبني فإنك تصيب منها، قال: حتى آتي النبي صلى الله عليه وسلم فأسأله، فأتاه فسأله، فقال: \"مولى القوم من أنفسهم، وإنا لا تحل لنا الصدقة\".","رواه أبو داود والترمذي والنسائي","صحيح"],["عن أبي هريرة رضي الله عنه قال: أخذ الحسن بن علي رضي الله عنهما تمرة من تمر الصدقة فجعلها في فيه، فقال رسول الله صلى الله عليه وسلم : «كَخْ كَخْ ارْمِ بها، أما علمت أنَّا لا نأكل الصدقة!؟». وفي رواية: «أنَّا لا تَحِلُّ لنا الصدقة».","الرواية الأولى: متفق عليه.\nالرواية الثانية: رواها مسلم","صحيح"],["عن قَبِيصة بن مُخَارق الهلالي قال: تحمَّلت حَمَالةً، فأتيت رسول الله صلى الله عليه وسلم أسأله فيها، فقال: \"أقم حتى تأتينا الصدقة، فنأمر لك بها\" ثم قال: \"يا قَبيصة إن المسألة لا تحل إلا لأحد ثلاثة: رجل تحمل حمالة، فحَلَّت له المسألة حتى يُصيبها، ثم يمسك، ورجل أصابته جائحة اجتاحت ماله، فحلت له المسألة حتى يصيب قِوَامًا من عيش -أو قال سدادًا من عيش-، ورجل أصابته فاقة حتى يقوم ثلاثة من ذوي الحِجَا من قومه: لقد أصابت فلانا فاقة، فحلت له المسألة حتى يصيب قوامًا من عيش -أو قال سدادًا من عيش-، فما سواهن من المسألة يا قبيصة سحتًا يأكلها صاحبها سحتًا\".","رواه مسلم","صحيح"]]],["صدقة التطوع",[["عن أبي هريرة أنه قال: يا رسول الله، أي الصدقة أفضل؟ قال: \"جُهْدُ المُقِلِّ، وابدأ بمن تَعُول\".","رواه أبو داود","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «قَالَ اللهُ: أَنْفِقْ يَا ابْنَ آدَمَ أُنْفِقْ عَلَيْكَ».","متفق عليه","صحيح"],["عن عائشة رضي الله عنها : أنهم ذبحوا شاة فقال النبي صلى الله عليه وسلم : «ما بقي منها؟» قالت: ما بقي منها إلا كتفها. قال: «بقي كلها غير كتفها».","رواه الترمذي","صحيح"],["عن مالك بن نضلة قال: قال رسول الله صلى الله عليه وسلم: \"الأيدي ثلاثة: فيدُ الله العليا، ويدُ المعطي التي تليها، ويدُ السائل السفلى، فأعط الفضل، ولا تعجز عن نفسك\".","رواه أبو داود","صحيح"],["عن أبي مسعود الأنصاري رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا أَمَرَنا بالصدقة انطلق أحدُنا إلى السوق، فيُحامِل، فيصيب المد، وإن لبعضهم لمائة ألف. قال: ما نراه إلا نفسه.","رواه البخاري","صحيح"],["عن أبي مسعود رضي الله عنه قال: جاء رجل إلى النبي صلى الله عليه وسلم بناقة مَخْطُومَةٍ، فقال: هذه في سبيل الله، فقال رسول الله صلى الله عليه وسلم : «لك بها يوم القيامة سبعمائة ناقة كلها مخطومة».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: «مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ، وَمَا زَادَ اللهُ عَبْدًا بِعَفْوٍ إِلَّا عِزًّا، وَمَا تَوَاضَعَ أَحَدٌ لِلهِ إِلَّا رَفَعَهُ اللهُ».","رواه مسلم","صحيح"],["عن ابن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «أيُّكم مالُ وارثِه أحَبُّ إليه من مالَه؟» قالوا: يا رسول الله، ما منَّا أحد إلا مَالُه أحَبُّ إليه. قال: «فإن مالَه ما قدَّم، ومالُ وارثِه ما أخَّر».","رواه البخاري","صحيح"],["عن أسماء بنت أبي بكر الصديق رضي الله عنهما قالت: قال لي رسول الله صلى الله عليه وسلم : «لا تُوكِي فيُوكَى عليك». وفي رواية: «أَنْفِقِي أو انْفَحِي، أو انْضَحِي، ولا تُحْصِي فيُحْصِي الله عليك، ولا تُوعِي فيُوعِي الله عليك».","متفق عليه","صحيح"],["عن أم بجيد، وكانت ممن بايع رسول الله صلى الله عليه وسلم، أنها قالت: يا رسول الله، إن المسكين ليقوم على بابي فما أجد له شيئًا أعطيه إياه، فقال لها رسول الله صلى الله عليه وسلم: \"إلم تجدي له شيئًا تعطيه إياه إلا ظِلْفًا مُحْرَقًا فادفعيه إليه في يده\".","رواه أبو داود والترمذي والنسائي","صحيح"]]]]],["الحج والعمرة",0,[["وجوب الحج والعمرة وحكم تاركهما",[["عن ابن عباس عن النبي صلى الله عليه وسلم لقي ركبًا ‌بالرَّوحاء، فقال: «من القوم؟» قالوا: المسلمون، فقالوا: من أنت؟ قال: «رسول الله»، فرفعت إليه امرأة صبيًّا، فقالت: ألهذا حج؟ قال: «نعم، ولك أجر».","رواه مسلم","صحيح"],["عن ابن عباس أن امرأة جاءت إلى النبي صلى الله عليه وسلم، فقالت: إن أمي نذرت أن تحج فماتت قبل أن تحج، أفأحج عنها؟ قال: «نعم، حجي عنها، أرأيت لو كان على أمك دين أكنت ‌قاضيته؟»، قالت: نعم، فقال: «اقضوا الله الذي له، فإن الله أحق بالوفاء».","متفق عليه","صحيح"],["عَنْ عَبْدِ اللهِ بنِ عُمَر رضي الله عنهما قال: قال رسولُ الله صلى الله عليه وسلم: «بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ الْبَيْتِ، وَصَوْمِ رَمَضَانَ».","متفق عليه","صحيح"],["عن ابن عباس عن الفضل -أو أحدهما عن الآخَر- قال: قال رسول الله صلى الله عليه وسلم: \"مَن أراد الحج فليتعجَّل، فإنه قد يمرض المريض، وتضل الضالة، وتعرض الحاجة\".","رواه أبو داود وابن ماجه","حسن"]]],["فضل الحج والعمرة",[["عن عائشة أم المؤمنين رضي الله عنها قالت: استأذنت النبي صلى الله عليه وسلم في الجهاد، فقال: «جهادكن الحج».","رواه البخاري","صحيح"],["عن أبي هريرة رضي الله عنه: أن رسول الله صلى الله عليه وسلم قال: «العمرة إلى العمرة كفارةٌ لما بينهما، والحج المبرور ليس له جزاءٌ إلا الجنة».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: سمعت النبي صلى الله عليه وسلم يقول: «مَنْ حَجَّ لِلهِ فَلَمْ يَرْفُثْ وَلَمْ يَفْسُقْ رَجَعَ كَيَوْمِ وَلَدَتْهُ أُمُّهُ».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «للعبد المملوك المصلح أجران»، والذي نفس أبي هريرة بيده لولا الجهاد في سبيل الله والحج، وبِرُّ أمي، لأحببت أن أموت وأنا مملوك.","متفق عليه","صحيح"],["عن عبد الله بن عُمر رضي الله عنهما عن رسول الله صلى الله عليه وسلم أنه قال: «اللَّهُمَّ ارحم الْمُحَلِّقِينَ. قالوا: والْمُقَصِّرِينَ يا رسول الله؟ قال: اللهم ارحم الْمُحَلِّقِينَ. قالوا: والْمُقَصِّرِينَ يا رسول الله؟ قال: اللهم ارحم الْمُحَلِّقِينَ. قالوا: والْمُقَصِّرِينَ يا رسول الله؟ قال: والْمُقَصِّرِينَ».","متفق عليه","صحيح"],["عن عبد الله بن عمر قال: سمعت رسول الله صلى الله عليه وسلم يقول: \"من طاف بالبيت وصلى ركعتين كان كعتق رقبة\".","رواه ابن ماجه","حسن"]]],["العشر من ذي الحجة",[["عن أبي بكرة عن النبي صلى الله عليه وسلم قال: \"شهران لا ينقصان، شهرا عيد: رمضان، وذو الحجة\".","متفق عليه","صحيح"],["عن ابن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: «ما مِنْ أيَّامٍ العمَلُ الصَّالِحُ فيها أحبُّ إلى اللهِ مِن هذه الأيام» يعني أيامَ العشر، قالوا: يا رسُولَ الله، ولا الجهادُ في سبيلِ الله؟ قال: «ولا الجهادُ في سبيلِ الله، إلا رجلٌ خَرَجَ بنفسِه ومالِه فلم يَرْجِعْ من ذلك بشيءٍ».","رواه البخاري وأبو داود، واللفظ له","صحيح"]]],["أحكام المسجد الحرام والمسجد النبوي وبيت المقدس",[["عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «ما بين بيتي ومنبري روضة من رياض الجنة، ومنبري على حوضي».","متفق عليه","صحيح"],["عن عبد الله بن زيد بن عاصم أن رسول الله صلى الله عليه وسلم قال: «إن إبراهيم حرَّم مكة ودعا لأهلها، وإني ‌حرمت المدينة كما حرم إبراهيم مكة، وإني ‌دعوت في صاعها ومدها بمثلي ما دعا به إبراهيم لأهل مكة».","متفق عليه","صحيح"],["عن أبي سعيد الخدري قال: دخلت على رسول الله صلى الله عليه وسلم في بيت بعض نسائه، فقلت: يا رسول الله، أي المسجدين الذي أسس على التقوى؟ قال: فأخذ كفًّا من حصباء، فضرب به الأرض، ثم قال: «هو مسجدكم هذا» لمسجد المدينة.","رواه مسلم","صحيح"],["عن أبي ذر رضي الله عنه قال: قلت يا رسول الله، أي مسجد وضع في الأرض أول؟ قال: «المسجد الحرام» قال: قلت: ثم أي؟ قال «المسجد الأقصى» قلت: كم كان بينهما؟ قال: «أربعون سنة، ثم أينما أدركتك الصلاة بعدُ فَصَلِّه، فإن الفضل فيه».","متفق عليه","صحيح"],["عن عائشة رضي الله عنها أن رسول الله صلى الله عليه وسلم قال: «خمسٌ من الدَّوَابِّ كُلُّهُنَّ فَاسِقٌ، يُقْتَلنَ في الحَرَمِ: الغرابُ، وَالحِدَأَةُ، وَالعَقْرَبُ، وَالفَأْرَةُ، وَالكَلْبُ العَقُورُ». وفي رواية: « يقتل خَمْسٌ فَوَاسِق في الْحِلِّ وَالْحَرَمِ ».","متفق عليه.\nوفي مسلم \"الغراب الأبقع\"","صحيح"],["عن عبد الله بن عمر أن رسول الله صلى الله عليه وسلم دخل الكعبة وأسامة بن زيد وبلال وعثمان بن طلحة الحجبي، فأغلقها عليه، ومكث فيها، فسألتُ بلالًا حين خرج: ما صنع النبي صلى الله عليه وسلم؟ قال: جعل عمودًا عن يساره، وعمودًا عن يمينه، وثلاثةَ أعمدةٍ وراءه، وكان البيت يومئذٍ على ‌ستة ‌أعمدة، ثم صلى، وفي رواية: «عمودين عن يمينه».","متفق عليه","صحيح"],["عن ‌عائشة رضي الله عنها قالت: سألت النبي صلى الله عليه وسلم عن الجَدْرِ أَمِنَ البيتِ هو؟ قال: «نعم» قلت: فما لهم لم يدخلوه في البيت؟ قال: «إن ‌قومك قَصُرَتْ بهم النفقة» قلت: فما شأن بابه مرتفعًا؟ قال: «فعل ذلك ‌قومك، ليدخلوا من شاؤوا ويمنعوا من شاؤوا، ولولا أن ‌قومك ‌حديث عهدهم بالجاهلية، فأخاف أن تنكر قلوبهم، أن أدخل الجدر في البيت، وأن ألصق بابه بالأرض».","رواه البخاري","صحيح"],["عن عبد الله بن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم يوم فتح مكة: «لا هجرة بعد الفتح، ولكن جهاد ونية. وإذا اسْتُنْفِرْتُم فَانْفِرُوا. وقال يوم فتح مكة: «إن هذا البَلد حَرَّمَهُ الله يوم خلق الله السموات والأرض، فهو حَرَامٌ بحُرْمَةِ الله إلَى يوم القيامة، وإنه لم يحل القتال فيه لِأَحَدٍ قَبْلِي، ولم يَحِلَّ لي إلا ساعة من نهار، حرام بِحرمة الله إلى يوم القيامة، لا يُعْضَدُ شَوْكُهُ، وَلاَ يُنَفَّرُ صَيْدُهُ، وَلاَ يَلْتَقِطُ لُقَطَتَهُ إلا من عَرَّفَهَا، ولاَ يُخْتَلَى خَلاَهُ». فقال العباس: يا رسول الله، إلا الإِذْخِرَ؛ فإنه لِقَيْنِهِمْ وبيوتهم؟ فقال: «إلا الإِذْخِرَ».","متفق عليه","صحيح"],["عن يزيد بن شريك بن طارق، قال: رأيت عليًّا رضي الله عنه على المنبر يخطب، فسمعته يقول: لا والله ما عندنا من كتاب نقرؤه: إلا كتاب الله، وما في هذه الصَّحِيفَةِ، فنشرها؛ فإذا فيها: أَسْنَانُ الإبل، وأشياء من الجِرَاحَاتِ. وفيها: قال رسول الله صلى الله عليه وسلم : «المدينة حَرَمٌ ما بين عَيْرٍ إلى ثَوْرٍ، فمن أحدث فيها حَدَثًا، أو آوى مُحْدِثًا؛ فعليه لعنة الله والملائكة والناس أجمعين، لا يقبل الله منه يوم القيامة صَرْفًا ولا عَدْلًا. ذِمَّةُ المسلمين واحدة، يسعى بها أَدْنَاهُم، فمن أَخْفَرَ مسلما، فعليه لعنة الله والملائكة والناس أجمعين، لا يقبل الله منه يوم القيامة صَرْفًا ولا عَدْلًا. ومن ادعى إلى غير أبيه، أو انتمى إلى غير مواليه، فعليه لعنة الله والملائكة والناس أجمعين؛ لا يقبل الله منه يوم القيامة صَرْفًا ولا عَدْلًا».","متفق عليه","صحيح"]]],["مواقيت الحج والعمرة",[["عن ابن عباس قال: إن النبي صلى الله عليه وسلم وقت لأهل المدينة ذا الحليفة، ولأهل الشأم الجُحْفة، ولأهل نجد قَرْن المنازل، ولأهل اليمن يَلَمْلَم، هن لهن، ولمن أتى عليهن من غيرهن ممن أراد الحج والعمرة، ومن كان دون ذلك، فمن حيث أنشأ حتى أهل مكة من مكة.","متفق عليه","صحيح"]]],["أحكام الإحرام",[["عن عائشة قالت: كأني أنظر إلى وَبِيص الطيب، في مَفْرِق النبي صلى الله عليه وسلم، وهو محرم.","متفق عليه","صحيح"],["عن عائشة رضي الله عنها زوج النبي صلى الله عليه وسلم قالت: كنت أُطيِّب رسول الله صلى الله عليه وسلم لإحرامه حين يحرم، ولحله قبل أن يطوف بالبيت.","متفق عليه","صحيح"],["عن زيد بن خالد الجهني قال: قال رسول الله صلى الله عليه وسلم: \"جاءني جبريل فقال: يا محمد، مر أصحابك فليرفعوا أصواتهم بالتلبية، فإنها من شعار الحج\".","رواه ابن ماجه","صحيح"],["عن جابرٍ رضي الله عنه قال: قدِمنا مع رسولِ الله صلى الله عليه وسلم ، ونحنُ نقولُ: لبيك بالحجِّ، فأمرَنا رسولُ الله صلى الله عليه وسلم فجعلناها عُمرةً.","متفق عليه","صحيح"],["عن ابن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: «هذه عمرةٌ استَمْتَعنا بها، فمن لم يكن عنده الهدي فليحل الحل كله، فإن ‌العمرة قد ‌دخلت في الحج إلى يوم القيامة».","رواه مسلم","صحيح"],["عن ابن عباس أن النبي صلى الله عليه وسلم سمع رجلًا يقول: لبيك عن شُبْرُمة، قال: \"‌من ‌شبرمة؟\" قال: أخ لي، أو قريب لي، قال: \"حججت عن نفسك؟\" قال: لا، قال: \"حُجَّ عن نفسك ثم حُجَّ عن شبرمة\".","رواه أبو داود وابن ماجه","صحيح"],["عن ابن عباس عن النبي صلى الله عليه وسلم لقي ركبًا ‌بالرَّوحاء، فقال: «من القوم؟» قالوا: المسلمون، فقالوا: من أنت؟ قال: «رسول الله»، فرفعت إليه امرأة صبيًّا، فقالت: ألهذا حج؟ قال: «نعم، ولك أجر».","رواه مسلم","صحيح"],["عن عائشة أم المؤمنين قالت: كنا نخرج مع النبي صلى الله عليه وسلم إلى مكة فنُضَمِّدُ جباهنا بالسُّكِّ المطيَّب عند الإحرام، فإذا عَرِقَتْ إحدانا سال على وجهها فيراه النبي صلى الله عليه وسلم فلا ينهاها.","رواه أبو داود","صحيح"],["عن عائشة قالت: دخل رسول الله صلى الله عليه وسلم على ضُبَاعة بنت الزبير، فقال لها: «لعلك أردت الحج؟» قالت: والله لا أجدني إلا وَجِعة، فقال لها: «حجي واشترطي، وقولي: اللهم محلي حيث حبستني»، وكانت تحت المقداد بن الأسود.","متفق عليه","صحيح"]]],["محظورات الإحرام",[["عن يَزِيد بن الأصمِّ قال: حدَّثَتْني مَيْمونَة بنت الحارث رضي الله عنها «أن رسول الله صلى الله عليه وسلم تَزَوَّجها وهو حلال»، قال: «وكانت خالَتي، وخالةَ ابنِ عباس».","رواه مسلم","صحيح"],["عن الصعب بن جَثَّامَةَ رضي الله عنه ، قال: أهديتُ رسولَ الله - صلى الله عليه وسلم - حماراً وحشياً، فَرَدَّهُ عَلَيَّ، فلما رأى ما في وجهي، قال: «إنا لم نَرُدَّهُ عليك إلا لأنَّا حُرُمٌ».","متفق عليه","صحيح"],["عن عبد الله بن زيد بن عاصم أن رسول الله صلى الله عليه وسلم قال: «إن إبراهيم حرَّم مكة ودعا لأهلها، وإني ‌حرمت المدينة كما حرم إبراهيم مكة، وإني ‌دعوت في صاعها ومدها بمثلي ما دعا به إبراهيم لأهل مكة».","متفق عليه","صحيح"],["عن عبد الله بن عباس رضي الله عنهما قال: «سمعت رسول الله صلى الله عليه وسلم يخطب بِعَرَفَاتٍ: من لم يَجِدْ نَعْلَيْنِ فَلْيَلْبَسِ الخُفَّيْنِ، ومن لَمْ يَجِدْ إِزَارًا فَلْيَلْبَسْ السَّرَاوِيلَ -للمحرم-».","رواه البخاري","صحيح"],["عن عبد الله بن عباس رضي الله عنهما قال: «بينما رجل واقف بِعَرَفَةَ، إذ وقع عن راحلته، فَوَقَصَتْهُ -أو قال: فَأوْقَصَتْهُ- فقال رسول الله صلى الله عليه وسلم : اغْسِلُوهُ بماء وسدر، وكَفِّنُوهُ في ثوبيه، ولا تُحَنِّطُوهُ، ولا تُخَمِّرُوا رأسه؛ فإنه يُبْعَثُ يوم القيامة مُلبِّياً».","متفق عليه","صحيح"],["عن عبد الله بن عمر رضي الله عنهما «أن رجلًا قال يا رسول الله، ما يَلْبَسُ المُحْرِمُ مِنَ الثياب؟ قال رسول الله صلى الله عليه وسلم : لا يلبسُ القميص، ولا العَمَائِمَ ، وَلاَ السَّرَاوِيلاَتِ، ولا البَرَانِسَ، ولا الخِفَافَ، إلا أحدٌ لا يجِدُ نَعْلَيْنِ، فَلْيَلْبَسْ خُفَّيْنِ، وَلْيَقْطَعْهُمَا أسفلَ من الكعبين، وَلا يَلْبَسْ من الثياب شيئا مَسَّهُ زَعْفَران أوْ وَرْسٌ»، وللبخاري: «ولا تَنْتَقِبُ المرأة، وَلا تلبس الْقُفَّازَيْنِ».","متفق عليه","صحيح"],["عن صفوان بن يَعْلَى: أنَّ يَعْلَى قال لعمر رضي الله عنه : أَرِني النبيَّ صلى الله عليه وسلم حِين يُوحَى إليه، قال: «فبيْنَما النبي صلى الله عليه وسلم بالجِعِرَّانة، ومعه نَفَرٌ من أصحابه، جاءه رجل فقال: يا رسول الله، كيف ترى في رجل أحْرَم بعمرة، وهو مُتَضَمِّخٌ بطِيب، فسكت النبيُّ صلى الله عليه وسلم ساعة، فجاءه الوحْي، فأشار عمر رضي الله عنه إلى يَعْلَى، فجاء يَعْلَى وعلى رسول الله صلى الله عليه وسلم ثوْب قد أُظِلَّ به، فأَدخَل رأسه، فإذا رسول الله صلى الله عليه وسلم مُحْمَرُّ الوجه، وهو يَغِطُّ، ثم سُرِّيَ عنه، فقال: «أين الذي سأل عن العمرة؟» فأُتي برجل، فقال: «اغسل الطِّيبَ الذي بِكَ ثلاث مرات، وانزِعْ عنك الجُبَّة، واصنع في عُمرتك كما تصنعُ في حَجَّتك» قلت لعطاء: أراد الإنقاء حين أمره أن يغسل ثلاث مرات؟ قال: «نعم».","متفق عليه","صحيح"]]],["الفدية وجزاء الصيد",[["عن سعد بن أبي وقاص قال: قال رسول الله صلى الله عليه وسلم: «إني أحرِّم ما بين لَابَتَي المدينة أن يُقطع عِضَاهُها أو يقتل صيدها»، وقال: «المدينة ‌خير ‌لهم ‌لو كانوا يعلمون، لا يدعها أحد رغبة عنها إلا أبدل الله فيها من هو خير منه، ولا يثبت أحد على لأوائها وجهدها إلا كنت له شفيعًا أو شهيدًا يوم القيامة».","متفق عليه","صحيح"],["عن عبد الله بن مَعْقِلٍ قال: «جلستُ إلى كَعْبِ بن عُجْرَةَ، فسألته عن الفدية، فقال: نزلت فِيَّ خاصة. وهي لكم عامة. حُمِلْتُ إلى رسول الله صلى الله عليه وسلم وَالقَمْلُ يَتَنَاثَرُ على وجهي. فقال: ما كُنْتُ أُرَى الوَجَعَ بَلَغَ بِكَ ما أَرَى -أو ما كنت أُرَى الجَهْدَ بلغ بك ما أَرى-! أَتَجِدُ شاة؟ فقلت: لا. فقال: صم ثلاثة أيام، أو أطعم ستة مساكين -لكل مسكين نصف صاع-». وفي رواية: «فأمره رسول الله صلى الله عليه وسلم أن يُطْعِمَ فَرَقًا بَيْنَ سِتَّةِ ، أو يُهْدِي شَاةً ، أو يصوم ثلاثة أيام».","متفق عليه","صحيح"],["عن أبي قَتَادَةَ الأنصاري رضي الله عنه «أن رسول الله صلى الله عليه وسلم خرج حاجًّا، فخرجوا معه، فصرف طائفة منهم -فيهم أبو قَتَادَةَ- وقال: خذوا ساحِل البحر حتى نَلْتَقِيَ. فأخذوا ساحل البحر، فلما انصرفوا أحرموا كلهم، إلا أبا قَتَادَةَ فلم يُحرم، فبينما هم يسيرون إذ رأوا حُمُرَ وَحْشٍ، فحمل أبو قَتَادَةَ على الْحُمُرِ، فَعَقَرَ منْها أَتَانَاً، فنزلنا فأكلنا من لحمها، ثم قلنا: أنأكل لحم صيد، ونحن محرمون؟ فحملنا ما بقي من لحمها فأدركنا رسول الله صلى الله عليه وسلم ، فسألناه عن ذلك؟ فقال: منكم أحد أمره أن يحمل عليها، أو أشار إليها؟ قالوا: لا، قال: فكلوا ما بقي من لحمها»، وفي رواية: «قال: هل معكم منه شيء؟ فقلت: نعم، فناولته الْعَضُدَ ، فأكل منها».","متفق عليه","صحيح"]]],["أنواع النسك",[["عن ابن عمر قال: أهللنا مع رسول الله صلى الله عليه وسلم ‌بالحج ‌مفرَدًا. وفي رواية: أن رسول الله صلى الله عليه وسلم أهلَّ ‌بالحج ‌مفرَدًا.","رواه مسلم","صحيح"],["عن عبد الله بن عباس رضي الله عنهما قال: «قَدِمَ رسول الله صلى الله عليه وسلم وأصحابه صَبِيحَةَ رَابِعَةٍ، فأمرهم أن يجعلوها عمرة، فقالوا: يا رسول الله، أَيُّ الحِلِّ؟ قال: الحِلُّ كُلُّهُ».","متفق عليه","صحيح"],["عن عائشة رضي الله عنها قالت: خرجنا مع رسول الله صلى الله عليه وسلم مُواِفينَ لهلال ذي الحجة، فقال رسول الله صلى الله عليه وسلم: «من أحب أن يهل بعمرة فليهل، ومن أحب أن يهل بحجة فليهل، ولولا أني أهديت لأهللت بعمرة»، فمنهم من أهل بعمرة، ومنهم من أهل بحجة، وكنت ممن أهل بعمرة، فحضت قبل أن أدخل مكة، فأدركني يوم عرفة وأنا حائض، فشكوت ذلك إلى رسول الله صلى الله عليه وسلم، فقال: «دعي عمرتك، وانقضي رأسك وامتشطي، وأَهِلِّي بالحج»، ففعلت، فلما كانت ليلةُ الحَصْبَة أرسل معي عبد الرحمن إلى التنعيم. فأردفها، فأهلت بعمرة مكان عمرتها، فقضى الله حجها وعمرتها، ولم يكن في شيء من ذلك هديٌ ولا صدقةٌ ولا صومٌ.","متفق عليه","صحيح"],["عن جابر بن عبد الله رضي الله عنهما قال: «أَهَلَّ النبيُّ صلى الله عليه وسلم وأصحابُه بالحج، وليس مع أحد منهم هَدْيٌ غير النبي صلى الله عليه وسلم وطلحة، وقدم علي رضي الله عنه من اليمن. فقال: أَهْلَلْتُ بما أَهَلَّ به النبي صلى الله عليه وسلم فأمر النبي صلى الله عليه وسلم أصحابه: أن يجعلوها عمرة، فيطوفوا ثم يُقَصِّرُوا ويَحِلُّوا، إلا من كان معه الهَدْي، فقالوا: ننطلق إلى مِنًى وَذَكَرُ أَحَدِنَا يَقْطُرُ؟ فبلغ ذلك النبي - صلى الله عليه وسلم- فقال: لَوِ اسْتَقْبَلْتُ من أَمْرِي مَا اسْتَدْبَرْتُ ؛ ما أَهْدَيْتُ ، ولولا أن معي الهَدْيَ لَأَحْلَلْتُ. وحاضت عائشة. فَنَسَكَتْ المنَاسِك كلها، غير أنها لم تَطُفْ بالبيت. فلما طَهُرت وطافت بالبيت قالت: يا رسول الله، تَنْطَلِقُونَ بحج وعمرة، وأنطلق بحج؟ فأمر عبد الرحمن بن أبي بكر: أن يخرج معها إلى التَّنْعِيمِ ، فاعتمرت بعد الحج».","متفق عليه","صحيح"]]],["صفة العمرة",[["عن ابن عباس رضي الله عنهما: أن رسول الله صلى الله عليه وسلم طاف بالبيت وهو على بعير، كلما أتى على الركن أشار إليه بشيء في ‌يده، ‌وكبر.","رواه البخاري","صحيح"],["عن جابر بن عبد الله أن النبي صلى الله عليه وسلم رمل ثلاثة أطواف من ‌الحَجَر ‌إلى ‌الحَجَر، وصلى ركعتين، ثم عاد إلى الحجر، ثم ذهب إلى زمزم فشرب منها، وصب على رأسه، ثم رجع فاستلم الركن، ثم رجع إلى الصفا، فقال: \"أبدأ بما بدأ الله عز وجل به\".","رواه أحمد","صحيح"]]],["واجبات العمرة",[["عن عائشة رضي الله عنها قالت: خرجنا مع رسول الله صلى الله عليه وسلم مُواِفينَ لهلال ذي الحجة، فقال رسول الله صلى الله عليه وسلم: «من أحب أن يهل بعمرة فليهل، ومن أحب أن يهل بحجة فليهل، ولولا أني أهديت لأهللت بعمرة»، فمنهم من أهل بعمرة، ومنهم من أهل بحجة، وكنت ممن أهل بعمرة، فحضت قبل أن أدخل مكة، فأدركني يوم عرفة وأنا حائض، فشكوت ذلك إلى رسول الله صلى الله عليه وسلم، فقال: «دعي عمرتك، وانقضي رأسك وامتشطي، وأَهِلِّي بالحج»، ففعلت، فلما كانت ليلةُ الحَصْبَة أرسل معي عبد الرحمن إلى التنعيم. فأردفها، فأهلت بعمرة مكان عمرتها، فقضى الله حجها وعمرتها، ولم يكن في شيء من ذلك هديٌ ولا صدقةٌ ولا صومٌ.","متفق عليه","صحيح"]]],["سنن العمرة",[["عن عائشة قالت: كأني أنظر إلى وَبِيص الطيب، في مَفْرِق النبي صلى الله عليه وسلم، وهو محرم.","متفق عليه","صحيح"],["عن صفية بنت شيبة عن امرأة قالت: رأيتُ رسول الله صلى الله عليه وسلم، يسعى في بطن المسيل، ويقول: «لا يُقطَعُ الوادي ‌إلا ‌شَدًّا».","رواه النسائي","صحيح"],["عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم جاء إلى السقاية فاستسقى، فقال العباس: يا فضلُ، اذهب إلى أمك فأت رسول الله صلى الله عليه وسلم بشراب من عندها، فقال: «اسقني»، قال: يا رسول الله، إنهم يجعلون أيديهم فيه، قال: «اسقني»، فشرب منه، ثم أتى زمزم وهم يسقون ويعملون فيها، فقال: «اعملوا فإنكم على عمل صالح» ثم قال: «‌لولا ‌أن ‌تغلبوا لنزلت، حتى أضع الحبل على هذه» يعني: عاتقه، وأشار إلى عاتقه.","رواه البخاري","صحيح"],["عن ابن عباس أن رسول الله صلى الله عليه وسلم وأصحابه اعتمروا من الجعرانة، فرملوا بالبيت، وجعلوا ‌أرديتهم تحت آباطهم ثم قذفوها على عواتقهم اليسرى.","رواه أبو داود","حسن"],["عن عبد الله بن السائب قال: سمعت رسول الله صلى الله عليه وسلم يقول ما بين ‌الرُّكْنينِ: {رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً ‌وَقِنَا عَذَابَ النَّارِ} [البقرة: 201].","رواه أبو داود","حسن"]]],["صفة الحج",[["عن ابن عباس أن النبي صلى الله عليه وسلم لم يرمل في ‌السبع ‌الذي ‌أفاض ‌فيه.","رواه أبو داود وابن ماجه","صحيح"],["عن ‌جابر قال: رمى رسول الله صلى الله عليه وسلم الجمرة يوم النحر ضحى، وأما بعدُ فإذا ‌زالت ‌الشمس.","رواه مسلم","صحيح"],["عن ابن عباس رضي الله عنهما قال: أنا ممن قدَّمَ النبي صلى الله عليه وسلم ليلة المزدلفة في ‌ضعفة ‌أهله.","متفق عليه","صحيح"],["عن ابن عباس رضي الله عنهما: أن رسول الله صلى الله عليه وسلم طاف بالبيت وهو على بعير، كلما أتى على الركن أشار إليه بشيء في ‌يده، ‌وكبر.","رواه البخاري","صحيح"],["عن عائشة رضي الله عنها زوج النبي صلى الله عليه وسلم قالت: كنت أُطيِّب رسول الله صلى الله عليه وسلم لإحرامه حين يحرم، ولحله قبل أن يطوف بالبيت.","متفق عليه","صحيح"],["عن جابر بن عبد الله رضي الله عنه قال: لم يَطُفِ النبي صلى الله عليه وسلم ولا أصحابه بين الصفا والمروة ‌إلا ‌طوافًا واحدًا. وفي رواية: طوافَه الأول.","رواه مسلم","صحيح"],["عن عبد الله بن عُمَر رضي الله عنه قال: «اسْتَأْذَنَ الْعَبَّاسُ بن عَبْدِ الْمُطَّلِب رسول الله صلى الله عليه وسلم : أن يبيت بمكة ليالي مِنى، من أجل سِقَايَتِه فأذن له».","متفق عليه","صحيح"],["عن عُرْوَةَ بن الزُّبَيْرِ قال: «سُئل أُسَامَةُ بن زَيْدٍ -وأنا جالس- كيف كان رسول الله صلى الله عليه وسلم يسيرُ حِينَ دَفَعَ؟ قال: كان يَسيرُ العَنَقَ، فإذا وجد فَجْوَةً نَصَّ».","متفق عليه","صحيح"],["عن أنس بن مالك رضي الله عنه ، قال: حَجَّ النبي صلى الله عليه وسلم على رَحْلٍ رَثٍّ، وقَطِيفة تُساوي أربعة دراهم، أو لا تُساوي، ثم قال: «اللهمَّ حَجَّة لا رِياءَ فيها، ولا سُمْعَة».","رواه ابن ماجه","صحيح"],["عن ابن عمر أن رسول الله صلى الله عليه وسلم أفاض يوم النحر، ثم رجع فصلى ‌الظهر ‌بمنى. قال نافع: فكان ابن عمر يفيض يوم النحر، ثم يرجع فيصلي ‌الظهر ‌بمنى، ويَذكرُ أن النبي صلى الله عليه وسلم فعله.","رواه مسلم","صحيح"],["عن عمرو بن ميمون يقول: شهدت عمر رضي الله عنه صلى بجَمْعٍ الصبح، ثم وقف فقال: إن المشركين كانوا لا يُفِيضون حتى تطلع الشمس، ويقولون: أشرق ‌ثبير، وأن النبي صلى الله عليه وسلم خالفهم ثم أفاض قبل أن تطلع الشمس.","رواه البخاري","صحيح"]]],["أركان الحج",[["عن ‌عروة ‌بن ‌مُضَرِّسِ الطائي قال: أتيتُ رسولَ الله صلى الله عليه وسلم بالموقِفِ، يعني بِجَمعٍ، قلتُ: جئتُ يا رسولَ الله مِن جبلِ طيِّئ، أكلَلتُ مَطيَّتي، وأتعبتُ نفسي، واللهِ ما تركتُ مِن حبْلٍ إلا وقفتُ عليه، فهل لي من حَجٍّ؟ فقال رسول الله صلى الله عليه وسلم: \"مَنْ أدرَكَ معنا هذه الصلاة، وأتى عَرَفَاتٍ قبلَ ذلك ليلًا أو نهارًا فقد تم حجُّه وقضى تفَثَه\".","رواه أبو داود والترمذي والنسائي وابن ماجه","صحيح"],["عن عائشة رضي الله عنها قالت: «حَجَجْنَا مع النبي صلى الله عليه وسلم فَأَفَضْنَا يوم النَّحْرِ، فحاضت صَفِيَّةُ، فأراد النبي صلى الله عليه وسلم منها ما يريد الرجل من أهله، فقلت: يا رسول الله، إنها حائض، قال: أَحَابِسَتُنَا هي؟ قالوا: يا رسول الله، إنها قد أفاضت يوم النَّحْرِ، قال: اخْرُجُوا». وفي لفظ: قال النبي صلى الله عليه وسلم : «عَقْرَى، حَلْقَى، أطافت يوم النَّحْرِ؟ قيل: نعم، قال: فَانْفِرِي».","متفق عليه","صحيح"]]],["واجبات الحج",[["عن عبد الله بن عُمر رضي الله عنهما عن رسول الله صلى الله عليه وسلم أنه قال: «اللَّهُمَّ ارحم الْمُحَلِّقِينَ. قالوا: والْمُقَصِّرِينَ يا رسول الله؟ قال: اللهم ارحم الْمُحَلِّقِينَ. قالوا: والْمُقَصِّرِينَ يا رسول الله؟ قال: اللهم ارحم الْمُحَلِّقِينَ. قالوا: والْمُقَصِّرِينَ يا رسول الله؟ قال: والْمُقَصِّرِينَ».","متفق عليه","صحيح"],["عن سالم قال: وكان عبد الله بن عمر رضي الله عنهما يقدم ‌ضَعَفَةَ ‌أهله، فيقفون عند المشعر الحرام بالمزدلفة بليل، فيذكرون الله ما بدا لهم، ثم يرجعون قبل أن يقف الإمام وقبل أن يدفع، فمنهم من يقدم منى لصلاة الفجر، ومنهم من يقدم بعد ذلك، فإذا قدموا رموا الجمرة وكان ابن عمر رضي الله عنهما يقول: أَرْخَصَ في أولئك رسولُ الله صلى الله عليه وسلم.","متفق عليه","صحيح"]]],["سنن الحج",[["عن عائشة قالت: كأني أنظر إلى وَبِيص الطيب، في مَفْرِق النبي صلى الله عليه وسلم، وهو محرم.","متفق عليه","صحيح"],["عن صفية بنت شيبة عن امرأة قالت: رأيتُ رسول الله صلى الله عليه وسلم، يسعى في بطن المسيل، ويقول: «لا يُقطَعُ الوادي ‌إلا ‌شَدًّا».","رواه النسائي","صحيح"],["عن عبد الله بن عمر رضي الله عنهما قال: صليتُ مع النبي صلى الله عليه وسلم بمنى ركعتين، وأبي بكر، وعمر ومع عثمان صدرًا من إمارته ثم أتمها.","متفق عليه","صحيح"],["عن عبد الله بن مسعود رضي الله عنه قال: ما رأيتُ النبي صلى الله عليه وسلم صلى صلاة بغير ‌ميقاتها، إلا صلاتين: جمع بين المغرب والعشاء، وصلى ‌الفجر قبل ‌ميقاتها.","متفق عليه","صحيح"],["عن محمد بن أبي بكر الثقفي قال: سألت أنس بن مالك ونحن غاديان من منى إلى عرفات عن التلبية، كيف كنتم تصنعون مع النبي صلى الله عليه وسلم؟ قال: كان ‌يلبي ‌الملبي، لا يُنكَر عليه، ويكبر المكبر، فلا يُنكَر عليه.","متفق عليه","صحيح"],["عن عبد الله بن عمرو بن العاص أن رسول الله صلى الله عليه وسلم وقف في حجة الوداع بمنى للناس يسألونه، فجاءه رجل فقال: لم أشعر فحلقتُ ‌قبل ‌أن ‌أذبح؟ فقال: «اذبح ولا حرج» فجاء آخر فقال: لم أشعر فنحرت قبل أن أرمي؟ قال: «ارم ولا حرج» فما سئل النبي صلى الله عليه وسلم عن شيء قُدِّم ولا أُخِّر إلا قال: «افعل ولا حرج».","متفق عليه","صحيح"],["عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم جاء إلى السقاية فاستسقى، فقال العباس: يا فضلُ، اذهب إلى أمك فأت رسول الله صلى الله عليه وسلم بشراب من عندها، فقال: «اسقني»، قال: يا رسول الله، إنهم يجعلون أيديهم فيه، قال: «اسقني»، فشرب منه، ثم أتى زمزم وهم يسقون ويعملون فيها، فقال: «اعملوا فإنكم على عمل صالح» ثم قال: «‌لولا ‌أن ‌تغلبوا لنزلت، حتى أضع الحبل على هذه» يعني: عاتقه، وأشار إلى عاتقه.","رواه البخاري","صحيح"],["عن عبد الله بن السائب قال: سمعت رسول الله صلى الله عليه وسلم يقول ما بين ‌الرُّكْنينِ: {رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً ‌وَقِنَا عَذَابَ النَّارِ} [البقرة: 201].","رواه أبو داود","حسن"]]],["أحكام الفوات والإحصار",[["عن عكرمة قال: سمعت الحجاج بن عمرو الأنصاري قال: قال رسول الله صلى الله عليه وسلم: \"‌مَنْ ‌كُسِرَ أو ‌عَرِجَ فقد حَلَّ، وعليه الحج من قابل\" قال عكرمة: فسألت ابن عباس وأبا هريرة عن ذلك فقالا: صدق.","رواه أبو داود والترمذي والنسائي وابن ماجه","صحيح"],["عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم خرج معتمرًا فحال كفار قريش بينه وبين البيت، فنحر هديه، وحلق رأسه بالحديبية، وقاضاهم على أن يعتمر العام المقبل، ولا يحمل سلاحًا عليهم إلا سيوفًا، ولا يقيم بها إلا ما أحبوا، فاعتمر من العام المقبل، فدخلها كما كان صالحهم، فلما أقام بها ثلاثًا أمروه أن يخرج فخرج.","رواه البخاري","صحيح"],["عن ‌عروة ‌بن ‌مُضَرِّسِ الطائي قال: أتيتُ رسولَ الله صلى الله عليه وسلم بالموقِفِ، يعني بِجَمعٍ، قلتُ: جئتُ يا رسولَ الله مِن جبلِ طيِّئ، أكلَلتُ مَطيَّتي، وأتعبتُ نفسي، واللهِ ما تركتُ مِن حبْلٍ إلا وقفتُ عليه، فهل لي من حَجٍّ؟ فقال رسول الله صلى الله عليه وسلم: \"مَنْ أدرَكَ معنا هذه الصلاة، وأتى عَرَفَاتٍ قبلَ ذلك ليلًا أو نهارًا فقد تم حجُّه وقضى تفَثَه\".","رواه أبو داود والترمذي والنسائي وابن ماجه","صحيح"],["عن نافع أن ابن عمر رضي الله عنهما أراد الحج عام نزل الحجاج بابن الزبير، فقيل له: إن الناس كائن بينهم قتال، وإنا ‌نخاف ‌أن ‌يصدوك. فقال: (لقد كان لكم في رسول الله إسوة حسنة)، إذن أصنع كما صنع رسول الله صلى الله عليه وسلم، إني أشهدكم أني قد أوجبت عمرةً، ثم خرج، حتى إذا كان بظاهر البيداء، قال: ما شأن الحج والعمرة إلا واحد، أشهدكم أني قد أوجبت حجًّا مع عمرتي، وأهدى هديًا اشتراه بقُدَيد، ولم يزد على ذلك، فلم ينحر، ولم يحلَّ من شيء حرُم منه، ولم يحلق ولم يقصِّر، حتى كان يوم النحر، فنحر وحلق، ورأى أن قد قضى طواف الحج والعمرة بطوافه الأول. وقال ابن عمر رضي الله عنهما: كذلك فعل رسول الله صلى الله عليه وسلم.","متفق عليه","صحيح"]]],["أحكام المسجد النبوي",[["عن نافع أن عبد الله بن عمر أخبره أن المسجد كان على عهد رسول الله صلى الله عليه وسلم مبنيًّا باللَّبِنِ، وسقفُه الجريدُ، وعُمُدُه خشبُ النخل، فلم يزد فيه أبو بكر شيئًا، وزاد فيه عمر، وبناه على بنيانه في عهد رسول الله صلى الله عليه وسلم باللبن والجريد وأعاد عمده خشبًا، ثم غيَّره عثمان فزاد فيه زيادة كثيرة، وبنى جداره بالحجارة المنقوشة، والقَصَّة، وجعل عمده من حجارة منقوشة وسَقَفَه بالسَّاج.","رواه البخاري","صحيح"]]],["الهدي والكفارات",[["عن عائشة رضي الله عنها قالت: «أَهدَى رسول الله صلى الله عليه وسلم مَرَّةً غَنَمًا».","متفق عليه","صحيح"],["عن أبي الزبير قال: سألتُ جابرًا عن ركوب الهدي، فقال: سمعت النبي صلى الله عليه وسلم يقول: «اركبها بالمعروف، حتى تجد ظهرًا».","رواه مسلم","صحيح"],["عن جابر بن عبد الله، قال: «نَحَرْنَا مع رسول الله صلى الله عليه وسلم عَامَ الحُدَيْبِيَة البَدَنَةَ عن سَبْعَة، والبَقَرَةَ عن سَبْعَة»","رواه مسلم","صحيح"],["عائشة رضي الله عنها قالت: «فَتَلْتُ قَلَائِدَ هَدْيِ رسولِ الله صلى الله عليه وسلم ، ثم أَشْعَرْتُها وَقَلَّدَهَا -أو قَلَّدْتُها-، ثم بعث بها إلى البيت، وأقام بالمدينة، فما حَرُمَ عليه شيءٌ كان له حِلًّا».","متفق عليه","صحيح"],["عن ابن عباس رضي الله عنهما قال: صلى رسول الله صلى الله عليه وسلم الظهر بذي الحليفة، ثم دعا بناقته فأشعرها في صفحة سنامها الأيمن، وسَلَت الدم، وقلَّدها نعلين، ثم ركب راحلته، فلما استوت به على البيداء أهل بالحج.","رواه مسلم","صحيح"],["عن ابن عباس أن ذؤيبًا أبا قبيصة حدثه أن رسول الله صلى الله عليه وسلم كان يبعث معه بالبدن ثم يقول: «إن عَطِبَ منها شيء فخشيت عليه موتًا فانحرها، ثم اغمس نعلها في دمها، ثم اضرب به صفحتها، ولا تطعمها أنت ولا أحد من أهل رفقتك».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه «أن نبي الله صلى الله عليه وسلم رأى رجلا يَسُوقُ بَدَنَةً، فقال: اركبها، قال: إنها بَدَنَةٌ، قال اركبها، فرأيته رَاكِبَهَا، يُسَايِرُ النبي صلى الله عليه وسلم ». وفي لفظ: قال في الثانية، أو الثالثة: «اركبها وَيْلَكَ أو وَيْحَكَ».","متفق عليه","صحيح"],["عن جابر بن عبد الله رضي الله عنهما قال: «أَهَلَّ النبيُّ صلى الله عليه وسلم وأصحابُه بالحج، وليس مع أحد منهم هَدْيٌ غير النبي صلى الله عليه وسلم وطلحة، وقدم علي رضي الله عنه من اليمن. فقال: أَهْلَلْتُ بما أَهَلَّ به النبي صلى الله عليه وسلم فأمر النبي صلى الله عليه وسلم أصحابه: أن يجعلوها عمرة، فيطوفوا ثم يُقَصِّرُوا ويَحِلُّوا، إلا من كان معه الهَدْي، فقالوا: ننطلق إلى مِنًى وَذَكَرُ أَحَدِنَا يَقْطُرُ؟ فبلغ ذلك النبي - صلى الله عليه وسلم- فقال: لَوِ اسْتَقْبَلْتُ من أَمْرِي مَا اسْتَدْبَرْتُ ؛ ما أَهْدَيْتُ ، ولولا أن معي الهَدْيَ لَأَحْلَلْتُ. وحاضت عائشة. فَنَسَكَتْ المنَاسِك كلها، غير أنها لم تَطُفْ بالبيت. فلما طَهُرت وطافت بالبيت قالت: يا رسول الله، تَنْطَلِقُونَ بحج وعمرة، وأنطلق بحج؟ فأمر عبد الرحمن بن أبي بكر: أن يخرج معها إلى التَّنْعِيمِ ، فاعتمرت بعد الحج».","متفق عليه","صحيح"]]],["الأضحية",[["عن جُنْدُب بن عَبْدِ الله البجَليِّ رضي الله عنه قال: «صلى النبي صلى الله عليه وسلم يوم النَّحر، ثم خطب، ثم ذبح، وقال: من ذبح قبل أن يُصَلِّيَ فَلْيَذْبَحْ أُخرى مكانها، ومن لم يذبح فَلْيَذْبَحْ باسم الله».","متفق عليه","صحيح"],["عن البَرَاء بن عَازب رضي الله عنهما قال: «خطبنا النبي صلى الله عليه وسلم يوم الأضحى بعد الصلاة، فقال: من صلى صلاتنا وَنَسَكَ نُسُكَنَا فقد أصاب النُّسُكَ، ومن نسك قبل الصلاة فلا نُسُك له. فقال أبو بُرْدَةَ بن نِيَار -خال البَرَاء بن عَازبٍ-: يا رسول الله، إني نسكت شاتي قبل الصلاة، وعرفت أن اليوم يوم أكل وشرب، وأحببت أن تكون شاتي أول ما يذبح في بيتي، فذبحت شاتي، وتغديت قبل أن آتي الصلاة. فقال: شاتك شاة لحم. قال: يا رسول الله، فإن عندنا عَنَاقًا لنا هي أحب إلي من شاتين؛ أَفَتَجْزِي عني؟ قال: نعم، ولن تَجْزِيَ عن أحد بعدك».","متفق عليه","صحيح"],["عن أبي هريرة، أن رسول الله صلى الله عليه وسلم قال: «مَن كان له سَعَة، ولمْ يُضَحِّ، فلا يَقْرَبَنّ مُصَلّانا».","رواه ابن ماجه وأحمد","حسن"]]],["أخطاء وبدع في الحج",[["عن ابن عباس رضي الله عنهما أن النبي صلى الله عليه وسلم مَرَّ وهو يطوف بالكعبة بإنسان ربط يده إلى إنسان بِسَيرٍ أو بخيطٍ أو بشيء غير ذلك، فقطعه النبي صلى الله عليه وسلم بيده، ثم قال: «‌قُدْهُ ‌بيده».","رواه البخاري","صحيح"]]],["أحكام ومسائل الحج والعمرة",[["عن ابن عباس رضي الله عنهما قال: احتجم رسول الله صلى الله عليه وسلم وهو محرم.","متفق عليه","صحيح"],["عن أنس بن مالك رضي الله عنه : أنَّ رسول الله صلى الله عليه وسلم حَجَّ على رَحْلٍ وكانتْ زَامِلَتَهُ.","رواه البخاري","صحيح"],["عن ابن عباس قال: قال رسول الله صلى الله عليه وسلم: \"ليس على النساء الحلق، إنما على ‌النساء ‌التقصير\".","رواه أبو داود","صحيح"],["عن العلاء بن الحضرمي عن رسول الله صلى الله عليه وسلم أنه قال: «مُكْثُ المهاجر بمكة بعد قضاء نسكه ثلاث».","متفق عليه","صحيح"],["عن السَّائب بن يزيد رضي الله عنهما قال: «حُجَّ بي مع رسول الله صلى الله عليه وسلم في حجة الوداع، وأنا ابن سبع سنين».","رواه البخاري","صحيح"],["عن عبد الله بن عباس رضي الله عنهما قال: «طَافَ النبيُّ -صلَّى الله عليه وسلَّم- فِي حَجَّةِ الوَدَاعِ على بَعِير، يَستَلِم الرُّكنَ بِمِحجَن».","متفق عليه","صحيح"],["عن أبي هريرة ذكر النبي صلى الله عليه وسلم فيه قال: \"وفطركم يوم تفطرون، وأضحاكم يوم تضحون، وكل عرفة موقف، وكل منى منحر، وكل فجاج مكة منحر، وكل جمع موقف\".","رواه أبو داود والترمذي وابن ماجه","صحيح"],["عن ابن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: «هذه عمرةٌ استَمْتَعنا بها، فمن لم يكن عنده الهدي فليحل الحل كله، فإن ‌العمرة قد ‌دخلت في الحج إلى يوم القيامة».","رواه مسلم","صحيح"],["عن أم سلمة قالت: شكوت إلى رسول الله صلى الله عليه وسلم أني أشتكي قال: «‌طُوْفِي من وراء الناس وأنت راكبة» فطفت ورسول الله صلى الله عليه وسلم يصلي إلى جنب البيت يقرأ بالطور وكتاب مسطور.","متفق عليه","صحيح"]]]]],["الجنائز",0,[["الموت وأحكامه",[["عن بريدة عن النبي صلى الله عليه وسلم أنه قال: «المؤمن يموت بعرق الجبين».","رواه الترمذي والنسائي وابن ماجه","صحيح"],["عن علي قال: رأينا رسول الله صلى الله عليه وسلم قام فقمنا وقعد فقعدنا. يعني في الجنازة.","رواه مسلم","صحيح"],["عن جابر بن سمرة قال: أُتِيَ النبي صلى الله عليه وسلم برجلٍ قَتَلَ نفسَه بمَشَاقِصَ، فلم يصلِّ عليه.","رواه مسلم","صحيح"],["عن معاذِ بن جبل قال: قال رسول الله صلى الله عليه وسلم: \"من كان آخرُ كلامهِ لا إله إلا اللهُ دخل الجنة\".","رواه أبو داود","صحيح"],["عن عُبيد بن خالد السلمي -رجل من أصحاب النبي صلى الله عليه وسلم- رفعه مرة ووقفه مرة: \"موت الفَجْأة أَخْذَةُ أَسَفٍ\".","رواه أبو داود","صحيح"],["عن عائشة رضي الله عنها زوج النبي صلى الله عليه وسلم أخبرته: «أن رسول الله صلى الله عليه وسلم حين توفي سجي ببُرْدٍ حِبَرَة».","متفق عليه","صحيح"],["عن عائشة عن النبي صلى الله عليه وسلم قال: «ما من ميت تصلي عليه أُمَّةٌ من المسلمين يبلغون مائة، كلهم يشفعون له، إلا شفعوا فيه».","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها قالت: قال النبي صلى الله عليه وسلم: «لَا تَسُبُّوا الْأَمْوَاتَ، فَإِنَّهُمْ قَدْ أَفْضَوْا إِلَى مَا قَدَّمُوا».","رواه البخاري","صحيح"],["عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم: «ألم تَرَوا الإنسانَ إذا مات شخصَ بصرُه؟» قالوا: بلى، قال: «فذلك حين يَتبع بصرُه نفْسَه».","رواه مسلم","صحيح"]]],["غسل الميت",[["عن عائشة رضي الله عنها قالت: دخلت على أبي بكر رضي الله عنه، فقال: في كم كفنتم النبي صلى الله عليه وسلم؟ قالت: في ثلاثة أثواب بيض سحولية، ليس فيها قميص ولا عمامة. وقال لها: في أي يوم توفي رسول الله صلى الله عليه وسلم؟ قالت: يوم الاثنين. قال: فأي يوم هذا؟ قالت: يوم الاثنين. قال: أرجو فيما بيني وبين الليل، فنظر إلى ثوب عليه، كان يمرض فيه به رَدْعٌ من زعفران، فقال: اغسلوا ثوبي هذا وزيدوا عليه ثوبين، فكفنوني فيها، قلت: إن هذا خلق، قال: إن الحي أحق بالجديد من الميت، إنما هو للمُهْلَة فلم يُتَوفَّ حتى أمسى من ليلة الثلاثاء، ودفن قبل أن يصبح.","رواه البخاري","صحيح"]]],["تكفين الميت",[["عن جابر بن عبد الله أن النبي صلى الله عليه وسلم خطب يومًا، فذكر رجلًا من أصحابه قُبِض فكفِّن في كفنٍ غيرِ طائل، وقُبِر ليلًا، فزجر النبي صلى الله عليه وسلم أن يقبر الرجل بالليل حتى يصلى عليه، إلا أن يضطر إنسان إلى ذلك، وقال النبي صلى الله عليه وسلم: «إذا كَفَّنَ أحدُكم أخاه فليُحسِّنْ كَفَنَه».","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها قالت: دخلت على أبي بكر رضي الله عنه، فقال: في كم كفنتم النبي صلى الله عليه وسلم؟ قالت: في ثلاثة أثواب بيض سحولية، ليس فيها قميص ولا عمامة. وقال لها: في أي يوم توفي رسول الله صلى الله عليه وسلم؟ قالت: يوم الاثنين. قال: فأي يوم هذا؟ قالت: يوم الاثنين. قال: أرجو فيما بيني وبين الليل، فنظر إلى ثوب عليه، كان يمرض فيه به رَدْعٌ من زعفران، فقال: اغسلوا ثوبي هذا وزيدوا عليه ثوبين، فكفنوني فيها، قلت: إن هذا خلق، قال: إن الحي أحق بالجديد من الميت، إنما هو للمُهْلَة فلم يُتَوفَّ حتى أمسى من ليلة الثلاثاء، ودفن قبل أن يصبح.","رواه البخاري","صحيح"]]],["صفة الصلاة على الميت",[["عن جابر بن عبد الله رضي الله عنهما «أن النبي صلى الله عليه وسلم صَلَّى على النَّجَاشِيِّ، فكنت في الصفّ الثاني، أو الثالث».","متفق عليه","صحيح"],["عن سَمُرَةَ بْنِ جُنْدُبٍ رضي الله عنه قال: «صَلَّيْت وراء النبي صلى الله عليه وسلم على امرأة ماتت في نِفَاسِهَا فقام في وَسْطِهَا».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: «نَعَى النبيُّ صلى الله عليه وسلم النَّجَاشِيَّ في اليوم الذي مات فيه، خرج بهم إلى المصلَّى، فصفَّ بهم، وكَبَّرَ أَرْبَعاً».","متفق عليه","صحيح"],["عن عبد الرحمن بن أبي ليلى، قال: كان زيد -أي ابن أرقم- يكبر على جنائزنا أربعا، وإنه كبر على جنازة خمسًا، فسألته فقال: كان رسول الله صلى الله عليه وسلم يكبرها.","رواه مسلم","صحيح"],["عن المغيرة بن شعبة عن النبي صلى الله عليه وسلم قال: \"الراكب يسير خلف الجنازة، والماشي يمشي خلفها وأمامها، وعن يمينها وعن يسارها، قريبًا منها، والسقط يصلى عليه ويدعى لوالديه بالمغفرة والرحمة\".","رواه أبو داود والنسائي وابن ماجه","صحيح"],["عن عائشة أنها أمرت أن يُمَرَّ بجنازة سعد بن أبي وقاص في المسجد، فتصلي عليه، فأنكر الناس ذلك عليها، فقالت: ما أسرع ما نسي الناس، ما صلى رسول الله صلى الله عليه وسلم على سُهَيل ابن البيضاء إلا في المسجد.","رواه مسلم","صحيح"],["عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم مَرَّ بقبرٍ قد دفن ليلًا، فقال: «متى دُفن هذا؟» قالوا: البارحة، قال: «أفلا آذنتموني؟» قالوا: دفناه في ظلمة الليل فكرهنا أن نوقظك، فقام، فصففنا خلفه، قال ابن عباس: وأنا فيهم فصلى عليه.","رواه البخاري","صحيح"],["عن واثلة بن الأسقع رضي الله عنه مرفوعاً: « صلى بنا رسول الله صلى الله عليه وسلم على رجل من المسلمين، فسمعته يقول: «اللهم إن فلان ابن فلان في ذمتك وحبل جِوَارِكَ، فَقِهِ فِتْنَةَ القبر، وعذاب النار، وأنت أهل الوفاء والحمد؛ اللهم فاغفر له وارحمه، إنك أنت الغفور الرحيم».","رواه أبو داود وابن ماجه وأحمد","صحيح"],["عن أبي غالب قال: رأيت أنس بن مالك صلى على جنازةِ رجلٍ، فقام حِيالَ رأسِه، فجيء بجنازة أخرى، فقالوا: يا أبا حمزة صلِّ عليها، فقام حيال وسْطِ السرير، فقال العلاء بن زياد: يا أبا حمزة، هكذا رأيت رسول الله صلى الله عليه وسلم قام من الجنازة مقامك من الرجل، وقام من المرأة مقامك من المرأة؟ قال: نعم. فأقبل علينا، فقال: احفظوا.","رواه أبو داود والترمذي وابن ماجه","صحيح"],["عن عوف بن مالك قال: صلى رسول الله صلى الله عليه وسلم على جنازة، فحفظت من دعائه وهو يقول: «اللهم اغفر له وارحمه، وعافه واعف عنه، وأكرم نزله، ووسع مدخله، واغسله بالماء والثلج والبرد، ونقِّه من الخطايا كما نقيت الثوب الأبيض من الدنس، وأبدله دارًا خيرًا من داره، وأهلًا خيرًا من أهله وزوجًا خيرًا من زوجه، وأدخله الجنة وأعِذْه من عذاب القبر -أو من عذاب النار-» قال: حتى تمنيت أن أكون أنا ذلك الميت.","رواه مسلم","صحيح"]]],["حمل الميت ودفنه",[["عن سفيان التَّمَّار أنه رأى قبر النبي صلى الله عليه وسلم مُسَنَّمًا.","رواه البخاري","صحيح"],["عن عائشة أن رسول الله صلى الله عليه وسلم قال: \"كسر عظم الميت ككسره حيًّا\".","رواه أبو داود وابن ماجه","صحيح"],["عن ابن عمر أن النبي صلى الله عليه وسلم كان إذا وَضَعَ الميت في القبر قال: \"بسم الله، وعلى سنة رسول الله\".","رواه أبو داود والترمذي والنسائي في الكبرى وابن ماجه","صحيح"],["عن سعد بن أبي وقاص أنه قال في مرضه الذي هلك فيه: الْحَدُوا لي لحدًا، وانصِبوا عليَّ اللَّبِن نصبًا، كما صنع برسول الله صلى الله عليه وسلم.","رواه مسلم","صحيح"],["عن عامر بن ربيعة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إذا رأى أحدكم جنازةً فإلم يكن ماشيًا معها فليقم حتى يُخلِّفها أو تُخلِّفَه أو توضع من قبل أن تخلفه».","متفق عليه","صحيح"],["عن ثوبان أن رسول الله صلى الله عليه وسلم أُتِيَ بدابة وهو مع الجنازة، فأبى أن يركبها، فلما انصرف أتي بدابة فركب، فقيل له، فقال: \"إن الملائكة كانت تمشي، فلم أكن لأركب وهم يمشون، فلما ذهبوا ركبت\".","رواه أبو داود","صحيح"],["عن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: «مَنْ شهدَ الْجَنَازَةَ حتى يصلَّى عليها فله قِيرَاطٌ، ومن شهدها حتى تُدفن فله قِيرَاطان، قيل: وما القِيرَاطَانِ؟ قال: مثل الجبلين العظيمين». ولمسلم: «أصغرهما مثل أُحُدٍ».","متفق عليه","صحيح"],["عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم مَرَّ بقبرٍ قد دفن ليلًا، فقال: «متى دُفن هذا؟» قالوا: البارحة، قال: «أفلا آذنتموني؟» قالوا: دفناه في ظلمة الليل فكرهنا أن نوقظك، فقام، فصففنا خلفه، قال ابن عباس: وأنا فيهم فصلى عليه.","رواه البخاري","صحيح"],["عن جابر بن عبد الله رضي الله عنهما قال: كان النبي صلى الله عليه وسلم يجمع بين الرجلين من قتلى أحد في ثوب واحد، ثم يقول: «أيُّهم أكثرُ أخذًا للقرآن»، فإذا أشير له إلى أحدهما قدمه في اللحد، وقال: «أنا شهيد على هؤلاء يوم القيامة»، وأمر بدفنهم في دمائهم، ولم يغسلوا، ولم يُصَلِّ عليهم.","رواه البخاري","صحيح"],["عن جابر بن عبد الله أن النبي صلى الله عليه وسلم خطب يومًا، فذكر رجلًا من أصحابه قُبِض فكفِّن في كفنٍ غيرِ طائل، وقُبِر ليلًا، فزجر النبي صلى الله عليه وسلم أن يقبر الرجل بالليل حتى يصلى عليه، إلا أن يضطر إنسان إلى ذلك، وقال النبي صلى الله عليه وسلم: «إذا كَفَّنَ أحدُكم أخاه فليُحسِّنْ كَفَنَه».","رواه مسلم","صحيح"]]],["التعزية",[["عن أسيد بن أبي أسيد التابعي، عن امرأة من المبايعات، قالت: كان فيما أخذ علينا رسولُ الله صلى الله عليه وسلم في المعروف الذي أخذ علينا أن لا نعصيه فيه: أن لا نَخْمِشَ وجهًا، ولا نَدْعُوَ وَيْلًا، ولا نَشُقَّ جَيْبًا، وأن لا نَنْشُرَ شَعْرًا.","رواه أبو داود","صحيح"],["عن أنس رضي الله عنه : أن رسول الله صلى الله عليه وسلم دخل على ابنه إبراهيم رضي الله عنه وهو يجود بنفسه، فجعلت عينا رسول الله صلى الله عليه وسلم تذرفان. فقال له عبد الرحمن بن عوف: وأنت يا رسول الله؟! فقال: «يا ابن عوف إنها رحمة» ثم أتبعها بأخرى، فقال: «إن العين تدمع والقلب يحزن، ولا نقول إلا ما يرضي ربنا، وإنا لفراقك يا إبراهيم لمحزونون».","رواه البخاري وروى مسلم بعضه","صحيح"],["عن أنس رضي الله عنه قال: كان ابن لأبي طلحة رضي الله عنه يشتكي، فخرج أبو طلحة، فَقُبِضَ الصَّبي، فلما رجع أبو طلحة، قال: ما فعل ابني؟ قالت أم سليم وهي أم الصَّبي: هو أسْكَن ما كان، فَقَرَّبَت إليه العشاء فتَعَشَّى، ثم أصاب منها، فلما فَرَغ،َ قالت: وارُوا الصَّبي فلما أصبح أبو طلحة أتى رسول الله صلى الله عليه وسلم فأخبره، فقال:«أعَرَّسْتُمُ اللَّيلَةَ؟» قال: نعم، قال: «اللَّهُمَّ بارِك لهما»، فولدت غلامًا، فقال لي أبو طلحة: احْمِلْهُ حتى تأتي به النبي صلى الله عليه وسلم وبعث معه بتمرات، فقال: «أمَعَه شيء؟» قال: نعم، تَمَرات، فأخذها النبي صلى الله عليه وسلم فمَضَغَها، ثم أخذها من فِيه فجعلها في فِيِّ الصَّبي، ثم حَنَّكَهُ وسماه عبد الله. وفي رواية: قال ابن عيينة: فقال رجل من الأنصار: فرأيت تِسْعَة أولاد كلهم قد قرؤوا القرآن، يعني: من أولاد عبد الله المولود. وفي رواية: مات ابن لأبي طلحة من أم سليم، فقالت لأهلها: لا تُحَدِّثوا أبا طلحة بابْنِهِ حتى أكون أنا أُحدِّثه، فجاء فَقَرَّبَتْ إليه عشاء فأكَل وشرب، ثم تَصَنَّعَتْ له أحْسَن ما كانت تصنع قبل ذلك، فَوَقَع بها. فلمَّا أن رأت أنه قد شَبِع وأصاب منها، قالت: يا أبا طلحة، أرأيت لو أن قومًا أعَارُوا عَارِيَتَهُم أهل بيت فطَلَبوا عَارِيَتَهُم، ألهم أن يَمْنَعُوهُم؟ قال: لا، فقالت: فَاحْتَسِبْ ابنك، قال: فغضِب، ثم قال: تَرَكْتِني حتى إذا تَلطَّخْتُ، ثم أخبرتني بابني؟! فانطلق حتى أتى رسول الله -صلى الله عليه وسلم- فأخبره بما كان فقال رسول الله صلى الله عليه وسلم : «بارك الله في لَيْلَتِكُمَا»، قال: فَحَمَلَتْ. قال: وكان رسول الله صلى الله عليه وسلم في سَفَر وهي معه، وكان رسول الله صلى الله عليه وسلم إذا أتى المدينة من سَفر لا يَطْرُقُهَا طُرُوقًا فَدَنَوا من المدينة، فضَرَبَها المَخَاض، فَاحْتَبَسَ عليها أبو طلحة، وانطلق رسول الله صلى الله عليه وسلم قال: يقول أبو طلحة: إنك لَتَعْلَمُ يَا رَبِّ أنه يُعْجِبُنِي أن أخرج مع رسول الله صلى الله عليه وسلم إذا خرج وأدخل معه إذا دخل وقد احْتَبَسْتُ بما ترى، تقول أم سليم: يا أبا طلحة، ما أجِدُ الذي كنت أجِدُ، انطلق، فانطلقنا وضربها المَخَاض حين قَدِما، فولدت غلامًا. فقالت لي أمي: يا أنس، لا يُرْضِعْهُ أحدٌ حتى تَغْدُو به على رسول الله صلى الله عليه وسلم فلمَّا أصبح احتَمَلْتُه فانْطَلَقتُ به إلى رسول الله صلى الله عليه وسلم ... وذكر تمام الحديث.","متفق عليه","صحيح"]]],["زيارة القبور",[["عن جابر قال: نهى رسول الله صلى الله عليه وسلم أن يُجَصَّص القبر، وأن يُقعَد عليه، وأن يُبنَى عليه.","رواه مسلم","صحيح"],["عن أبي هريرة قال: زار النبي صلى الله عليه وسلم قبر أمه، فبكى وأبكى من حوله، فقال: «استأذنتُ ربي في أن أستغفر لها فلم يؤذن لي، واستأذنته في أن أزور قبرها فأذن لي، فزوروا القبور فإنها تذكر الموت».","رواه مسلم","صحيح"],["عن بَشير بن نَهيك عن بَشير مولى رسول الله صلى الله عليه وسلم وكان اسمه في الجاهلية زَحْمَ بنَ مَعْبد، فهاجر إلى رسول الله صلى الله عليه وسلم، فقال: \"ما اسمك؟ \" قال: زَحْم، قال: \"بل أنت بشير\"، قال: بينما أنا أماشي رسول الله صلى الله عليه وسلم مَرَّ بقبور المشركين، فقال: \"لقد سبق هؤلاء خيرًا كثيرًا\" ثلاثًا، ثم مر بقبور المسلمين، فقال: \"لقد أدرك هؤلاء خيرًا كثيرًا\" وحانت من رسول الله صلى الله عليه وسلم نظرةً، فإذا رجلٌ يمشي في القبور عليه نعلان، فقال: \"يا صاحب السِّبْتِيَّتَين، ويحك، ألق سِبْتَيَّتَيكَ\" فنظر الرجل، فلما عرف رسول الله صلى الله عليه وسلم خلعهما فرمى بهما.","رواه أبو داود والنسائي وابن ماجه","صحيح"],["عن عائشة رضي الله عنها قالت: ألا أُحَدِّثكم عنِّي وعن رسول الله صلى الله عليه وسلم قلنا: بلى، قال: قالت: لمَّا كانت ليلتي التي كان النبيُّ صلى الله عليه وسلم فيها عندي، انقلب فوضعَ رداءه، وخلع نعلَيْه، فوضعهما عند رجليه، وبسط طرفَ إزاره على فراشه، فاضطجع، فلم يلبث إلا رَيْثما ظنَّ أن قد رقدتُ، فأخذ رداءه رُوَيْدًا، وانتعل رُوَيْدًا، وفتح الباب فخرج، ثم أجافه رُوَيْدًا، فجعلتُ دِرْعي في رأسي، واختمرتُ، وتَقنَّعتُ إزاري، ثم انطلقتُ على إثره، حتى جاء البَقِيعَ فقام، فأطال القيام، ثم رفع يديه ثلاث مرات، ثم انحرف فانحرفتُ، فأسرع فأسرعت، فهَرْول فهرولتُ، فأحضر فأحضرت، فسبقتُه فدخلت، فليس إلا أن اضطجعتُ فدخل، فقال: «ما لك؟ يا عائشُ، حَشْيا رابِية» قالت: قلت: لا شيء، قال: «تُخْبِرِينِي أَو لَيُخْبِرَنِّي اللطيفُ الخبير» قالت: قلت: يا رسول الله، بأبي أنت وأمي، فأخبرته، قال: «فأنتِ السواد الذي رأيتُ أمامي؟» قلت: نعم، فلَهَدَني في صدري لَهْدةً أوجعتني، ثم قال: «أظننتِ أنْ يَحِيفَ اللهُ عليك ورسولُه؟» قالت: مَهْما يكتمِ الناسُ يعلمه الله، قال: «نعم، فإن جبريلَ أتاني حين رأيتِ، فناداني، فأخفاه منك، فأجبتُه، فأخفيته منك، ولم يكن يدخل عليك وقد وضعتِ ثيابك، وظننت أن قد رقدت، فكرهتُ أن أوقظَك، وخشيتُ أن تستوحشي، فقال: إنَّ ربَّك يأمركَ أن تأتيَ أهلَ البَقِيع فتستغفر لهم»، قالت: قلت: كيف أقول لهم يا رسول الله؟ قال «قولي: السلامُ على أهل الدِّيار من المؤمنين والمسلمين، ويرحمُ اللهُ المستقدمين منا والمستأخرين، وإنَّا إن شاء الله بكم للاحِقون».","رواه مسلم","صحيح"]]],["الأعمال الصالحة عن الميت وإهداء الثواب له",[["عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم قَالَ: «إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةٍ: إِلَّا مِنْ صَدَقَةٍ جَارِيَةٍ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ».","رواه مسلم","صحيح"],["عن أم العلاء قالت: طار لنا عثمان بن مظعون في السكنى، حين اقترعت الأنصار على سكنى المهاجرين، فاشتكى فمرَّضْناه حتى توفي، ثم جعلناه في أثوابه، فدخل علينا رسول الله صلى الله عليه وسلم، فقلت: رحمة الله عليك أبا السائب، فشهادتي عليك لقد أكرمك الله، قال: «وما يدريك» قلت: لا أدري والله، قال: «أما هو فقد جاءه اليقين، إني لأرجو له الخير من الله، والله ما أدري -وأنا رسول الله- ما يفعل بي ولا بكم» قالت أم العلاء: فوالله لا أزكي أحدا بعده، قالت: ورأيت لعثمان في النوم عينا تجري، فجئت رسول الله صلى الله عليه وسلم فذكرت ذلك له، فقال: «ذاك عمله يجري له».","رواه البخاري","صحيح"]]]]],["الأسرة: الزواج والطلاق",1,[["النكاح",[["عن أبي موسى رضي الله عنه أن النبي صلى الله عليه وسلم قال: «لا نِكَاحَ إِلّا بِوَليٍّ».","رواه أبو داود والترمذي وابن ماجه وأحمد","صحيح"],["عن عبد الله بن عمر رضي الله عنهما : «أن رسول الله صلى الله عليه وسلم نهى عن الشِّغَارِ».","متفق عليه","صحيح"],["عن علي رضي الله عنه أن النبي صلى الله عليه وسلم قال: «لَعَنَ اللهُ المُحَلِّل، والمُحَلَّلَ له».","رواه أبو داود والترمذي وابن ماجه وأحمد","صحيح"],["عن كعب بن مالك رضي الله عنه قال: رأيتُ رسولَ اللهِ صلى الله عليه وسلم يأكلُ بثلاثِ أَصَابِعَ، فإذا فَرَغَ لَعِقَهَا.","رواه مسلم","صحيح"],["عن سعد بن أبي وقاص رضي الله عنه قال: رد رسول الله صلى الله عليه وسلم على عثمان بن مظعون التَّبَتُّلَ، ولو أذن له لاختَصَيْنَا.","متفق عليه","صحيح"],["عن أبي علي طلق بن علي رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إذا دعا الرجل زوجته لحاجته فَلْتَأتِهِ وإن كانت على التَّنُور».","رواه الترمذي","صحيح"],["عن ابن عباس رضي الله عنهما أن النبي صلى الله عليه وسلم قال: «الثَّيِّب أحقُّ بنفسها مِن وَلِيِّها، والبِكر تُسْتَأمَر، وإذْنُها سُكُوتها».","رواه مسلم","صحيح"],["قال رسول الله صلى الله عليه وسلم في بنت حمزة: «لَا تَحِلُّ لِي يَحْرُمُ من الرَّضَاعِ مَا يَحْرُمُ من النَّسَبِ وهي ابنة أَخِي من الرَّضاعة».","متفق عليه","صحيح"],["عن ابن عباس، أن جَاريةً بِكْراً أتَتِ النبي صلى الله عليه وسلم فذكرت «أنَّ أباها زَوَّجَها وهي كارهة، فَخَيَّرَهَا النبي صلى الله عليه وسلم ».","رواه أبو داود وابن ماجه وأحمد","صحيح"]]],["الطلاق",[["عن عمرو بن شعيب، عن أبيه، عن جده قال: قال رسول الله صلى الله عليه وسلم : «لا نَذْرَ لابن آدم فيما لا يملك، ولا عِتْقَ له فيما لا يملك، ولا طلاق له فيما لا يمْلِك».","رواه أبو داود والترمذي وابن ماجه وأحمد","صحيح"],["عن ابن عباس، قال: \"كان الطلاق على عهد رسول الله صلى الله عليه وسلم ، وأبي بكر، وسنتين من خلافة عمر، طلاق الثلاث واحدة، فقال عمر بن الخطاب: إن الناس قد استعجلوا في أمر قد كانت لهم فيه أَنَاةٌ، فلو أَمْضَيْنَاهُ عليهم، فَأَمْضَاهُ عليهم\".","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها ، قالت: طلَّق رجل امرأَته ثلاثا، فَتَزوَّجها رجل، ثم طلَّقها قَبْل أن يَدْخُل بها، فَأَراد زوجها الأول أن يتزوَّجها، فسُئِل رسول الله صلى الله عليه وسلم عن ذلك، فقال: «لا، حتى يَذُوَق الآخرُ مِنْ عُسَيْلَتِها ما ذَاقَ الأوَّل».","متفق عليه","صحيح"],["عن الزُّبير بن العوام رضي الله عنه أنَّه كانت عنده أمُّ كُلثوم بنتُ عقبة، فقالت له وهي حاملٌ: طَيِّب نفسي بتطليقة، فطلَّقها تطليقةً، ثم خرجَ إلى الصلاة، فرجع وقد وضعت، فقال: ما لها؟ خَدَعتني، خَدَعها اللهُ، ثم أتى النبيَّ صلى الله عليه وسلم ، فقال: «سَبَقَ الكتابُ أَجَلَه، اخطِبها إلى نفسِها».","رواه ابن ماجه","صحيح"],["عن عبد الله بن عمر رضي الله عنهما : أنه طَلَّق امرأته وهي حائض، على عَهْد رسول الله صلى الله عليه وسلم ، فسأل عمر بن الخطاب رسول الله صلى الله عليه وسلم عن ذلك، فقال رسول الله صلى الله عليه وسلم: «مُرْهُ فليُرَاجِعْهَا، ثم ليُمْسِكْهَا حتى تَطْهُر، ثم تحيض ثم تَطْهُر، ثم إن شاء أَمسَكَ بَعْدُ، وإن شاء طلق قَبْل أن يَمَسَّ، فتلك العِدَّةُ التي أمر الله أن تُطَلَّقَ لها النساء».","متفق عليه","صحيح"]]],["الرجعة",[["عن الحسن {فلا تعضلوهن} [البقرة: 232] قال: حدثني معقل بن يسار، أنها نزلت فيه، قال: زوَّجتُ أختًا لي من رجل فطلقها، حتى إذا انقضت عدتها جاء يخطبها، فقلت له: زوجتك وفرشتك وأكرمتك، فطلقتها، ثم جئت تخطبها، لا والله لا تعود إليك أبدا، وكان رجلًا لا بأس به، وكانت المرأة تريد أن ترجع إليه، فأنزل الله هذه الآية: {فلا تعضلوهن} [البقرة: 232] فقلت: الآن أفعل يا رسول الله، قال: فزوجها إياه.","رواه البخاري","صحيح"],["عن أبي هريرة أن رسول الله صلى الله عليه وسلم قال: \"ثلاث جِدُّهُنَّ جِدٌّ، وهَزْلُهُنَّ جِدٌّ: النكاح، والطلاق، والرَّجْعَةُ\".","رواه أبو داود والترمذي وابن ماجه","حسن"]]],["الخلع",[["عن ابن عباس رضي الله عنهما «أن امرأة ثابت بن قيس اخْتَلَعَت من زوجها على عهد النبي صلى الله عليه وسلم فأمرها النبي صلى الله عليه وسلم أن تَعْتَدَّ بحَيْضَة».","رواه أبو داود والترمذي","صحيح"],["عن ابن عباس أن امرأة ثابت بن قيس أتت النبي صلى الله عليه وسلم فقالت: يا رسول الله، ثابت بن قيس، ما أعْتِبُ عليه في خُلُقٍ ولا دِيْنٍ، ولكني أكره الكفر في الإسلام، فقال رسول الله صلى الله عليه وسلم : «أتردين عليه حديقته؟» قالت: نعم، قال رسول الله صلى الله عليه وسلم : «اقبل الحديقة وطلقها تطليقة».","رواه البخاري","صحيح"]]],["الإيلاء",[["عن سليمان بن يَسَار رحمه الله أنه قال: \"أدركت بِضْعَةَ عشر من أصحاب رسول الله صلى الله عليه وسلم كلهم يُوقِفُ الْمُولِي\".","رواه الشافعي والدارقطني","صحيح"]]],["الظهار",[["عن ابن عباس رضي الله عنهما أنه كان يقول: «إذا حَرَّمَ امرأته ليس بشيء» وقال: {لقد كان لكم في رسول الله أُسْوَةٌ حَسَنَةٌ} [الأحزاب: 21]","رواه البخاري","صحيح"],["عن ابن عباس: أن رجلا أتى النبي صلى الله عليه وسلم قد ظَاهَرَ مِنْ امرأته، فَوَقَعَ عليها، فقال: يا رسول الله، إني قد ظَاهَرْتُ مِنْ زَوْجَتِي، فَوَقَعْتُ عليها قَبْلَ أَنْ أُكَفِّرَ، فقال: «وما حَمَلَكَ على ذلك يرحمك الله؟»، قال: رَأَيْتُ خَلْخَالَهَا في ضوء القمر، قال: «فلا تَقْرَبْهَا حتى تَفْعَلَ ما أَمَرَكَ الله به».","رواه أبو داود والترمذي والنسائي وابن ماجه","حسن"],["عن سلمة بن صخر رضي الله عنه قال: كُنْتُ امْرَأً أُصِيبُ من النساء ما لا يُصِيبُ غيري، فلما دخل شهر رمضان خِفْتُ أن أصيب من امرأتي شيئا يُتَابَعُ بي حتى أصبح، فَظَاهَرْتُ منها حتى يَنْسَلِخَ شهر رمضان، فَبَيْنَا هي تَخْدُمُنِي ذات ليلة، إذ تَكَشَّفَ لي منها شيء، فلم أَلْبَثْ أن نَزَوْتُ عليها، فلما أصبحت خرجت إلى قومي فأخبرتهم الخبر، وقلت امشوا معي إلى رسول الله صلى الله عليه وسلم ، قالوا: لا والله. فانطلقت إلى النبي صلى الله عليه وسلم فأخبرته، فقال: «أنت بِذَاكَ يا سلمة؟»، قلت: أنا بذاك يا رسول الله -مرتين- وأنا صابر لأمر الله، فاحكم فيَّ ما أراك الله. قال: «حَرِّرْ رقبة»، قلت: والذي بعثك بالحق ما أملك رقبة غيرها، وضربت صَفْحَةَ رَقَبَتِي، قال: «فصم شهرين متتابعين»، قال: وهل أصبت الذي أصبت إلا من الصيام؟ قال: «فأطعم وَسْقًا من تمر بين ستين مسكينًا»، قلت: والذي بعثك بالحق لقد بِتْنَا وَحْشَيْنِ ما لنا طعام، قال: «فانطلق إلى صاحب صَدَقَةِ بَنِي زُرَيْقٍ فَلْيَدْفَعْهَا إليك، فأطعم ستين مسكينًا وسقًا من تمر وكُلْ أنت وعِيَالُكَ بَقِيَّتَهَا»، فَرَجَعْتُ إِلَى قَوْمِي، فقلت: وجدت عندكم الضِّيقَ، وَسُوءَ الرَّأْيِ، ووجدت عند النبي صلى الله عليه وسلم السَّعَةَ، وَحُسْنَ الرَّأْيِ، وَقَدْ أَمَرَنِي -أَوْ أَمَرَ لِي- بِصَدَقَتِكُمْ.","رواه أبو داود والترمذي وابن ماجه وأحمد والدارمي","حسن"]]],["اللعان",[["عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «لا تَرْغَبُوا عن آبائكم، فمن رغب عن أبيه، فهو كفر».","متفق عليه","صحيح"],["عن عبد الله بن عمر رضي الله عنها : أن رجلا اتهم امرأته بالزنا، ونفى كون ولدها منه في زمن رسول الله صلى الله عليه وسلم فأمرهما رسول الله صلى الله عليه وسلم فتلاعنا، كما قال الله تعالى، ثم قضى بالولد للمرأة، وفرق بين المتلاعنين","متفق عليه","صحيح"],["عن عائشة رضي الله عنها : أن رسول الله صلى الله عليه وسلم دخل عليَّ مسرورًا تبرُقُ أسارِيرُ وجهه. فقال: ألم تَرَيْ أن مُجَزِّزًا نظر آنفًا إلى زيد بن حارثة وأسامة بن زيد، فقال: إن بعض هذه الأقدام لمن بعض». وفي لفظ: «كان مجزِّزٌ قائفًا».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم جاءه أعرابي فقال: يا رسول الله، إن امرأتي ولدت غلاما أسود، فقال: «هل لك من إبل» قال: نعم، قال: «ما ألوانها» قال: حمر، قال: «هل فيها من أَوْرَقَ» قال: نعم، قال: «فأنى كان ذلك» قال: أراه عرق نزعه، قال: «فلعل ابنك هذا نَزَعَهُ عِرْقٌ»","متفق عليه","صحيح"],["إن هِلال بن أُمية قذف امرأته بشريك ابن سَحْماء، وكان أخا البراء بن مالك لأمه، وكان أول رجل لَاعَنَ في الإسلام، قال: فَلَاعَنَهَا، فقال رسول الله صلى الله عليه وسلم : «أبصروها، فإن جاءت به أبيض سَبِطًا، قَضِيءَ الْعَيْنَيْنِ؛ فهو لهلال بن أمية، وإن جاءت به أَكْحَلَ جَعْدًا حَمْشَ السَّاقَيْنِ؛ فهو لشريك بن سحماء»، قال: فأُنبِئْت أنها جاءت به أَكْحَلَ جَعْدًا حَمْشَ السَّاقَيْنِ.","رواه مسلم","صحيح"],["عن أبي رِمْثَةَ رضي الله عنه قال: انطلقت مع أبي نحو النبي صلى الله عليه وسلم ثم إن رسول الله صلى الله عليه وسلم ، قال لأبي: «ابنك هذا؟» قال: إِي ورَبِّ الكعبة، قال: «حقا؟» قال: أشهد به، قال: فتبسم رسول الله صلى الله عليه وسلم ضاحكا من ثَبْتِ شَبَهِي في أبي، ومِنْ حَلِفِ أَبِي عَلَيَّ، ثم قال: «أما إنه لا يَجْني عليك، ولا تَجْني عليه»، وقرأ رسول الله صلى الله عليه وسلم : {ولا تَزِرُ وَازِرَةٌ وِزْرَ أخرى} [الأنعام: 164].","رواه أبو داود والنسائي وأحمد والدارمي","صحيح"],["عن عائشة رضي الله عنها قالت: «اخْتَصَمَ سعد بن أبي وقاص، وعبد بن زَمْعَةَ في غلام: فقال سعد: يا رسول الله، هذا ابن أخي عتبة بن أبي وقاص، عهد إلي أنه ابنه، انظر إلى شبهه، وقال عبد بن زمعة: هذا أخي يا رسول الله، وُلِدَ على فِرَاشِ أبي من وَلِيدَتِهِ، فنظر رسول الله صلى الله عليه وسلم إلى شَبَهِهِ، فرأى شَبَهًا بَيِّنًا بعتبة، فقال: هو لك يا عبد بن زمعة، الولدُ لِلْفِرَاشِ ولِلْعَاهِرِ الحَجَرُ. واحْتَجِبِي منه يا سَوْدَةُ. فلم يَرَ سَوْدَةَ قَطُّ».","متفق عليه","صحيح"],["عن عبد الله بن عمر رضي الله عنهما مرفوعاً: «أن فلان بن فلان قال: يا رسول الله، أرأيت أن لو وجد أحدنا امرأته على فاحشة، كيف يصنع؟ إن تكلم تكلم بأمر عظيم، وإن سَكَتَ سَكَتَ على مثل ذلك. قال: فسكت النبي صلى الله عليه وسلم فلم يُجبه. فلما كان بعد ذلك أتاه فقال: إن الذي سألتك عنه قد ابتليت به. فأنزل الله عز وجل هؤلاء الآيات في سورة النور ?والذين يرمون أزواجهم...? فتلاهن عليه ووعظه وذكره. وأخبره أن عذاب الدنيا أهون من عذاب الآخرة. فقال: لا، والذي بعثك بالحق، ما كذبتُ عليها. ثم دعاها، فوعظها، وأخبرها: أن عذاب الدنيا أهون من عذاب الآخرة. فقالت: لا، والذي بعثك بالحق، إنه لكاذب. فبدأ بالرجل؛ فشهد أربع شهادات بالله: إنه لمن الصادقين، والخامسة: أن لعنة الله عليه إن كان من الكاذبين. ثم ثَنَّى بالمرأة. فشهدت أربع شهادات بالله: إنه لمن الكاذبين، والخامسة: أن غضب الله عليها إن كان من الصادقين. ثم فرق بينهما. ثم قال: إن الله يعلم أن أحدكما كاذب فهل منكما تائب؟ -ثلاثا-»، وفي لفظ «لا سبيل لك عليها. قال: يا رسول الله، مالي؟ قال: لا مال لك: إن كنت صدقت عليها فهو بما استحللت من فرجها، وإن كنت كذبت فهو أبعد لك منها».","متفق عليه","صحيح"],["عن ابن عباس رضي الله عنهما أن هِلَالَ بن أُمَيَّةَ، قذف امرأته عند النبي صلى الله عليه وسلم بِشَرِيكِ بن سَحْمَاءَ، فقال النبي صلى الله عليه وسلم : «البَيِّنَةَ أو حَدٌّ في ظَهْرِكَ»، فقال: يا رسول الله، إذا رأى أحدنا على امرأته رجلًا ينطلق يَلْتَمِسُ البَيِّنَةَ، فجعل النبي صلى الله عليه وسلم يقول: «البَيِّنَةَ وإلا حد في ظهرك» فقال هلال: والذي بعثك بالحق إني لصادق، فلَيُنْزِلَنَّ الله ما يُبَرِّئُ ظهري من الحد، فنزل جبريل وأنزل عليه: {والذين يرمون أزواجهم} [النور: 6] فقرأ حتى بلغ: {إن كان من الصادقين} [النور: 9] فانصرف النبي صلى الله عليه وسلم فأرسل إليها، فجاء هِلال فشهد، والنبي صلى الله عليه وسلم يقول: «إن الله يعلم أن أحَدَكُمَا كاذب، فهل منكما تائب» ثم قامت فشهدت، فلما كانت عند الخامسة وَقَّفُوهَا، وقالوا: إنها مُوجِبَة، قال ابن عباس: فَتَلَكَّأَتْ وَنَكَصَتْ، حتى ظننا أنها ترجع، ثم قالت: لا أفضح قومي سائر اليوم، فَمَضَتْ، فقال النبي صلى الله عليه وسلم : «أبصروها، فإن جاءت به أَكْحَلَ العينين، سَابِغَ الْأَلْيَتَيْنِ، خَدَلَّجَ الساقين، فهو لِشَرِيكِ بْنِ سَحْمَاءَ»، فجاءت به كذلك، فقال النبي صلى الله عليه وسلم : «لولا ما مضى من كتاب الله لكان لي ولها شأن».","متفق عليه واللفظ للبخاري","صحيح"],["عن ابن شهاب، أن سهل بن سعد الساعدي أخبره: أن عُوَيْمِراً العجلاني جاء إلى عاصم بن عدي الأنصاري، فقال له: يا عاصم، أرأيت رجلاً وجد مع امرأته رجلاً، أيقتله فتقتلونه، أم كيف يفعل؟ سل لي يا عاصم عن ذلك رسول الله صلى الله عليه وسلم ، فسأل عاصم رسول الله صلى الله عليه وسلم عن ذلك، فكره رسول الله صلى الله عليه وسلم المسائل وعابها، حتى كبر على عاصم ما سمع من رسول الله صلى الله عليه وسلم ، فلما رجع عاصم إلى أهله جاءه عويمر، فقال: يا عاصم، ماذا قال لك رسول الله صلى الله عليه وسلم ؟ فقال عاصم لعويمر: لم تأتني بخير، قد كره رسول الله صلى الله عليه وسلم المسألة التي سألته عنها، فقال عويمر: والله لا أنتهي حتى أسأله عنها، فأقبل عويمر حتى جاء رسول الله صلى الله عليه وسلم وسط الناس، فقال: يا رسول الله، أرأيت رجلاً وجد مع امرأته رجلًا، أيقتله فتقتلونه، أم كيف يفعل؟ فقال رسول الله صلى الله عليه وسلم : «قد أُنزِل فيك وفي صاحبتك، فاذهب فَأْتِ بها» قال سهل: فَتَلاعَنا وأنا مع الناس عند رسول الله صلى الله عليه وسلم ، فلما فَرَغَا مِن تَلاعُنِهِما، قال عويمر: كذبت عليها يا رسول الله إنْ أَمْسَكْتُها، فطلقها ثلاثا، قبل أن يأمره رسول الله صلى الله عليه وسلم ، قال ابن شهاب: فكانت سُنَّة المُتلاعِنَيْن.","متفق عليه","صحيح"]]],["العدة",[["عن فاطمة بنت قيس، قالت: قلت: يا رسول الله، زوجي طَلَّقَنِي ثلاثا، وأخاف أن يُقْتَحَمَ عَلَيَّ، قال: «فأمَرَها، فَتَحَوَّلَتْ».","رواه مسلم","صحيح"],["عن ابن عباس رضي الله عنهما «أن امرأة ثابت بن قيس اخْتَلَعَت من زوجها على عهد النبي صلى الله عليه وسلم فأمرها النبي صلى الله عليه وسلم أن تَعْتَدَّ بحَيْضَة».","رواه أبو داود والترمذي","صحيح"],["عن أبي سعيد رضي الله عنه أن النبي صلى الله عليه وسلم قال في سَبَايَا أَوْطَاس: «لا تُوطَأُ حَامِلٌ حتى تَضَعَ، ولا غَيْرُ ذَاتِ حَمْلٍ حتى تَحِيضَ حَيْضَةً».","رواه أبو داود وأحمد والدارمي","صحيح"],["عن جابر بن عبد الله قال: طُلِّقَتْ خالتي، فأرادت أن تَجُدَّ نَخْلَهَا، فَزَجَرَهَا رجل أن تخرج، فأتت النبي صلى الله عليه وسلم فقال: «بلى فَجُدِّي نَخْلَكِ، فإنك عسى أن تَصَدَّقِي، أو تفعلي معروفا».","رواه مسلم","صحيح"],["عن زينب بنت أبي سلمة قالت: تُوُفِّيَ حَمِيْمٌ لأم حبيبة، فدعت بصُفْرَةٍ، فَمَسحَتْ بذراعيها، فقالت: إنما أصنع هذا؛ لأني سمعت رسول الله صلى الله عليه وسلم يقول: «لا يحل لامرأة تؤمن بالله واليوم الآخر أن تُحِدَّ على ميت فوق ثلاث، إلا على زوج: أربعة أشهر وعشرًا».","متفق عليه","صحيح"],["عن عروة بن الزبير عن عائشة زوج النبي صلى الله عليه وسلم أنها انْتَقَلَتْ حفصةَ بنتَ عبد الرحمن بن أبي بكر الصديق، حين دَخَلَتْ في الدَّمِ من الحيضة الثالثة. قال ابن شهاب: فذُكر ذلك لِعَمْرَةَ بنت عبد الرحمن. فقالت: صدَق عروة. وقد جادلها في ذلك ناس، وقالوا: إن الله -تبارك وتعالى- يقول في كتابه: {ثَلاَثَةَ قُرُوءٍ} [البقرة 2: 228]. فقالت عائشة: صدقتم، وتدرون ما الأَقْرَاءُ؟. إنما الأَقْرَاءُ الأَطْهَارُ.","رواه مالك","صحيح"],["عن أم سلمة رضي الله عنها مرفوعاً: «جاءت امرأة إلى رسول الله صلى الله عليه وسلم فقالت: يا رسول الله، إن ابنتي توفي عنها زوجها، وقد اشتكت عينها أفَنَكْحُلُها؟ فقال رسول الله صلى الله عليه وسلم : لا -مرتين، أو ثلاثا-، ثم قال: إنما هي أربعة أشهر وعشر، وقد كانت إحداكن في الجاهلية ترمي بالبَعْرَةِ على رأس الحول». فقالت زينب: كانت المرأة إذا توفي عنها زوجها: دخلت حفشا، ولبست شر ثيابها، ولم تَمَسَّ طيبا ولا شيئا حتى تمر بها سنة، ثم تؤتى بدابة -حمار أو طير أو شاة- فتَفْتَضُّ به! فقلما تفتض بشيء إلا مات! ثم تخرج فتُعطى بعرة؛ فترمي بها، ثم تراجع بعد ما شاءت من طيب أو غيره».","متفق عليه","صحيح"]]],["الرضاع",[["عن عائشة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم : «لا تُحَرِّمُ الْمَصَّة وَالْمَصَّتَان».","رواه مسلم","صحيح"],["قال رسول الله صلى الله عليه وسلم في بنت حمزة: «لَا تَحِلُّ لِي يَحْرُمُ من الرَّضَاعِ مَا يَحْرُمُ من النَّسَبِ وهي ابنة أَخِي من الرَّضاعة».","متفق عليه","صحيح"],["عن أم سلمة قالت: قال رسول الله صلى الله عليه وسلم : «لا يُحَرِّمُ من الرَّضَاعَةِ إلا ما فَتَقَ الْأَمْعَاءَ في الثَّدْيِ، وكان قَبْلَ الْفِطَامِ».","رواه الترمذي","صحيح"],["عن عبد الله بن عباس رضي الله عنهما «قال رسول الله صلى الله عليه وسلم في بنت حمزة: لا تحل لي، يحرم من الرضاع: ما يحرم من النسب، وهي ابنة أخي من الرضاعة».","متفق عليه","صحيح"],["عن عائشة- رضي الله عنها- قالت: «دخل علي رسول الله صلى الله عليه وسلم وعندي رجل، فقال: يا عائشة، من هذا؟ قلت: أخي من الرضاعة، فقال: يا عائشة: انظرن من إخوانكن؟ فإنما الرضاعة من المجاعة».","متفق عليه","صحيح"],["عن عائشة، أنها قالت: \"كان فِيمَا أُنْزِلُ من القرآن: (عَشْرُ رَضَعَاتٍ مَعْلُومَاتٍ يُحَرِّمْنَ)، ثم نُسِخْنَ بِخَمْسٍ مَعْلُومَاتٍ، فَتُوُفِّيَ رَسُولُ الله صلى الله عليه وسلم ، وهُنَّ فِيمَا يُقْرَأُ من القرآن\".","رواه مسلم","صحيح"],["عن عقبة بن الحارث رضي الله عنه مرفوعاً: «أنه تزوج أم يحيى بنت أبي إهاب، فجاءت أَمَة سوداء، فقالت: قد أرضعتكما، فذكرت ذلك للنبي صلى الله عليه وسلم . قال: فأعرض عني. قال: فَتَنَحَّيْتُ فذكرت ذلك له. قال: كيف وقد زعمت أن قد أرضعتكما؟!».","رواه البخاري","صحيح"],["عن عائشة رضي الله عنها أن سالما مولى أبي حذيفة كان مع أبي حذيفة وأهله في بيتهم، فأتت -تعني ابنة سُهيل- النبي صلى الله عليه وسلم فقالت: إن سالما قد بلغ ما يبلغ الرجال. وعَقَل ما عقلوا. وإنه يدخل علينا. وإني أظن أن في نفس أبي حذيفة من ذلك شيئا. فقال لها النبي صلى الله عليه وسلم «أَرْضِعِيهِ، تَحْرُمِي عليه، ويذهب الذي في نفس أبي حذيفة» فرجعت فقالت: إني قد أرضعته. فذهب الذي في نفس أبي حذيفة.","رواه مسلم","صحيح"],["عن أم حبيبة بنت أبي سفيان رضي الله عنهما قالت: قلت يا رسول الله، انكح أختي ابنة أبي سفيان. قال: أو تحبين ذلك؟ فقلت: نعم؛ لست لك بمُخْلِيَةٍ، وأحَبُّ من شاركني في خير أختي. فقال رسول الله صلى الله عليه وسلم : إن ذلك لا يحل لي. قالت: إنا نُحَدَّثُ أنك تريد أن تنكح بنت أبي سلمة. قال: بنت أم سلمة؟! قالت: قلت: نعم، قال: إنها لو لم تكن ربيبتي في حَجْرِي، ما حلت لي؛ إنها لابنة أخي من الرضاعة، أرضعتني وأبا سلمة ثويبةُ؛ فلا تعرضن علي بناتكن ولا أخواتكن. قال عروة: وثويبة مولاة لأبي لهب أعتقها، فأرضعت النبي صلى الله عليه وسلم ، فلما مات أبو لهب رآه بعض أهله بشرِّ حِيبة، فقال له: ماذا لقيت؟ قال أبو لهب: لم ألق بعدكم خيرًا، غير أني سقيت في هذه بعتاقتي ثويبة.","متفق عليه","صحيح"],["عن ‌عائشة قالت: إن أفلحَ أخا أبي ‌القُعَيس استأذن عليَّ بعدما نزل الحجاب، فقلت: والله لا آذن له حتى أستأذن رسول الله صلى الله عليه وسلم، فإن أخا أبي ‌القعيس ليس هو أرضعني، ولكن أرضعتني امرأة أبي ‌القعيس، فدخل علي رسول الله صلى الله عليه وسلم فقلت: يا رسول الله، إن الرجل ليس هو أرضعني، ولكن أرضعتني امرأته، قال: «ائذني له، فإنه عمك، تربت يمينك». عَنْ عَائِشَةَ قَالَتْ: إِنَّ أَفْلَحَ أَخَا أَبِي القُعَيْسِ اسْتَأْذَنَ عَلَيَّ بَعْدَ مَا نَزَلَ الحِجَابُ، فَقُلْتُ: وَاللَّهِ لاَ آذَنُ لَهُ حَتَّى أَسْتَأْذِنَ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَإِنَّ أَخَا أَبِي القُعَيْسِ لَيْسَ هُوَ أَرْضَعَنِي، وَلَكِنْ أَرْضَعَتْنِي امْرَأَةُ أَبِي القُعَيْسِ، فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ الرَّجُلَ لَيْسَ هُوَ أَرْضَعَنِي، وَلَكِنْ أَرْضَعَتْنِي امْرَأَتُهُ؟ قَالَ: «ائْذَنِي لَهُ، فَإِنَّهُ عَمُّكِ، تَرِبَتْ يَمِينُكِ» قَالَ عُرْوَةُ: فَبِذَلِكَ كَانَتْ عَائِشَةُ، تَقُولُ: حَرِّمُوا مِنَ الرَّضَاعَةِ مَا يَحْرُمُ مِنَ النَّسَبِ.","متفق عليه","صحيح"]]],["الحضانة",[["عن رافع بن سنان أنه أسلَمَ وأَبَتْ امرأتُه أن تُسْلِم، فأتت النبي صلى الله عليه وسلم ، فقالت: ابنتي وهي فَطِيمٌ أو شَبَهُهُ، وقال رافع: ابنتي، قال له النبي صلى الله عليه وسلم : «اقعد ناحية»، وقال لها: «اقعدي ناحية»، قال: «وأقعد الصَبِيَّةَ بينهما»، ثم قال «ادعواها»، فمَالت الصبية إلى أمها، فقال النبي صلى الله عليه وسلم : «اللهم اهدها»، فمالت الصبية إلى أَبيها، فأخذها.","رواه أبو داود والنسائي وأحمد","صحيح"],["عن أبي ميمونة سلمى مولى من أهل المدينة رجلُ صِدق، قال: بينما أنا جالس مع أبي هريرة، جاءته امرأة فارِسَيّة معها ابنٌ لها فادَّعَيَاه، وقد طلَّقَها زوجُها، فقالت: يا أبا هريرة، ورَطَنَت له بالفارسية، زوجي يريد أن يذهب بابني، فقال أبو هريرة: اسْتَهِما عليه ورَطَنَ لها بذلك، فجاء زوجها، فقال: مَن يُحاقُّني في ولدي، فقال أبو هريرة: اللهم إني لا أقول هذا إلا أني سمعت امرأةً جاءت إلى رسول الله صلى الله عليه وسلم ، وأنا قاعد عنده، فقالت: يا رسول الله، إن زوجي يريد أن يذهب بابني، وقد سقاني من بِئر أبي عِنَبَة، وقد نفعني، فقال رسول الله صلى الله عليه وسلم اسْتَهِما عليه، فقال زوجها: من يُحَاقُّنِي في ولدي؟ فقال النبي صلى الله عليه وسلم : «هذا أبوك، وهذه أمك فخُذْ بيدِ أيِّهما شِئت»، فأخذ بيد أمِّه، فانطلقت به.","رواه أبو داود والترمذي والنسائي وابن ماجه وأحمد","صحيح"],["عن عبد الله بن عمرو رضي الله عنهما أن امرأة قالت: يا رسول الله، إن ابني هذا كان بطني له وِعاء، وثَدْيِي له سِقاء، وحِجْري له حِواء، وإن أباه طَلَّقَني، وأراد أنْ يَنْتَزِعَه مِني، فقال لها رسول الله صلى الله عليه وسلم : «أنتِ أحقُّ به ما لم تَنكحي».","رواه أبو داود وأحمد","حسن"]]],["النفقات",[["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «قَالَ اللهُ: أَنْفِقْ يَا ابْنَ آدَمَ أُنْفِقْ عَلَيْكَ».","متفق عليه","صحيح"],["عن أبي مسعود رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إِذَا أَنْفَقَ الرَّجُلُ عَلَى أَهْلِهِ يَحْتَسِبُهَا فَهُوَ لَهُ صَدَقَةٌ».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لا يَقْتَسِمُ وَرَثَتي دينارًا ولا درهمًا، ما تَرَكْتُ بَعْدَ نَفَقَة نسائي، ومئونَة عامِلي فهو صَدَقة».","متفق عليه","صحيح"],["عن أم سلمة رضي الله عنها ، قالت: قلت: يا رسول الله، هل لي أجرٌ في بني أبي سلمة أن أُنْفِقَ عليهم، ولستُ بتاركتهم هكذا وهكذا إنما هم بَنِيَّ؟ فقال: «نعم، لك أجرُ ما أنفقتِ عليهم».","متفق عليه","صحيح"],["عن كَعْب بن مالك رضي الله عنه قال: قلتُ: يا رسولَ الله، إن مِن تَوبتي أن أَنْخَلِعَ مِنْ مالي؛ صدقةً إلى الله وإلى رسولِه، فقال رسولُ الله صلى الله عليه وسلم : \"أمسِكْ عليك بعضَ مالِكَ؛ فهو خيرٌ لكَ\".","متفق عليه","صحيح"],["عن عائشة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم «إذا أَنْفَقَتِ المرأة من طعام بيتها غيرَ مُفْسِدَةٍ كان لها أجرها بما أنفقت، ولزوجها أجره بما كسب، وللخازن مثل ذلك، لا ينقص بعضهم أجر بعض شيئًا».","متفق عليه","صحيح"],["عن طارق المُحَارِبِيِّ، قال: قَدِمْنَا المدينة فإذا رسول الله صلى الله عليه وسلم قَائِمٌ على المِنْبَرِ يَخْطُبُ النَّاسَ وهو يقول: \"يَدُ الْمُعْطِي الْعُلْيَا، وَابْدَأْ بِمَنْ تَعُولُ: أُمَّكَ وأَبَاكَ، وأُخْتَكَ وأَخَاكَ، ثُمَّ أَدْنَاكَ أَدْنَاكَ\".","رواه النسائي","صحيح"],["عن خَيْثَمَةَ، قال: كنا جلوسًا مع عبد الله بن عمرو، إذ جاءه قَهْرَمَانٌ له فَدَخَلَ، فقال: أَعْطَيْتَ الرَّقِيقَ قُوتَهُمْ؟ قال: لا، قال: فَانْطَلِقْ فَأَعْطِهِمْ، قال: قال رسول الله صلى الله عليه وسلم : «كَفَى بِالْمَرْءِ إِثْمًا أَنْ يَحْبِسَ عَمَّنْ يَمْلِكُ قُوتَهُ».","رواه مسلم","صحيح"]]],["اللباس والزينة",[["عن أنس بن مالك رضي الله عنه قال: نهى النبي صلى الله عليه وسلم أن يَتَزَعْفَرَ الرجلُ.","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: لعن رسول الله صلى الله عليه وسلم الرجل يلبس لِبْسَةَ المرأة، والمرأة تلبس لِبْسَةَ الرجل.","رواه النسائي في الكبرى وابن ماجه بمعناه وأحمد","صحيح"],["عن عبد الله بن عمر رضي الله عنهما قال: لعن النبي صلى الله عليه وسلم الوَاصِلَةَ والمُسْتَوْصِلَةَ، والوَاشِمَةَ والمُسْتَوشِمَةَ.","متفق عليه","صحيح"],["عن عمرو بن شعيب، عن أبيه، عن جده رضي الله عنه عن النبي صلى الله عليه وسلم قال: «لا تَنْتِفُوا الشَّيْبَ؛ فإنه نُور المسلم يوم القيامة».","رواه أبو داود والترمذي وأحمد وابن ماجه والنسائي","صحيح"],["عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إذا انقطع شِسْعُ نَعْل أحدكم، فلا يَمْشِ في الأخرى حتى يُصلِحها».","رواه مسلم","صحيح"],["عن ابن عمر رضي الله عنهما قال: رأى رسول الله صلى الله عليه وسلم صبيًّا قد حُلِق بعض شعر رأسه وترك بعضه، فنهاهم عن ذلك، وقال: «احلقوه كله، أو اتركوه كله».","رواه أبو داود والنسائي في الكبرى","صحيح"],["عن جابر رضي الله عنه قال: أُتِيَ بأبي قُحَافَة والد أبي بكر الصديق رضي الله عنهما ، يوم فتح مكة ورأسه ولحيته كَالثَّغَامَةِ بياضًا. فقال رسول الله صلى الله عليه وسلم : «غَيِّرُوا هذا واجْتَنِبوا السَّواد».","رواه مسلم","صحيح"]]],["المجتمع المسلم",[["عن عبد الله بن عمر رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «المؤمن الذي يخالط الناس، ويصبر على أذاهم خير من الذي لا يخالط الناس ولا يصبر على أذاهم».","رواه الترمذي وابن ماجه وأحمد","صحيح"],["عن عبد الله بن عمرو رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «لَيْسَ الْوَاصِلُ بِالْمُكَافِئِ، وَلَكِنِ الْوَاصِلُ الَّذِي إِذَا قُطِعَتْ رَحِمُهُ وَصَلَهَا».","رواه البخاري","صحيح"],["عن أم سلمة رضي الله عنها قالت: كان رسول الله صلى الله عليه وسلم إذا سلم قام النساء حين يقضي تسليمه، ومكث يسيرًا قبل أن يقوم. قال ابن شهاب: فأرى والله أعلم أن مكثه لكي ينفذ النساء قبل أن يدركهن من انصرف من القوم.","رواه البخاري","صحيح"],["عن أبي موسى الأشعري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : \"إنَّ الأشعريين إذا أرمَلُوا في الغَزْوِ، أو قَلَّ طعامُ عِيالِهم بالمدينةِ، جَمَعُوا ما كان عندهم في ثوبٍ واحدٍ، ثم اقتَسَمُوه بينهم في إناءٍ واحدٍ بالسَّوِيَّةِ، فَهُم مِنِّي وأنا مِنهُم\".","متفق عليه","صحيح"]]],["أحكام النساء",[["عن ابن عباس قال: قال رسول الله صلى الله عليه وسلم: \"ليس على النساء الحلق، إنما على ‌النساء ‌التقصير\".","رواه أبو داود","صحيح"],["عن جابر رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا يَبِيتَنَّ رجل عند امرأة ثيِّب، إلا أنْ يكون ناكِحًا أو ذا مَحْرَم».","رواه مسلم","صحيح"],["عن عبد الله عن النبي صلى الله عليه وسلم قال: \"صلاة المرأة في بيتها أفضل من صلاتها في حجرتها، وصلاتها في مخدعها أفضل من صلاتها في بيتها\".","رواه أبو داود","صحيح"],["عن عبد الله بن عمرو رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «الدُّنْيَا مَتَاعٌ، وَخَيْرُ مَتَاعِ الدُّنْيَا الْمَرْأَةُ الصَّالِحَةُ».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه ، قال: قال رسول الله صلى الله عليه وسلم : «إذا دعا الرجل امرأته إلى فراشه فَأَبَتْ فَبَاتَ غَضْبَانَ عليها لَعَنَتْهَا الملائكة حتى تصبح».","متفق عليه","صحيح"],["عن ابن عباس رضي الله عنهما في قصة بريرة وزوجها، قال: قال لها النبي صلى الله عليه وسلم : «لو رَاجَعْتِهِ؟» قالت: يا رسول الله تأمرني؟ قال: «إنما أشْفَع» قالت: لا حاجة لي فيه.","رواه البخاري","صحيح"],["عن عائشة قالت: كنت أشرب وأنا حائض، ثم أناوله النبي صلى الله عليه وسلم فيضع فاه على موضع فيَّ، فيشرب، وأتعرق العرق وأنا حائض، ثم أناوله النبي صلى الله عليه وسلم فيضع فاه على موضع فيَّ.","رواه مسلم","صحيح"],["عن أسماء رضي الله عنها : أن امرأة قالت: يا رسول الله، إن لي ضَرَّةً فهل علي جُناح إن تشبَّعْتُ من زوجي غير الذي يعطيني؟ فقال النبي صلى الله عليه وسلم : «المُتَشَبِّعُ بما لم يُعطَ كلابس ثَوْبَي زُورٍ».","متفق عليه","صحيح"]]],["أحكام المولود",[["عن ابن عباس «أن رسول الله صلى الله عليه وسلم عَقَّ عن الحسن والحسين كَبْشًا كَبْشًا».","رواه أبو داود","صحيح"],["عن يوسف بن عبد الله بن سلام رضي الله عنهما قال: «سَمَّاني رسول الله صلى الله عليه وسلم يوسف، وأَجْلَسَنِي في حِجْره».","رواه أحمد","صحيح"],["عن عائشة «أن رسول الله صلى الله عليه وسلم أمرهم أن يُعَقَّ عن الغُلَامِ شَاتَانِ مُكَافِئَتَانِ، وعن الْجَارِيَةِ شَاةٌ».","رواه الترمذي وأحمد","صحيح"],["عن سمرة قال: قال رسول الله صلى الله عليه وسلم : «الغلام مُرْتَهَنٌ بِعَقِيقَتِهِ يُذْبَحُ عنه يوم السابع، ويُسَمَّى، ويُحْلَق رأسه».","رواه أبو داود والترمذي والنسائي وابن ماجه وأحمد والدارمي","صحيح"],["عن أنس بن مالك رضي الله عنه قال: غَدَوتُ إلى رسول الله صلى الله عليه وسلم بعبد الله بن أبي طلحة، ليُحنِّكَه، فوافيتُه في يده المِيْسَمُ يَسِمُ إبلَ الصدقة.","متفق عليه","صحيح"]]]]],["المعاملات والبيوع",1,[["البيوع",[["عن جابر رضي الله عنه أن النبي صلى الله عليه وسلم اشْتَرَى منه بَعِيراً، فَوَزَنَ له فَأرْجَح.","متفق عليه","صحيح"],["عن عبد الله بن عمر- رضي الله عنهما- مرفوعاً: «أن النبي صلى الله عليه وسلم نهى عن بيع الوَلاءِ وعن هِبَتِهِ».","متفق عليه","صحيح"],["عن أبي مسعود رضي الله عنه «أن رسول الله صلى الله عليه وسلم نهى عن ثمن الكلب، ومَهْرِ البغي، وحُلْوَانِ الكَاهِنِ».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه : «أن رسول الله صلى الله عليه وسلم رخص في بيع العرايا، في خمسة أوَسْقُ ٍأو دون خمسة أوسق».","متفق عليه","صحيح"],["عن عبد الله بن عمر- رضي الله عنهما- مرفوعاً: «أن رسول الله صلى الله عليه وسلم نهى عن بيع الثمرة حتى يبدو صلاحها، نهى البائع و المُبْتَاعَ».","متفق عليه","صحيح"],["عن أبي قتادة رضي الله عنه : أنه سمع رسول الله صلى الله عليه وسلم يقول: «إيَّاكُمْ وكَثْرَةَ الحَلِفِ في البيع، فإنه يُنَفِّقُ ثم يَمْحَقُ».","رواه مسلم","صحيح"],["عن عبد الله بن عمر رضي الله عنهما عن النبي صلى الله عليه وسلم أنه قال: «من ابْتَاعَ طعاما فلا يَبِعْهُ حتى يَسْتَوْفِيَهُ»، وفي لفظ: «حتى يَقْبِضَهُ».","متفق عليه","صحيح"]]],["السلم",[["عن عبد الله بن عباس رضي الله عنهما قال: قدم رسول الله صلى الله عليه وسلم المدينة، وهم يُسلفون في الثمار: السنة والسنتين والثلاث، فقال: «من أسلَفَ في شيء فليُسلف في كيل معلوم، ووزن معلوم، إلى أجل معلوم».","متفق عليه","صحيح"]]],["الربا",[["عن ابن عمر قال: قال رسول الله صلى الله عليه وسلم: \"الوزن وزن أهل مكة، والمكيال مكيال أهل المدينة\".","رواه أبو داود والنسائي","صحيح"],["عن أبي المنهال قال: «سألت البراء بن عازب، وزيد بن أرقم، عن الصَّرْفِ؟ فكل واحد يقول: هذا خير مني. وكلاهما يقول: نهى رسول الله صلى الله عليه وسلم عن بيع الذهب بالوَرِقِ دَيْنَاً».","متفق عليه","صحيح"],["عن أبي بكرة رضي الله عنه قال: «نهى رسول الله صلى الله عليه وسلم عن الفضة بالفضة، والذهب بالذهب، إلا سَوَاءً بسوَاءٍ، وأمرنا أن نشتري الفضة بالذهب، كيف شئنا. ونشتري الذهب بالفضة كيف شئنا، قال: فسأله رجل فقال: يدا بيد؟ فقال: هكذا سمعت».","متفق عليه","صحيح"],["عن أبي سعيد الخدري- رضي الله عنه-: جاء بلال إلى رسول الله صلى الله عليه وسلم بتمر بَرْنِيٍّ، فقال له النبي صلى الله عليه وسلم : «من أين لك هذا؟» قال بلال: كان عندنا تمر رديء، فبعتُ منه صاعين بصاع ليطعم النبي صلى الله عليه وسلم . فقال النبي صلى الله عليه وسلم عند ذلك: «أَوَّهْ، أَوَّهْ، عَيْنُ الربا، عين الربا، لا تفعل، ولكن إذا أردت أن تشتري فَبِعِ التمرَ ببيع آخر، ثم اشتر به».","متفق عليه","صحيح"]]],["القرض",[["عن أبي هريرة رضي الله عنه : أن رجلًا أتى النبي صلى الله عليه وسلم يَتَقَاضَاهُ فَأغْلَظَ له، فَهَمَّ به أصحابه، فقال رسول الله صلى الله عليه وسلم : «دَعُوه، فإن لِصَاحب الحَقِّ مَقَالا» ثم قال: «أعْطُوهُ سِنًّا مِثْل سِنِّهِ» قالوا: يا رسول الله، لا نَجِدُ إلا أمْثَلَ مِنْ سِنِّهِ، قال: «أعْطُوه، فإن خَيْرَكم أحْسَنُكُم قَضَاء».","متفق عليه","صحيح"]]],["الرهن",[["عن عائشة بنت أبي بكر رضي الله عنهما أن رسول الله -صلى الله عليه وسلم اشترى من يهودي طعاما، ورهنه دِرْعًا من حديد.","متفق عليه","صحيح"]]],["الضمان والكفالة",[["عن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم : أنَّه ذكر رجلًا من بني إسرائيل، سأل بعضَ بني إسرائيل أن يُسْلِفَه ألفَ دينار، فقال: ائْتِنِي بالشهداء أُشْهِدُهم، فقال: كفى بالله شهيدًا، قال: فَأْتِنِي بالكَفِيل، قال: كَفَى بالله كفيلًا، قال: صَدَقتَ، فَدَفَعَها إِليه إلى أجل مُسَمَّى، فخرج في البحر فقَضَى حَاجَتَه، ثُمَّ التَمَسَ مركَبًا يَرْكَبُها يَقْدَم عليه لِلأَجَل الذي أجَّله، فلم يجِد مركَبًا، فأَخَذَ خَشَبَة فَنَقَرَها، فَأَدْخَل فِيهَا أَلفَ دِينَار وصَحِيفَة مِنْه إلى صاحبه، ثم زَجَّجَ مَوضِعَها، ثمَّ أَتَى بِهَا إِلَى البحر، فقال: اللَّهُمَّ إنَّك تعلم أنِّي كنتُ تَسَلَّفتُ فلانًا ألف دِينَار، فَسَأَلَنِي كفيلًا، فقلتُ: كفى بالله كفيلًا، فَرَضِيَ بك، وسأَلَنِي شهيدًا، فقلتُ: كفى بالله شهيدًا، فرضِي بك، وأنِّي جَهَدتُ أنْ أَجِدَ مَركَبا أَبعث إليه الذي لَه فَلَم أَقدِر، وإنِّي أسْتَوْدِعُكَها. فرمى بها في البحر حتَّى وَلَجِت فيه، ثم انْصَرف وهو في ذلك يلتمس مركبا يخرج إلى بلده، فخرج الرجل الذي كان أسلفه، ينظُر لعلَّ مَركَبًا قد جاء بماله، فَإِذا بِالخَشَبَة التي فيها المال، فأَخَذَها لِأهله حَطَبًا، فلمَّا نَشَرَها وجَد المالَ والصحِيفة، ثمَّ قدِم الذي كان أسلفه، فأتى بالألف دينار، فقال: والله ما زلتُ جاهدًا في طلب مركب لآتيك بمالك، فما وجدتُ مركبا قبل الذي أتيتُ فيه، قال: هل كنتَ بعثتَ إليَّ بشيء؟ قال: أُخبِرك أنِّي لم أجِد مركبا قبل الذي جئتُ فيه، قال: فإنَّ الله قد أدَّى عنك الذي بعثتَ في الخشبة، فانصرِف بالألف الدينار راشدًا».","رواه البخاري","صحيح"]]],["الصلح وأحكام الجوار",[["عن ابن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: «مَا زَالَ يُوصِينِي جِبْرِيلُ بِالْجَارِ، حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه أنّ رسولَ الله صلى الله عليه وسلم قال: «لا يمَنَعَنَّ جارٌ جاره: أن يغرِزَ خَشَبَهُ في جداره، ثم يقول أبو هريرة: ما لي أراكم عنها مُعْرِضِين؟ والله لَأرْميَنّ َبها بين أكتافكم».","متفق عليه","صحيح"]]],["الوكالة",[["عن عروة البارقي أن النبي صلى الله عليه وسلم أعطاه دينارًا يشتري له به شاةً، فاشترى له به شاتين، فباع إحداهما بدينارٍ، وجاءه بدينارٍ وشاةٍ، فدعا له بالبركة في بيعه، وكان لو اشترى التراب لربح فيه.","رواه البخاري","صحيح"]]],["الشركة",[["عن أبي موسى الأشعري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : \"إنَّ الأشعريين إذا أرمَلُوا في الغَزْوِ، أو قَلَّ طعامُ عِيالِهم بالمدينةِ، جَمَعُوا ما كان عندهم في ثوبٍ واحدٍ، ثم اقتَسَمُوه بينهم في إناءٍ واحدٍ بالسَّوِيَّةِ، فَهُم مِنِّي وأنا مِنهُم\".","متفق عليه","صحيح"]]],["المساقاة والمزارعة",[["عن عبدالله بن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم عامل أهل خيبر بِشَطْرِ ما يخرج منها من ثَمَرٍ أو زرع.","متفق عليه","صحيح"],["عن حنظلة بن قيس قال: سألت رافع بن خديج عن كراء الأرض بالذهب والورق؟ فقال: لا بأس به، إنما كان الناس يؤاجرون على عهد رسول الله صلى الله عليه وسلم بما على المَاذَيَاناتِ، وأَقْبَالِ الجَدَاوِلِ، وأشياء من الزرع؛ فيهلك هذا، ويسلم هذا، ولم يكن للناس كراء إلا هذا؛ ولذلك زجر عنه، فأما شيء معلوم مضمون؛ فلا بأس.","رواه مسلم","صحيح"]]],["السبق والقمار والميسر",[["عن ابن عمر «أن النبي صلى الله عليه وسلم سَبَّقَ بين الخيل، وفَضَّلَ القُرَّحَ في الغاية».","رواه أبو داود وأحمد","صحيح"],["عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم : «لا سَبَقَ إلا في خُفٍّ أو في حَافِرٍ أو نَصْلٍ».","رواه أبو داود والترمذي والنسائي وابن ماجه وأحمد","صحيح"]]],["الغصب",[["عن عائشة رضي الله عنها عن النبي صلى الله عليه وسلم قال: «مَنْ ظَلَم قِيدَ شِبْرٍ مِن الأرْضِ؛ طُوِّقَهُ مِن سَبْعِ أَرَضِين».","متفق عليه","صحيح"]]],["الشفعة",[["عن جابر بن عبد الله رضي الله عنهما قال: (جعل وفي لفظ: قضى) النبي صلى الله عليه وسلم بالشُّفْعة في كل ما لم يقسم، فإذا وقعت الحدود، وصُرِّفَتِ الطرق؛ فلا شفعة).","متفق عليه","صحيح"]]],["اللقطة واللقيط",[["عن زيد بن خالد الجهني رضي الله عنه : «سئل رسول الله صلى الله عليه وسلم عن لُقَطَة الذهب، أو الوَرِق؟ فقال: اعرف وكِاَءَهَا وعِفَاصَهَا، ثم عَرِّفْهَا سَنَةً، فإن لم تُعرَف فاستنفقها، ولتكن وديعة عندك فإن جاء طالبها يوما من الدهر؛ فأدها إليه. وسأله عن ضالة الإبل؟ فقال: ما لك ولها؟ دَعْهَا فإن معها حِذَاَءَهَا وسِقَاءَهَا، تَرِدُ الماء وتأكل الشجر، حتى يجدها رَبُّهَا. وسأله عن الشاة؟ فقال: خذها؛ فإنما هي لك، أو لأخيك، أو للذئب».","متفق عليه","صحيح"],["عن عبد الله بن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم يوم فتح مكة: «لا هجرة بعد الفتح، ولكن جهاد ونية. وإذا اسْتُنْفِرْتُم فَانْفِرُوا. وقال يوم فتح مكة: «إن هذا البَلد حَرَّمَهُ الله يوم خلق الله السموات والأرض، فهو حَرَامٌ بحُرْمَةِ الله إلَى يوم القيامة، وإنه لم يحل القتال فيه لِأَحَدٍ قَبْلِي، ولم يَحِلَّ لي إلا ساعة من نهار، حرام بِحرمة الله إلى يوم القيامة، لا يُعْضَدُ شَوْكُهُ، وَلاَ يُنَفَّرُ صَيْدُهُ، وَلاَ يَلْتَقِطُ لُقَطَتَهُ إلا من عَرَّفَهَا، ولاَ يُخْتَلَى خَلاَهُ». فقال العباس: يا رسول الله، إلا الإِذْخِرَ؛ فإنه لِقَيْنِهِمْ وبيوتهم؟ فقال: «إلا الإِذْخِرَ».","متفق عليه","صحيح"]]],["الوقف",[["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «مَنْ احْتَبَسَ فَرَسًا في سَبِيل الله، إيمانًا بالله، وتَصْدِيقًا بِوَعْدِه، فإن شِبَعَهُ وريَّه ورَوْثَهُ وبَوْلَه في مِيْزَانه يوم القيامة».","رواه البخاري","صحيح"],["عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم قَالَ: «إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةٍ: إِلَّا مِنْ صَدَقَةٍ جَارِيَةٍ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ».","رواه مسلم","صحيح"],["عن عبد الله بن عمر رضي الله عنهما قال: «قد أصاب عمر أرضًا بخيبر. فأتى النبي صلى الله عليه وسلم يستأمره فيها. فقال: يا رسول الله، إني أصبت أرضًا بخيبر، لم أُصِبْ مالًا قَطُّ هو أنفس عندي منه، فما تأمرني به؟ فقال: إن شِئْتَ حَبَّسْتَ أصلها، وتصدقت بها. قال: فتصدق بها، غير أنه لا يُباع أصلها، ولا يوهب، ولا يورث. قال: فتصدق عمر في الفقراء، وفي القربى، وفي الرقاب، وفي سبيل الله، وابن السبيل، والضيف. لا جناح على من وليها أن يأكل منها بالمعروف، أو يطعم صديقًا، غير مُتَمَوِّلٍ فيه»، وفي لفظ: «غير مُتَأثِّلٍ».","متفق عليه","صحيح"],["عن أنس بن مالك رضي الله عنه قال: كان أبو طلحة رضي الله عنه أكثر الأنصار بالمدينة مالا من نخل، وكان أحب أمواله إليه بَيْرَحَاء، وكانت مُسْتَقبِلَةَ المسجد وكان رسول الله صلى الله عليه وسلم يدخلها ويشرب من ماء فيها طيب. قال أنس: فلما نزلت هذه الآية: {لن تنالوا البر حتى تُنِفُقوا مما تُحبون} قام أبو طلحة إلى رسول الله صلى الله عليه وسلم فقال: يا رسول الله، إن الله تعالى أنزل عليك: {لن تنالوا البر حتى تنفقوا مما تحبون} وإن أحب مالي إلي بَيْرَحَاء، وإنها صدقة لله تعالى ، أرجو بِرَّهَا وذُخْرَهَا عند الله تعالى ، فَضَعْهَا يا رسول الله حيث أَرَاكَ الله، فقال رسول الله صلى الله عليه وسلم : «بَخٍ ذلك مال رَابِحٌ، ذلك مال رابح، وقد سمعتُ ما قلتَ، وإني أرى أن تجعلها في الأقربين»، فقال أبو طلحة: أفعل يا رسول الله، فقسمها أبو طلحة في أقاربه، وبني عمه.","متفق عليه","صحيح"]]],["الهبة والعطية",[["عن خالد بن عدي الجهني قال: سمعت رسول الله صلى الله عليه وسلم يقول: \"من بلغه معروف عن أخيه من غير مسألة ولا إشراف نفس فليقبله ولا يرده، فإنما هو رزق ساقه الله إليه\".","رواه أحمد","صحيح"],["عن الصعب بن جَثَّامَةَ رضي الله عنه ، قال: أهديتُ رسولَ الله - صلى الله عليه وسلم - حماراً وحشياً، فَرَدَّهُ عَلَيَّ، فلما رأى ما في وجهي، قال: «إنا لم نَرُدَّهُ عليك إلا لأنَّا حُرُمٌ».","متفق عليه","صحيح"],["عن أم المؤمنين ميمونة بنت الحارث رضي الله عنها : أنها أعتقت وَليدَةً ولم تستأذن النبي صلى الله عليه وسلم فلما كان يَومُها الذي يَدورُ عليها فيه، قالت: أشَعَرْتَ يا رسول الله، أني أعتقت وليدتي؟ قال: «أو فعلت؟» قالت: نعم. قال: «أما إنك لو أعطيتها أخوالك كان أعظم لأجرك».","متفق عليه","صحيح"],["عن عمر بن الخطاب رضي الله عنه قال: «حَمَلْتُ على فرس في سبيل الله، فأضاعه الذي كان عنده، فأردت أن أشتريه، وظننت أنه يبيعه بِرُخْصٍ، فسألت النبي صلى الله عليه وسلم ؟ فقال: لا تَشْتَرِهِ، ولا تعد في صدقتك؛ فإن أَعْطَاكَهُ بِدِرْهَمٍ؛ فإن العَائِدَ في هِبَتِهِ كالعَائِدِ في قَيْئِهِ».","متفق عليه","صحيح"],["عن جابر أن أم مالك كانت تُهدِي للنبي صلى الله عليه وسلم في عُكَّةٍ لها سمنًا، فيأتيها بنوها فيسألون الأُدْمَ، وليس عندهم شيء، فتعمد إلى الذي كانت تهدي فيه للنبي صلى الله عليه وسلم، فتجد فيه سمنًا، فما زال يقيم لها أدم بيتها حتى عصرته، فأتت النبي صلى الله عليه وسلم فقال: «عَصَرْتِيْها؟» قالت: نعم، قال «لو تركتيها ما زال قائمًا».","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها أنها اشترتْ بَريرَة مِنْ أُناسٍ من الأنصار واشْتَرَطوا الوَلاء، فقال رسول الله صلى الله عليه وسلم : «الوَلاءُ لِمَنْ وَلِيَ النِّعْمَة»، وخَيَّرَهَا رسول الله صلى الله عليه وسلم وكان زوْجُها عبْدا، وأهدَتْ لعائشة لحْما، فقال رسول الله صلى الله عليه وسلم : «لو صَنَعْتُم لنا من هذا اللحم»، قالت عائشة: تُصُدِّقَ به على بَرِيرَة، فقال: «هو لها صدَقة ولنا هديَّة».","متفق عليه","صحيح"]]],["الوصية",[["عن أبي هريرة أن رجلًا قال للنبي صلى الله عليه وسلم: إن أبي مات وترك مالًا، ولم يوص، فهل يكفر عنه أن أتصدق عنه؟ قال: «نعم».","رواه مسلم","صحيح"],["عن عمرو بن خارجة رضي الله عنه : أن النبي صلى الله عليه وسلم خطب على ناقته وأنا تحت جِرَانِها وهي تَقْصَع بِجِرَّتِها، وإن لُعابها يَسِيل بين كتفيَّ فسمعتُه يقول: «إن الله أعطى كلِّ ذي حقٍّ حقَّه، ولا وصيَّةَ لِوارث، والولَد لِلْفِراش، وللعاهِرِ الحَجَر، ومن ادَّعى إلى غير أبِيهِ أو انْتمى إلى غير مَوَاليه رغبةً عنهم فعَلِيه لعنةُ الله، لا يَقْبَلُ الله منه صَرْفا ولا عَدْلا».","رواه الترمذي وابن ماجه وأحمد","صحيح"],["عن سعد بن أبي وقاص رضي الله عنه قال: جاءني رسول الله صلى الله عليه وسلم يَعُودُنِي عام حَجَّةِ الوداع من وَجَعٍ اشْتَدَّ بي، فقلت: يا رسول الله، قد بلغ بي من الوَجَعِ ما ترى، وأنا ذو مال، ولا يَرِثُنِي إلا ابنةٌ أَفَأَتَصَدَّقُ بثلثي مالي؟ قال: لا، قلت: فالشَّطْرُ يا رسول الله؟ قال: لا، قلت: فالثلث؟ قال: الثلث، والثلث كثير، إنك إن تَذَرَ وَرَثَتَكَ أغنياء خيرٌ من أن تَذَرَهُم عالَةً يَتَكَفَّفُونَ الناس، وإنك لن تنفق نفقة تبتغي بها وجه الله إلا أُجِرْتَ بها، حتى ما تجعل في فِيْ امرأتك. قال: قلت: يا رسول الله أُخَلَّفُ بعد أصحابي؟ قال: إنك لن تُخَلَّفُ فتعمل عملا تبتغي به وجه الله إلا ازْدَدْتَ به درجة ورِفْعَةً، ولعلك أن تُخَلَّفَ حتى ينتفع بك أقوام، ويُضَرُّ بك آخرون. اللهم أَمْضِ لأصحابي هجرتهم، ولا تَرُدَّهُم على أَعْقَابِهِم، لكنِ البَائِسُ سعد بن خَوْلَةَ (يَرْثِي له رسول الله صلى الله عليه وسلم أن مات بمكة).","متفق عليه","صحيح"],["عن حنظلة بن حِذْيَم، أن جدَّه حَنِيفَة قال لحِذْيَم: اجمع لي بنيَّ، فإني أريد أن أُوصِي، فجَمَعهم، فقال: إنَّ أوَّل ما أوصي أنَّ ليَتِيمي هذا الذي في حَجْري مائة من الإبل، التي كنا نُسمِّيها في الجاهلية: المُطَيِّبة، فقال حِذْيَم: يا أبَتِ، إني سمعت بَنِيك يقولون: إنما نُقِرُّ بهذا عند أَبِينا، فإذا مات رجَعْنا فيه، قال: فبَيْني وبيْنكم رسول الله صلى الله عليه وسلم ، فقال حِذيم: رَضِينا، فارْتَفَعَ حذيم، وحنيفة، وحنْظَلَة معهم غُلام، وهو رَدِيف لحذيم، فلما أتوا النبي صلى الله عليه وسلم ، سلَّموا عليه، فقال النبي صلى الله عليه وسلم : «ما رَفَعَك يا أبا حذيم؟» قال: هذا، وضرَب بيده على فَخِذ حذيم، فقال: إني خَشِيتُ أن يَفْجَأَني الكِبَر، أو الموْت، فأردتُ أن أوصي، وإني قلتُ: إن أوَّل ما أوصي أن ليتيمي هذا الذي في حَجْري مائة من الإبل، كنا نُسَمِّيها في الجاهلية: المُطَيِّبة، فغَضِب رسول الله صلى الله عليه وسلم ، حتى رأَيْنا الغضب في وجهه، وكان قاعدًا فجَثَا على ركبتيه، وقال: «لا، لا، لا الصدقة خمس، وإلا فعشر، وإلا فخمس عشرة، وإلا فعشرون، وإلا فخمس وعشرون، وإلا فثلاثون، وإلا فخمس وثلاثون، فإن كَثُرت فأربعون» ، قال: فودَّعوه ومع اليتيم عصا، وهو يَضْرب جملا، فقال النبي صلى الله عليه وسلم : «عَظُمَت هذه هراوة يتيم» ، قال حنظلة: فَدَنا بي إلى النبي صلى الله عليه وسلم ، فقال: إنَّ لي بَنِين ذوي لِحى، ودون ذلك، وإنَّ ذا أصغرُهم، فادع الله له، فَمَسَح رأسه، وقال: «بارك الله فيك» ، أو «بورك فيه» ، قال ذَيَّالٌ: فلقد رأيتُ حنظلة، يؤتى بالإنسان الوارِم وجهه، أو بالبهيمة الوارِمة الضَّرع، فيَتْفُل على يديه، ويقول: بسم الله، ويضع يده على رأسه، ويقول على موْضِع كف رسول الله صلى الله عليه وسلم ، فَيَمْسحه عليه، وقال ذيال: فَيَذْهب الوَرَم.","رواه أحمد","صحيح"]]],["العتق",[["عن سمرة قال: قال رسول الله صلى الله عليه وسلم : «من مَلَكَ ذا رَحِمٍ مَحْرَمٍ فهو حُرٌّ».","رواه أبو داود والترمذي وابن ماجه وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال النبي صلى الله عليه وسلم : «أَيُّمَا رَجُلٍ أَعْتَقَ امْرَأً مسلمًا، استَنْقَذَ الله بكلِّ عُضْوٍ منه عُضْوا منه مِن النار».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «للعبد المملوك المصلح أجران»، والذي نفس أبي هريرة بيده لولا الجهاد في سبيل الله والحج، وبر أمي، لأحببت أن أموت وأنا مملوك.","متفق عليه","صحيح"],["عن أبي علي سويد بن مُقَرِّن رضي الله عنه قال: لقد رَأَيْتُنِي سابع سبعة من بني مُقَرِّن ما لنا خادم إلا واحدة لطمها أصغرنا فأمرنا رسول الله صلى الله عليه وسلم أن نعتقها وفي رواية: «سابع إخوة لي».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: «من أعتق شِقْصَاً مِنْ مملوك، فعليهِ خَلاصُهُ كله في ماله، فإِنْ لم يكن له مال؛ قُوِّمَ المملوك قِيمَةَ عَدْلٍ، ثمَّ اُسْتُسْعِيَ العبد، غير مَشْقُوقٍ عليه».","متفق عليه","صحيح"],["عن عَبْدُ الله بن عمر رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «مَن أَعْتَقَ شِرْكًا له في عَبْدٍ، فكان له مالٌ يَبْلُغُ ثَمَنَ العَبْدِ: قُوِّمَ عليه قِيمَةَ عَدْلٍ ، فأعطى شُرَكَاءَهُ حِصَصَهُمْ، وعَتَقَ عليه العَبْدُ ، وإلا فقد عَتَقَ منه ما عَتَقَ».","متفق عليه","صحيح"],["عن أم المؤمنين ميمونة بنت الحارث رضي الله عنها : أنها أعتقت وَليدَةً ولم تستأذن النبي صلى الله عليه وسلم فلما كان يَومُها الذي يَدورُ عليها فيه، قالت: أشَعَرْتَ يا رسول الله، أني أعتقت وليدتي؟ قال: «أو فعلت؟» قالت: نعم. قال: «أما إنك لو أعطيتها أخوالك كان أعظم لأجرك».","متفق عليه","صحيح"]]],["الأيمان والنذور",[["عن عمرو بن شعيب، عن أبيه، عن جده قال: قال رسول الله صلى الله عليه وسلم : «لا نَذْرَ لابن آدم فيما لا يملك، ولا عِتْقَ له فيما لا يملك، ولا طلاق له فيما لا يمْلِك».","رواه أبو داود والترمذي وابن ماجه وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لأَنْ يَلَجَّ أحدُكم في يَمِينِه في أهْلِه آثَمُ له عند الله تعالى من أن يُعْطِي كَفَّارَتَهُ التي فرض الله عليه».","متفق عليه","صحيح"],["عن بريدة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من حَلف فقال: إنِّي بَرِيءٌ من الإسلام، فإن كان كاذبا، فهو كما قال، وإن كان صَادقا، فَلَنْ يَرْجِعَ إلى الإسلام سَالِمًا».","رواه أبو داود وأحمد والنسائي في الكبرى","صحيح"],["عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: ««رأى عيسى ابنُ مريم رجلًا يَسْرِق، فقال له: أسَرَقتَ؟ قال: كلا والله الذي لا إله إلا هو، فقال عيسى: آمنتُ بالله، وكذَّبتُ عيني».","متفق عليه","صحيح"],["عن عَبْدُ الله بْنُ عَبَّاسٍ رضي الله عنه قال: «استَفْتَى سعد بن عُبَادَةَ رسول الله في نَذْرٍ كان على أمِّه، تُوُفِّيَتْ قبل أَنْ تقضيَهُ، قال رسول الله صلى الله عليه وسلم : فاقْضِهِ عنها».","متفق عليه","صحيح"]]]]],["الفرائض والميراث",1,[["شروط الإرث",[["عن جابر رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «إذا اسْتَهَلَّ المَوْلُودُ وَرِثَ».","رواه أبو داود والترمذي وابن ماجه","صحيح"]]],["موانع الإرث",[["وعن أسامة بن زيد رضي الله عنهما أن النبي صلى الله عليه وسلم قال: «لا يرثُ المسلمُ الكافرَ، ولا يَرِثُ الكافرُ المسلمَ».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لا يَقْتَسِمُ وَرَثَتي دينارًا ولا درهمًا، ما تَرَكْتُ بَعْدَ نَفَقَة نسائي، ومئونَة عامِلي فهو صَدَقة».","متفق عليه","صحيح"],["عن أسامة بن زيد- رضي الله عنه- مرفوعاً: «قلت ُيا رسول الله، أتنزل غدا في دارك بمكة؟ قال: وهل ترك لنا عقيل من رِبَاعٍ؟ ثم قال: لا يَرِثُ الكافر المسلم، ولا المسلم الكافر","متفق عليه","صحيح"],["عن عبد الله بن عمرو رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «لا يَتَوَارَثُ أهل مِلَّتَيْنِ شتّى».","رواه أبو داود وابن ماجه وأحمد","حسن"]]],["ميراث ذوي الأرحام",[["عن المقدام، قال: قال رسول الله صلى الله عليه وسلم : «من تَرَكَ كَلًّا فَإِليَّ» ورُبَّمَا قال: «إلى الله وإلى رسوله، ومن تَرَكَ مَالًا فِلَوَرَثَتِهِ، وأنا وَارِثُ من لا وارثَ له، أَعْقِلُ له وأَرِثُهُ، والخَالُ وَارِثُ مَنْ لا وَارِثَ له، يَعْقِلُ عنه ويَرِثُهُ».","رواه أبو داود وابن ماجه وأحمد","حسن"]]],["ميراث الحمل",[["عن جابر رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «إذا اسْتَهَلَّ المَوْلُودُ وَرِثَ».","رواه أبو داود والترمذي وابن ماجه","صحيح"]]]]],["الأطعمة والأشربة",1,[["أحكام الأطعمة والأشربة",[["عن جابر رضي الله عنه : أَنَّ النَّبِيَّ صلى الله عليه وسلم سَأَلَ أَهْلَهُ الأُدُمَ، فقالوا: مَا عِنْدَنَا إِلَّا خَلٌّ، فَدَعَا بِهِ، فَجَعَلَ يَأْكُلُ، وَيَقُولُ: «نِعْمَ الأُدُمُ الخَلَّ، نِعْمَ الأُدُمُ الخَلَّ».","رواه مسلم","صحيح"],["عن ابن عباس، قال: «كان رسول الله صلى الله عليه وسلم يُنْبَذُ له الزَّبِيبُ في السِّقَاءِ، فَيَشْرَبُهُ يَوْمَهُ وَالْغَدَ وَبَعْدَ الْغَدِ، فإذا كان مَسَاءُ الثَّالِثَةِ شَرِبَهُ وَسَقَاهُ، فإن فَضَلَ شيء أَهْرَاقَهُ».","رواه مسلم","صحيح"],["عن عبد الله بن عباسٍ رضي الله عنهما قال: بلغَ عمرَ رضي الله عنه أن فلانًا باعَ خمرًا. فقال: قاتلَ الله فلانًا! ألم يعلم أن رسولَ الله صلى الله عليه وسلم قال: \"قاتلَ الله اليهودَ، حُرِّمت عليهم الشُّحومُ، فجَمَلُوها، فباعُوها\".","متفق عليه","صحيح"]]],["ما يحل ويحرم من الحيوانات والطيور",[["عن أم شريك رضي الله عنها : أن رسول الله صلى الله عليه وسلم أمرها بِقَتْلِ الأَوْزَاغِ وقال: «كان يَنْفُخُ على إبراهيم».","متفق عليه","صحيح"],["عن عَبْد اللهِ بن أبي أوفى رضي الله عنهما قال: «غَزَوْنَا مَعَ رَسُولِ الله صلى الله عليه وسلم سَبْعَ غَزَوَاتٍ، نَأْكُلُ الْجَرَادَ».","متفق عليه","صحيح"],["عن ابن عمر رضي الله عنهما ، قال: \"نهى رسول الله صلى الله عليه وسلم عن الجَلَّالَة في الإبِل: أنْ يُرْكَبَ عليها، أو يُشْرَب مِن أَلْبَانِها\".","رواه أبو داود والترمذي وابن ماجه","صحيح"],["عَنِ ابْنِ عَبَّاسٍ رَضيَ اللهُ عنهُما أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم: نَهَى عَنْ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ، وَعَنْ كُلِّ ذِي مِخْلَبٍ مِنَ الطَّيْرِ.","رواه مسلم","صحيح"],["عن أَسْمَاء بِنْت أَبِي بَكْرٍ رضي الله عنهما قالت: «نَحَرْنَا عَلَى عَهْدِ رَسُولِ الله صلى الله عليه وسلم فَرَسًا فَأَكَلْنَاهُ». وَفِي رِوَايَةٍ «وَنَحْنُ بِالْمَدِينَةِ».","متفق عليه","صحيح"],["عن عبد الله بن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «أُحِلَّتْ لكم مَيْتَتَانِ وَدَمَانِ، فأما الميتتان: فَالْجَرَادُ والْحُوتُ، وأما الدَّمَانِ: فالكبد والطحال».","رواه ابن ماجه وأحمد","صحيح"],["عن أبي واقد الليثي رضي الله عنه قال: قَدِم النبي صلى الله عليه وسلم المدينة وهم يَجُبُّون أَسْنِمة الإبل، ويَقْطعون أَلْيَات الغنم، فقال: «ما قُطِع من البَهِيمَة وهي حيَّة فهي ميْتَة».","رواه أبو داود والترمذي والدارمي وأحمد","صحيح"],["عن عائشة رضي الله عنها : أنّ قومًا قالوا: يا رسول الله إنّ قومًا يأتوننا باللحم لا نَدري أَذَكروا اسمَ الله عليه أم لا، فقال رسول الله صلى الله عليه وسلم : «سَمُّوا الله عليه وكُلُوه».","رواه البخاري","صحيح"],["عن ابن عباس رضي الله عنهما قال: وجد النبي صلى الله عليه وسلم شاةً ميتةً أُعْطِيَتْها مولاة لميمونة من الصدقة، فقال النبي صلى الله عليه وسلم: «هلَّا انتفعتم بجلدها؟» قالوا: إنها ميتة، قال: «إنما حَرُمَ أكلُها».","متفق عليه","صحيح"]]],["التذكية",[["عن كعب بن مالك، أنّ امرأةً ذَبحَت شاةً بِحَجَر، «فسُئل النبيُّ صلى الله عليه وسلم عن ذلك فأمَرَ بِأكلها».","رواه البخاري","صحيح"],["عن أبي سعيد قال: سألْنا رسول الله صلى الله عليه وسلم عن الجَنِينِ فقال: «كُلُوهُ إنْ شِئْتُم، فإنَّ ذَكاتَه، ذَكاةُ أُمِّهِ».","رواه أبو داود والترمذي وابن ماجه وأحمد","صحيح"],["عن أَسْمَاء بِنْت أَبِي بَكْرٍ رضي الله عنهما قالت: «نَحَرْنَا عَلَى عَهْدِ رَسُولِ الله صلى الله عليه وسلم فَرَسًا فَأَكَلْنَاهُ». وَفِي رِوَايَةٍ «وَنَحْنُ بِالْمَدِينَةِ».","متفق عليه","صحيح"]]],["الصيد",[["عن أبي ثعلبة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إذا رَمَيْتَ بِسَهْمِكَ، فغابَ عنْك، فَأَدْرَكْتَهُ فَكُلْهُ، ما لَمْ يُنْتِنْ».","رواه مسلم","صحيح"],["عن ابن أبي عَمَّار قال: قلت لجابر: الضَّبْع صَيْدٌ هي؟ قال: «نعم»، قال: قلتُ: آكُلُها؟ قال: «نعم»، قال: قلتُ له: أَقَالَهُ رسول الله صلى الله عليه وسلم ؟ قال: «نعم».","رواه أبو داود والترمذي والنسائي وابن ماجه وأحمد والدارمي","صحيح"],["عن أنس رضي الله عنه قال: «أَنْفَجْنَا أَرْنَباً بِمَرِّ الظَّهْرَانِ، فَسَعَى الْقَوْمُ فَلَغَبُوا، وَأَدْرَكْتُهَا فَأَخَذْتُهَا، فَأَتَيْتُ بِهَا أَبَا طَلْحَةَ، فَذَبَحَهَا وَبَعَثَ إلَى رَسُولِ الله صلى الله عليه وسلم بِوَرِكِهَا وَفَخِذَيْهَا فَقَبِلَهُ».","متفق عليه","صحيح"],["عن أبي ثَعْلبة الخُشني رضي الله عنه قال: «أَتَيْتُ رسول الله صلى الله عليه وسلم فقلت: يا رسول الله، إنا بأرض قوم أهل كتاب، أَفَنَأْكُلُ في آنِيَتِهِم؟ وفي أرض صيد، أَصِيدُ بِقَوْسِي وبِكَلْبِي الذي ليس بِمُعَلَّمٍ، وبِكَلْبِي المُعَلَّمِ، فما يَصلح لي؟ قال: أمَّا مَا ذَكَرْتَ- يعني من آنية أهل الكتاب-: فإِنْ وجدْتُمْ غيرها فلا تأكلوا فيها، وإِنْ لم تَجِدُوا فاغسِلوهَا، وكلوا فِيهَا، وما صدتَ بِقَوْسِكَ، فذَكَرْتَ اسمَ الله عَلَيه فَكُلْ، وما صِدْتَ بِكَلْبِكَ المُعَلَّمِ، فَذَكَرْتَ اسْمَ الله عليه فَكُلْ، وما صِدْتَ بِكَلْبِكَ غيرِ المُعَلَّمِ فَأَدْرَكْتَ ذَكَاتَهُ فَكُلْ».","متفق عليه","صحيح"],["عن عديّ بن حاتم رضي الله عنه قال: قلتُ: يا رسول الله، إني أُرسلُ الكلاب المعلَّمة، فيُمسِكنَ عليّ، وأذكرُ اسم الله؟ فقال: \"إذا أرسلتَ كلبَكَ المعلَّمَ، وذكرتَ اسمَ الله، فكُلْ ما أمسكَ عليك\"، قلت: وإن قتلنَ؟ قال: \"وإن قَتلْنَ، ما لم يَشْرَكْها كلبٌ ليس منها\"، قلتُ له: فإني أرمي بالمِعْراض الصيدَ فأُصُيبُ؟ فقال: \"إذا رميتَ بالمعراضِ فخزَقَ فكلْهُ، وإن أصابَه بعَرْضٍ فلا تأكلْهُ\". وحديث الشعبي، عن عدي نحوه، وفيه: \"إلا أن يأكل الكلب، فإن أكل فلا تأكل؛ فإني أخاف أن يكون إنما أمسك على نفسه، وإن خالطها كلاب من غيرها فلا تأكل؛ فإنما سميت على كلبك، ولم تسم على غيره\". وفيه: \"إذا أرسلت كلبك المكلب فاذكر اسم الله، فإن أمسك عليك فأدركته حيا فاذبحه، وإن أدركته قد قتل ولم يأكل منه فكله، فإنَّ أخْذَ الكلبِ ذَكَاته\". وفيه أيضا: \"إذا رميت بسهمك فاذكر اسم الله\". وفيه: \"فإن غاب عنك يوما أو يومين -وفي رواية: اليومين والثلاثة- فلم تجد فيه إلا أثر سهمك، فكل إن شئت، فإن وجدته غريقا في الماء فلا تأكل؛ فإنك لا تدري الماء قتله، أو سهمك؟","متفق عليه","صحيح"]]],["الأشربة المحرمة",[["عن أنس بن مالك رضي الله عنه قال: سُئل رسول الله صلى الله عليه وسلم عن الخمر تُتَّخَذُ خَلًّا؟ قال: «لا».","رواه مسلم","صحيح"],["عن وائل الحضرمي أن طارق بن سويد الجعفي سأل النبي صلى الله عليه وسلم عن الخمر، فَنَهَاهُ -أو كره- أن يَصْنَعَهَا، فقال: إنما أَصْنَعُهَا لِلدَّوَاءِ، فقال: «إنه ليس بِدَوَاءٍ، ولكنه دَاءٌ».","رواه مسلم","صحيح"],["عن ابن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: «كل مُسْكِرٍ خَمْرٌ، وكل مُسْكِرٍ حرام، ومن شرِب الخمر في الدنيا فمات وهو يُدْمِنُهَا لَمْ يَتُبْ، لَمْ يَشْرَبْهَا في الآخرة».","رواه مسلم وأخرج البخاري الجملة الأخيرة منه","صحيح"],["عن عبد الله بن عباسٍ رضي الله عنهما قال: بلغَ عمرَ رضي الله عنه أن فلانًا باعَ خمرًا. فقال: قاتلَ الله فلانًا! ألم يعلم أن رسولَ الله صلى الله عليه وسلم قال: \"قاتلَ الله اليهودَ، حُرِّمت عليهم الشُّحومُ، فجَمَلُوها، فباعُوها\".","متفق عليه","صحيح"]]]]],["الطب والتداوي",1,[["الطب النبوي",[["عن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم قال: «الحُمَّى من فَيْحِ جهنم فأبردوها بالماء».","متفق عليه","صحيح"],["عن أبي سعيد الخدري رضي الله عنه أنَّ رجلًا أتى النبيَّ صلى الله عليه وسلم فقال: أخي يَشْتكي بطنَه، فقال: «اسْقِه عَسَلًا» ثم أتى الثانيةَ، فقال: «اسْقِه عَسَلًا» ثم أتاه الثالثةَ فقال: «اسْقِه عَسَلًا» ثم أتاه فقال: قد فعلتُ؟ فقال: «صدق اللهُ، وكذب بطنُ أخيك، اسْقِه عَسَلًا» فسقاه فبرأ.","متفق عليه","صحيح"],["عن قيس بن أبي حازم، قال: دخلنا على خباب بن الأرت - رضي الله عنه - نعودُه وقد اكْتَوى سبعَ كَيّات، فقال: إن أصحابنا الذين سَلفوا مضوا، ولم تَنقصهم الدنيا، وإنّا أصبنا ما لا نجد له مَوضعاً إلا التراب ولولا أن النبي - صلى الله عليه وسلم - نهانا أن ندعوَ بالموت لدعوتُ به. ثم أتيناه مرة أخرى وهو يبني حائطاً له، فقال: إن المسلم ليُؤجَر في كل شيء يُنفقه إلا في شيء يجعلُه في هذا التراب.","متفق عليه، واللفظ للبخاري. وروى مسلم أوله مختصراً","صحيح"]]],["أحكام التداوي",[["عن رافع بن خديج رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «ثمن الكلب خبيث، ومهر البغي خبيث، وكسب الحجام خبيث».","رواه مسلم","صحيح"],["عن وائل الحضرمي أن طارق بن سويد الجعفي سأل النبي صلى الله عليه وسلم عن الخمر، فَنَهَاهُ -أو كره- أن يَصْنَعَهَا، فقال: إنما أَصْنَعُهَا لِلدَّوَاءِ، فقال: «إنه ليس بِدَوَاءٍ، ولكنه دَاءٌ».","رواه مسلم","صحيح"],["عن أنس بن مالك رضي الله عنه أَنَّ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ، وَالزُّبَيْرَ بْنَ الْعَوَّامِ رضي الله عنهم ، شَكَوَا الْقَمْلَ إلَى رَسُولِ الله صلى الله عليه وسلم فِي غَزَاةٍ لَهُمَا فَرَخَّصَ لَهُمَا فِي قَمِيصِ الْحَرِيرِ وَرَأَيْته عَلَيْهِمَا.","متفق عليه","صحيح"]]],["الرقية الشرعية",[["عن عبد الله بن مسعود رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إنَّ الرُّقَى والتَمائِمَ والتِّوَلَةَ شِرْكٌ».","رواه أبو داود وابن ماجه وأحمد","صحيح"],["عن أبي سعيد الخدري رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم يَتَعَوَّذُ مِنَ الجَانِّ، وعَيْنِ الإنسان، حتى نَزَلَتْ المُعَوِّذتان، فلمَّا نَزَلَتا، أخذ بهما وتركَ ما سواهما.","رواه الترمذي والنسائي وابن ماجه","صحيح"],["عن أنس رضي الله عنه أنه قَالَ لِثابِتٍ رحمه اللهُ: ألاَ أرْقِيكَ بِرُقْيَةِ رسولِ اللهِ صلى الله عليه وسلم ؟ قال: بلى، قال: «اللَّهُمَّ رَبَّ النَّاسِ، مُذْهِبَ البَأسِ، اشْفِ أنْتَ الشَّافِي، لاَ شَافِيَ إِلاَّ أنْتَ، شِفَاءً لاَ يُغَادِرُ سَقماً».","رواه البخاري","صحيح"],["عن عائشة رضي الله عنها : أنَّ النَّبيَّ صلى الله عليه وسلم كَانَ إِذَا اشْتَكى الإنْسَانُ الشَّيْءَ مِنْهُ، أَوْ كَانَتْ بِهِ قَرْحَةٌ أَوْ جُرْح، قالَ النبيُّ صلى الله عليه وسلم بأُصبعِهِ هكذا - ووضع سفيان بن عيينة الراوي سبابته بالأرض ثم رفعها- وقالَ: «بِسمِ اللهِ، تُرْبَةُ أرْضِنَا، بِرِيقَةِ بَعْضِنَا، يُشْفَى بِهِ سَقِيمُنَا، بإذْنِ رَبِّنَا».","متفق عليه","صحيح"]]]]],["الأخلاق",0,[["الأخلاق الحميدة",[["عن أنس بن مالك رضي الله عنه عن النبي صلى الله عليه وسلم قال: «يَسِّرُوا وَلَا تُعَسِّرُوا، وَبَشِّرُوا وَلَا تُنَفِّرُوا».","متفق عليه","صحيح"],["عن جرير بن عبد الله رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «مَنْ لَا يَرْحَمِ النَّاسَ لَا يَرْحَمْهُ اللهُ عَزَّ وَجَلَّ».","متفق عليه","صحيح"],["عن المِقدام بن معدي كرب رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إِذَا أَحَبَّ الرَّجُلُ أَخَاهُ فَلْيُخْبِرْهُ أَنَّهُ يُحِبُّهُ».","رواه أبو داود والترمذي والنسائي في الكبرى وأحمد","صحيح"],["عن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «رَحِمَ اللهُ رَجُلًا سَمْحًا إِذَا بَاعَ، وَإِذَا اشْتَرَى، وَإِذَا اقْتَضَى».","رواه البخاري","صحيح"],["عن سعد بن أبي وقاص رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إِنَّ اللهَ يُحِبُّ الْعَبْدَ التَّقِيَّ الْغَنِيَّ الْخَفِيَّ».","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها قالت: سمعت رسول الله صلى الله عليه وسلم يقول: «إنَّ المُؤْمِنَ ليُدرِكُ بِحُسْنِ خُلُقِهِ دَرَجَةَ الصَّائِمِ القَائِمِ».","رواه أبو داود وأحمد","صحيح بشواهده"],["عن أبي الدرداء رضي الله عنه عن النبي صلى الله عليه وسلم قال: «مَنْ رَدَّ عَنْ عِرْضِ أَخِيهِ رَدَّ اللهُ عَنْ وَجْهِهِ النَّارَ يَوْمَ الْقِيَامَةِ».","رواه الترمذي وأحمد","صحيح"],["عن أبي ذر رضي الله عنه قال: قال لي النبي صلى الله عليه وسلم: «لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا، وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلْقٍ».","رواه مسلم","صحيح"],["عن عبد الله بن عمرو رضي الله عنهما أن النبي صلى الله عليه وسلم قال: «الرَّاحِمُونَ يَرْحَمُهمُ الرَّحمنُ، ارحَمُوا أهلَ الأرضِ يَرْحْمْكُم مَن في السّماء».","رواه أبو داود والترمذي وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ، إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ».","متفق عليه","صحيح"]]],["الأخلاق الذميمة",[["عن حذيفة رضي الله عنه قال: سمعت النبي صلى الله عليه وسلم يقول: «لَا يَدْخُلُ الْجَنَّةَ قَتَّاتٌ».","متفق عليه","صحيح"],["عن عائشة رضي الله عنها عن النبي صلى الله عليه وسلم قال: «إِنَّ أَبْغَضَ الرِّجَالِ إِلَى اللهِ الْأَلَدُّ الْخَصِمُ».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه : أن رسول الله صلى الله عليه وسلم قال: «المُتَسَابَّانِ ما قالا فَعَلى البَادِي منهما حتى يَعْتَدِي المَظْلُوم».","رواه مسلم.\nملحوظة: لفظ مسلم: «المستبان ما قالا فعلى البادئ، ما لم يعتد المظلوم»، والمصنف ذكره بالمعنى","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ».","متفق عليه","صحيح"],["عن عبد الله بن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «من تَسَمَّع حديث قوم وهم له كارهون؛ صُبَّ في أذنيه الآنُكُ يوم القيامة».","رواه البخاري.\nملحوظة:\nلفظ البخاري: \"من استمع إلى حديث قوم\"، و\"من تَسَمَّعَ\" رواه الخرائطي في مساويء الأخلاق (ح720)","صحيح"],["عن معاوية رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إنك إن اتَّبَعْتَ عَوْرَاتِ المسلمين أفْسَدْتَهُم، أو كِدْتَ أن تُفْسِدَهُم».","رواه أبو داود","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا يَحِلُّ لمسلم أن يَهْجُرَ أخَاه فوق ثَلَاث، فمن هَجَر فوق ثَلَاث فمات دخل النَّار».","رواه أبو داود وأحمد","صحيح"]]]]],["الآداب الشرعية",0,[["آداب العالم والمتعلم",[["عن عوف بن مالك الأشجعي قال: سمعت رسول الله صلى الله عليه وسلم يقول: \"لا يقص إلا أمير أو مأمور أو مختال\".","رواه أبو داود","صحيح"],["عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: «مَنْ سُئِلَ عن عِلْمٍ فَكَتَمَهُ، أُلْجِمَ يوم القيامةِ بِلِجَامٍ مِنْ نارٍ».","رواه أبو داود والترمذي وابن ماجه وأحمد","صحيح"],["عن زيد بن ثابت قال: سمعت رسول الله صلى الله عليه وسلم يقول: \"نضر الله امرأ سمع منا حديثا فحفظه حتى يبلغه، فرب حامل فقه إلى من هو أفقه منه، ورب حامل فقه ليس بفقيه\".","رواه أبو داود والترمذي وابن ماجه وأحمد","صحيح"],["عن سمرة بن جندب رضي الله عنه قال: لقد كنت على عَهْدِ رسولِ الله صلى الله عليه وسلم غُلاما، فكنت أحفظ عنه، فما يمنعني من القول إلا أن هاهنا رِجَالًا هم أَسَنُّ مِنِّي.","رواه مسلم","صحيح"],["عن حذيفة قال: قام فينا رسول الله صلى الله عليه وسلم مقامًا، ما ترك شيئًا يكون في مقامه ذلك إلى قيام الساعة، إلا حدث به، حفظه من حفظه ونسيه من نسيه، قد علمه أصحابي هؤلاء، وإنه ليكون منه الشيء قد نسيته فأراه فأذكره، كما يذكر الرجل وجه الرجل إذا غاب عنه، ثم إذا رآه عرفه.","رواه مسلم","صحيح"],["عن أبي زيد عمرو بن أخطب الأنصاري رضي الله عنه : صلى بنا رسول الله صلى الله عليه وسلم الفجر، وصعد المنبر، فخطبنا حتى حضرت الظهر، فنزل فصلى، ثم صعد المنبر فخطبنا حتى حضرت العصر، ثم نزل فصلى، ثم صعد المنبر فخطبنا حتى غربت الشمس، فأخبرنا بما كان وبما هو كائن، فأَعْلَمُنَا أَحْفَظُنَا.","رواه مسلم","صحيح"],["عن أبي موسى، قال: سئل النبي صلى الله عليه وسلم عن أشياء كرهها، فلما أكثر عليه غضب، ثم قال للناس: «سلوني عما شئتم» قال رجل: من أبي؟ قال: «أبوك حذافة» فقام آخر فقال: من أبي يا رسول الله؟ فقال: «أبوك سالم مولى شيبة» فلما رأى عمر ما في وجهه قال: يا رسول الله، إنا نتوب إلى الله عز وجل.","متفق عليه","صحيح"],["عن مسروق، قال: دخَلْنَا على عبد الله بن مسعود رضي الله عنه فقال: يا أيها الناس، من عَلِم شيئا فَلْيَقُلْ به، ومن لم يَعْلَم، فَلْيَقُلْ: الله أعلم، فإن من العلم أن يقول لما لا يَعْلَم: الله أعلم. قال الله تعالى لنبيه صلى الله عليه وسلم : (قل ما أسألكم عليه من أجر وما أنا من المتكلفين).","رواه البخاري","صحيح"],["عن عبد الله بن عمرو بن العاص رضي الله عنهما ، قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إنَّ اللهَ لاَ يَقْبِضُ العِلْمَ انْتِزَاعاً يَنْتَزعهُ مِنَ النَّاسِ، وَلكِنْ يَقْبِضُ العِلْمَ بِقَبْضِ العُلَمَاءِ، حَتَّى إِذَا لَمْ يُبْقِ عَالِماً، اتَّخَذَ النَّاسُ رُؤُوساً جُهَّالاً، فَسُئِلُوا فَأفْتوا بِغَيْرِ عِلْمٍ، فَضَلُّوا وَأضَلُّوا».","متفق عليه","صحيح"],["عن عبد الله بن عمر أن رسول الله صلى الله عليه وسلم قال: «إن من الشجر شجرة لا يسقط ورقها، وهي مثل المسلم، حدثوني ما هي؟» فوقع الناس في شجر البادية، ووقع في نفسي أنها النخلة، قال عبد الله: فاستحييت، فقالوا: يا رسول الله، أخبرنا بها؟ فقال رسول الله صلى الله عليه وسلم: «هي النخلة» قال عبد الله: فحدثت أبي بما وقع في نفسي، فقال: «لأن تكون قلتها أحب إلي من أن يكون لي كذا وكذا».","متفق عليه","صحيح"]]],["آداب السلام والاستئذان",[["عن عائشة أن النبي صلى الله عليه وسلم كان إذا دخل بيته بدأ بالسواك.","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها أن رجلًا استأذن على النبي صلى الله عليه وسلم فقال: «ائْذَنُوا له، بئس أخو العَشِيرَةِ؟».","متفق عليه","صحيح"],["عن أنسٍ رضي الله عنه : أنّهُ مَرَّ على صِبْيَانِ، فَسَلَّمَ عليهم، وقالَ: كانَ النبيُّ صلى الله عليه وسلم يَفعلُهُ.","متفق عليه","صحيح"],["عن أبي الخطاب قتادة، قال: قُلْتُ لأَنَسٍ: أكَانَتِ المصَافَحَةُ في أصْحَابِ رسولِ الله صلى الله عليه وسلم ؟، قَالَ: نَعَم.","رواه البخاري","صحيح"],["عن أبي جُرَيٍّ الْهُجَيْمِيِّ رضي الله عنه قال: أتيت رسول الله صلى الله عليه وسلم فقلت: عليك السلام يا رسول الله. قال: «لا تَقُلْ عليك السلام؛ فإن عليك السلام تحيَّة المَوْتَى».","رواه أبو داود والترمذي والنسائي في الكبرى","صحيح"],["عن عبد الله بن مسعود رضي الله عنه قال: كنا نُسلِّم على النبي صلى الله عليه وسلم وهو في الصلاة فيرُدُّ علينا، فلما رجعنا من عند النجاشي سلمنا عليه فلم يرد علينا، وقال: «إن في الصلاة شغلًا».","متفق عليه","صحيح"]]],["آداب الكلام والصمت",[["عن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان يحدِّث حديثًا لو عدَّهُ العادُّ لأحصاه.","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لا ينبغي لصِدِّيق أن يكون لعَّانًا».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إذا قال الرَّجُل: هَلَكَ الناس، فهو أَهْلَكُهُم».","رواه مسلم","صحيح"],["عن المِقدام بن معدي كرب رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إِذَا أَحَبَّ الرَّجُلُ أَخَاهُ فَلْيُخْبِرْهُ أَنَّهُ يُحِبُّهُ».","رواه أبو داود والترمذي والنسائي في الكبرى وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه : أن رسول الله صلى الله عليه وسلم قال: «المُتَسَابَّانِ ما قالا فَعَلى البَادِي منهما حتى يَعْتَدِي المَظْلُوم».","رواه مسلم.\nملحوظة: لفظ مسلم: «المستبان ما قالا فعلى البادئ، ما لم يعتد المظلوم»، والمصنف ذكره بالمعنى","صحيح"],["عن بُريدة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا تقولوا للمُنَافق سَيِّدٌ، فإنه إن يَكُ سَيِّدًا فقد أسْخَطْتُمْ ربكم عز وجل ».","رواه أبو داود والنسائي في الكبرى وأحمد","صحيح"],["عن عروة قال: سمعتني عائشة وأنا أتكلم بعد العشاء الآخرة، فقالت: يا عُرَي، ألا تُريح كاتبك، فإن رسول الله صلى الله عليه وسلم لم يكن ينام قبلها ولا يتحدث بعدها.","رواه ابن حبان","صحيح"],["عن أبي موسى الأشعري - رضي الله عنه- قال: سمع النبي صلى الله عليه وسلم رجلا يُثْنِي على رجل ويُطْرِيهِ في المِدْحَةِ، فقال: «أَهْلَكْتُمْ -أو قَطَعْتُمْ- ظَهْرَ الرجل».","متفق عليه","صحيح"]]],["آداب الخلاف",[["عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إذا قاتل أحدكم فَلْيَجْتَنِبِ الوجه».","متفق عليه","صحيح"],["عن أبي هريرة، قال: قال رسول الله صلى الله عليه وسلم : «إذا ضَرَبَ أَحَدُكُمْ أخاه فَلْيَجْتَنِب الوجْهَ».","متفق عليه","صحيح"],["عن أبي أمامة، قال: قال رسول الله صلى الله عليه وسلم: (ما ضل قوم بعد هدى كانوا عليه إلا أوتوا الجدل)، ثم تلا رسول الله صلى الله عليه وسلم هذه الآية: {ما ضربوه لك إلا جدلا بل هم قوم خصمون}.","رواه الترمذي وابن ماجه","حسن"]]],["آداب المناظرة",[["عن عمران بن حصين، قال: قال رسول الله صلى الله عليه وسلم: «أخوف ما أخاف عليكم جدال المنافق عليم اللسان».","رواه ابن حبان","صحيح"],["عن عبد الله بن عمرو رضي الله عنهما أن النبي صلى الله عليه وسلم قال: «لا تُجادِلوا في القرآن؛ فإنَّ جِدالًا فيه كُفرٌ».","رواه أبو داود الطيالسي","صحيح"],["عن حذيفة قال: جاء العاقب والسَّيِّد، صاحبا نجران، إلى رسول الله صلى الله عليه وسلم يريدان أن يلاعناه، قال: فقال أحدهما لصاحبه: لا تفعل، فوالله لئن كان نبيًّا فلاعَنَّا لا نفلح نحن، ولا عَقِبُنا مِن بعدنا، قالا: إنا نعطيك ما سألتنا، وابعث معنا رجلًا أمينًا، ولا تبعث معنا إلا أمينًا. فقال «لأبعثنَّ معكم رجلًا أمينًا حقَّ أمينٍ»، فاستشرف له أصحاب رسول الله صلى الله عليه وسلم فقال: «قم يا أبا عبيدة بن الجراح» فلما قام، قال رسول الله صلى الله عليه وسلم: «هذا أمين هذه الأُمَّة».","متفق عليه","صحيح"],["عن أبي أمامة، قال: قال رسول الله صلى الله عليه وسلم: (ما ضل قوم بعد هدى كانوا عليه إلا أوتوا الجدل)، ثم تلا رسول الله صلى الله عليه وسلم هذه الآية: {ما ضربوه لك إلا جدلا بل هم قوم خصمون}.","رواه الترمذي وابن ماجه","حسن"]]],["آداب الأكل والشرب",[["عن ابن عباس أن رسول الله صلى الله عليه وسلم شرب لبنًا فمضمض، وقال: «إن له دسمًا».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا يشربَنَّ أحدٌ منكم قائما».","رواه مسلم","صحيح"],["عن أبي سعيدٍ الخُدْرِيِّ رضي الله عنه قال: نهى رسولُ اللهِ صلى الله عليه وسلم عن اخْتِنَاثِ الأَسْقِيَةِ.","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: ما عاب رسول الله صلى الله عليه وسلم طعاما قط، إن اشتهاه أكله، وإن كرهه تركه.","متفق عليه","صحيح"],["عن أبي جُحَيْفَة رضي الله عنه قال: كنتُ عند النبي صلى الله عليه وسلم فقال لرجل عنده: «لا آكُلُ وأنا مُتَّكِئ».","رواه البخاري","صحيح"],["عن ابن عباس رضي الله عنهما قال: «نهى رسول الله صلى الله عليه وسلم أنْ يُتَنَفَّسَ في الإناء، أو يُنْفَخَ فيه».","رواه أبو داود والترمذي وابن ماجه وأحمد والدارمي","صحيح"],["عن ابن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «إذا دُعِيَ أحدكم إلى الوَلِيمَة فَلْيَأْتِهَا».","متفق عليه","صحيح"],["عن كعب بن مالك رضي الله عنه قال: رأيتُ رسولَ اللهِ صلى الله عليه وسلم يأكلُ بثلاثِ أَصَابِعَ، فإذا فَرَغَ لَعِقَهَا.","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها: «أَنَّ رسول الله صلى الله عليه وسلم سُئِل عن الْبِتْعِ؟ فقال: كل شَرَابٍ أَسْكَر فهو حَرَامٌ».","متفق عليه","صحيح"],["عن ابنِ عُمَرَ رضي الله عنهما ، قال: كُنَّا على عَهْدِ رسولِ اللهِ صلى الله عليه وسلم نَأْكُلُ ونحنُ نَمْشِي، ونَشْرَبُ ونحنُ قِيَامٌ.","رواه الترمذي وابن ماجه وأحمد","صحيح"],["عن أبي هريرة وعبد الله بن عباس رضي الله عنهم قالا: نَهَى رسولُ اللهِ صلى الله عليه وسلم أَنْ يُشْرَبَ مِنْ فِي السِّقاءِ أو القِرْبَةِ.","حديث أبي هريرة رضي الله عنه: رواه البخاري\nحديث ابن عباس رضي الله عنهما:متفق عليه","صحيح"]]],["آداب الطريق والسوق",[["عن أبي سعيد الخدري رضي الله عنه مرفوعًا: \"إياكم والجلوسَ على الطُّرُقَاتِ\". قالوا: يا رسول الله، ما لنا بُدٌّ من مجالسنا، نتحدث فيها. قال: \"فأما إذا أَبَيْتُمْ فأعطوا الطريق حَقَّهُ\". قالوا: وما حَقُّهُ؟ قال: \"غَضُّ البصر، وكَفُّ الأذى، ورد السلام، والأمر بالمعروف، والنهي عن المنكر\".","متفق عليه","صحيح"],["عن أبي طلحة زيد بن سهل رضي الله عنه قال: كُنَّا قعودا بالأفْنِيَةِ نتحدَّث فيها فجاء رسول الله صلى الله عليه وسلم فقام علينا، فقال: «ما لكم ولمجالس الصُّعُدَاتِ؟ اجتنبوا مجالس الصُّعُدَاتِ». فقُلنا: إنما قَعَدْنَا لغير ما بأس، قَعَدْنَا نتذَاكَر، ونتحدث. قال: «إما لا فأدُّوا حقَها: غَضُّ البَصَر، وردُّ السلام، وحُسْن الكلام».","رواه مسلم","صحيح"]]],["آداب وأحكام السفر",[["عن جابر بن عبد الله رضي الله عنهما: أن رسول الله صلى الله عليه وسلم لما قدم المدينة نحر جزورًا أو بقرةً.","رواه البخاري","صحيح"],["عن عبد الله بن عمر رضي الله عنهما مرفوعاً: نهى رسول الله صلى الله عليه وسلم أن يُسَافَرَ بالقرآن إلى أرض العدو.","متفق عليه","صحيح"],["عن جابر بن عبد الله رضي الله عنهما كان رسول الله صلى الله عليه وسلم يَتَخَلَّف في الـمَسِير، فيُزْجِي الضعيف، ويُرْدِف ويدعو له.","رواه أبو داود","صحيح"],["عن ابن عباس رضي الله عنهما قال: لما قدم النبي صلى الله عليه وسلم مكة استقبلته أغيلمة بني عبد المطلب، فحمل واحدًا بين يديه، وآخرَ خلفه.","رواه البخاري","صحيح"],["عن أنس رضي الله عنه أن النبي صلى الله عليه وسلم كان إذا قدم من سفرٍ، فنظر إلى ‌جُدُرات المدينة أوضع راحلته، وإن كان على دابة حركها من حبها.","رواه البخاري","صحيح"],["عن أبي قتادة الأنصاري رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا كان في سفر، فعَرَّس بليل اضطجع على يمينه، وإذا عَرَّس قُبَيْل الصُّبْح نصَب ذراعه، ووضَع رَأْسه على كَفِّه.","رواه مسلم","صحيح"]]],["آداب النوم والاستيقاظ",[["عن عائشة قالت: ما نام رسول الله صلى الله عليه وسلم قبل العشاء، ولا سمر بعدها.","رواه ابن ماجه","صحيح"],["عن عبد الله بنِ عمر رضي الله عنهما أن عمرَ بْن الخطاب رضي الله عنه قال: ((يا رسول الله، أّيَرقُدُ أَحَدُنا وهو جُنُب؟ قال: نعم، إِذَا تَوَضَّأ أَحَدُكُم فَليَرقُد)).","متفق عليه","صحيح"],["عن ابن شهاب عن عباد بن تميم عن عمه أنه رأى رسول الله صلى الله عليه وسلم مستلقيًا في المسجد، واضعًا إحدى رجليه على الأخرى. وعن ابن شهاب عن سعيد بن المسيب قال: كان عمر وعثمان يفعلان ذلك.","متفق عليه","صحيح"],["عن أبي موسى الأشعري رضي الله عنه قال: احْتَرَقَ بَيْتٌ بالمَدِينَةِ عَلَى أهْلِهِ مِنَ اللَّيْلِ، فَلَمَّا حُدِّثَ رَسُولُ اللهِ صلى الله عليه وسلم بِشَأنِهِم، قالَ: «إنَّ هذه النارَ عَدُوٌّ لَكُمْ، فَإِذَا نِمْتُم، فَأَطْفِئُوهَا عَنْكُمْ».","متفق عليه","صحيح"],["عن عبادة بن الصامت عن النبي صلى الله عليه وسلم قال: \"من تَعَارَّ من الليل فقال: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير، الحمد لله، وسبحان الله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، ثم قال: اللهم اغفر لي، أو دعا، استجيب له، فإن توضأ وصلى قبلت صلاته\".","رواه البخاري","صحيح"],["عن أبي هريرة رضي الله عنه أن أبا بكر الصديق رضي الله عنه قال: يا رسول الله مُرني بكلمات أقُولُهُنَّ إذا أصبَحتُ وإذا أمسَيتُ، قال: «قل: اللهم فاطِرَ السماوات والأرض عالم الغيبِ والشهادة، ربَّ كُلِّ شَيءٍ ومَلِيكَه، أَشْهد أن لا إله إلا أنت، أعوذ بك من شرِّ نفسي وشرِّ الشيطان وشِرْكِهِ وأن أقترف على نفسي سوءًا أو أجرُّه إلى مسلم» قال: «قلها إذا أصبحت، وإذا أمسيت، وإذا أخذْتَ مَضْجَعَك».","رواه أبو داود والترمذي والنسائي وأحمد","صحيح"]]],["آداب الرؤيا",[["عن ابن عمر رضي الله عنهما قال: قال النبي صلى الله عليه وسلم : «أَفْرَى الفِرَى أن يُرِيَ الرجل عينيه ما لم تَرَيَا».","رواه البخاري","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من رآني في المنام فَسَيَرَانِي في اليَقظة -أو كأنما رآني في الْيَقَظَةِ- لا يَتَمَثَّلُ الشيطان بي».","متفق عليه.\nمسلم","صحيح"],["عن أبي هريرة ـ رضي الله عنه ـ قال: سمعت رسول الله صلى الله عليه وسلم يقول: «لم يبقَ من النُّبُوَّةِ إلا المُبَشِّرَاتُ» قالوا: وما المُبَشِّرَاتُ ؟ قال: «الرؤيا الصالحة».","رواه البخاري","صحيح"],["عن وَاثِلَةَ بن الأَسْقَعِ ـ رضي الله عنه ـ مرفوعاً: «إن من أعظم الفِرَى أن يَدَّعِيَ الرجلُ إلى غير أبيه، أو يُرِي عَيْنَهُ ما لم تَرَ، أو يقول على رسول الله صلى الله عليه وسلم ما لم يَقْلْ».","رواه البخاري","صحيح"],["عن ابن عمر قال: سمعت رسول الله صلى الله عليه وسلم قال: «بينا أنا نائمٌ أُتِيتُ بِقَدَحِ لَبَنٍ، فشربتُ حتى إني لأرى الرِّيَّ يخرج في أظفاري، ثم أعطيتُ فَضْلي عمر بن الخطاب» قالوا: فما أوَّلته يا رسول الله؟ قال: «العلم».","متفق عليه","صحيح"],["عن أبي سعيد الخدري قال: قال رسول الله صلى الله عليه وسلم: «بينا أنا نائمٌ رأيت الناس يُعرَضون عليَّ وعليهم قُمُصٌ، منها ما يبلغ الثُّدِيَّ، ومنها ما دون ذلك، وعُرِضَ عليَّ عمر بن الخطاب وعليه قميصٌ يَجُرُّه» قالوا: فما أولت ذلك يا رسول الله؟ قال: «الدين».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: سمعت النبي صلى الله عليه وسلم يقول: «بينا أنا نائم رأيتني على قَلِيبٍ عليها دَلْوٌ، فنزعتُ منها ما شاء الله، ثم أخذها ابن أبي قحافة فنزع بها ذَنوبًا أو ذَنوبين، وفي نزعه ضعف، والله يغفر له ضعفه، ثم استحالت غَرْبًا، فأخذها ابن الخطاب فلم أر عَبْقَرِيًّا من الناس ينزع نزع عمر، حتى ضَرَبَ الناسُ بِعَطَنٍ».","متفق عليه","صحيح"]]],["آداب الزيارة والاستئذان",[["عن جابر بن سمرة رضي الله عنه قال:كنا إذا أتينا النبي صلى الله عليه وسلم جلس أحدنا حيث ينتهي.","رواه أبو داود والترمذي وأحمد","صحيح لغيره"],["عن عبد الله بن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «من تَسَمَّع حديث قوم وهم له كارهون؛ صُبَّ في أذنيه الآنُكُ يوم القيامة».","رواه البخاري.\nملحوظة:\nلفظ البخاري: \"من استمع إلى حديث قوم\"، و\"من تَسَمَّعَ\" رواه الخرائطي في مساويء الأخلاق (ح720)","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إذا دُعِيَ أحدكم فليُجب، فإن كان صائما فليُصَلِّ، وإن كان مُفْطِرا فليَطْعَمْ».","رواه مسلم","صحيح"],["عن أنس رضي الله عنه ، قال: «لم يكن شخصٌ أَحَبَّ إليهم مِن رسول الله -صلى الله عليه وسلم، وكانوا إذا رَأَوْه لم يقوموا لِمَا يَعْلَمون مِن كَرَاهِيَته لذلك».","رواه الترمذي","صحيح"],["عن عبد الله بن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «لا يُقِيمُ الرجلُ الرجلَ من مَجْلِسِهِ، ثم يجلس فيه، ولكن تَفَسَّحُوا، وتَوَسَّعُوا».","متفق عليه","صحيح"],["عن عبد الله بن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : \"إذا كنتم ثلاثة فلا يتناجى اثنان دون الآخَر، حتى تختلطوا بالناس؛ من أجل أن ذلك يحُزنه\".","متفق عليه","صحيح"],["عن أنس رضي الله عنه : أن النبيَّ صلى الله عليه وسلم جاءَ إلى سعد بنِ عبادة رضي الله عنه فَجَاءَ بِخُبْزٍ وَزَيْتٍ، فأكلَ، ثم قال النبيُّ صلى الله عليه وسلم : «أفْطَرَ عِنْدَكُمُ الصَّائِمُونَ؛ وَأكَلَ طَعَامَكُمُ الأَبرَارُ، وَصَلَّتْ عَلَيْكُمُ المَلاَئِكَةُ».","رواه أبو داود وابن ماجه وأحمد والدارمي","سنده صحيح"]]],["آداب العطاس والتثاؤب",[["عن أبي هريرة رضي الله عنه قال: كان رسولُ الله صلى الله عليه وسلم إذا عَطَس وضَعَ يَدَه -أو ثوبَهُ- على فيهِ، وخَفَضَ -أو غضَّ- بها صوتَهُ.","رواه أبو داود والترمذي وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إذا عَطِسَ أحدكم فَلْيَقُلْ: الحمد لله، ولْيَقُلْ له أخوه يرحمك الله؛ فإذا قال له: يرحمك الله؛ فَلْيَقُلْ: يهديكم الله، ويُصْلِح بالكم».","روه البخاري","صحيح"],["عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «حَقُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ خَمْسٌ: رَدُّ السَّلَامِ، وَعِيَادَةُ الْمَرِيضِ، وَاتِّبَاعُ الْجَنَائِزِ، وَإِجَابَةُ الدَّعْوَةِ، وَتَشْمِيتُ الْعَاطِسِ».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إذا عَطَسَ أَحَدُكُم فَلْيَقُل: الحَمْدُ للهِ، وَلْيَقُلْ لَهُ أَخُوهُ أو صاحبُهُ: يَرْحَمُكَ الله، فإذا قال له: يرحمك الله، فَلْيَقُلْ: يَهْدِيكُم الله ويُصْلِحُ بَالَكُم».","رواه البخاري","صحيح"],["عن أبي هريرة، قال: قال رسول الله صلى الله عليه وسلم: (لما خلق الله آدم ونفخ فيه الروح عطس فقال: الحمد لله، فحمد الله بإذنه، فقال له ربه: رحمك الله يا آدم، اذهب إلى أولئك الملائكة، إلى ملإ منهم جلوس، فقل: السلام عليكم، قالوا: وعليك السلام ورحمة الله، ثم رجع إلى ربه، فقال: إن هذه تحيتك وتحية بنيك، بينهم، فقال الله له ويداه مقبوضتان: اختر أيهما شئت، قال: اخترت يمين ربي وكلتا يدي ربي يمين مباركة ثم بسطها فإذا فيها آدم وذريته، فقال: أي رب، ما هؤلاء؟ فقال: هؤلاء ذريتك، فإذا كل إنسان مكتوب عمره بين عينيه، فإذا فيهم رجل أضوؤهم، أو من أضوئهم - قال: يا رب من هذا؟ قال: هذا ابنك داود قد كتبت له عمر أربعين سنة. قال: يا رب زده في عمره. قال: ذاك الذي كتب له. قال: أي رب، فإني قد جعلت له من عمري ستين سنة. قال: أنت وذاك، قال: ثم أسكن الجنة ما شاء الله، ثم أهبط منها، فكان آدم يعد لنفسه، قال: فأتاه ملك الموت، فقال له آدم: قد عجلت، قد كتب لي ألف سنة. قال: بلى ولكنك جعلت لابنك داود ستين سنة، فجحد فجحدت ذريته، ونسي فنسيت ذريته. قال: فمن يومئذ أمر بالكتاب والشهود).","رواه الترمذي","حسن"]]],["آداب عيادة المريض",[["عن جابر رضي الله عنه قال: «جاءني النبيُّ صلى الله عليه وسلم يَعُودُني، ليس بِرَاكبٍ بَغْل ولا بِرْذَوْن».","رواه البخاري","صحيح"],["عن عبدالله بن عباس رضي الله عنهما أنّ النبي صلى الله عليه وسلم دخلَ على أعرابيٍّ يَعُودُه، وكان إذا دَخَلَ على مَن يَعودُه، قال: «لا بأس؛ طَهُور إن شاء الله».","رواه البخاري","صحيح"],["عن سعد بن أبي وقاص رضي الله عنه قَال: عَادَنِي رسول الله صلى الله عليه وسلم فقال: «اللَّهُمَّ اشْفِ سَعْداً، اللَّهُمَّ اشْفِ سَعْداً، اللَّهُمَّ اشْفِ سَعْداً».","متفق عليه واللفظ بنحوه لمسلم","صحيح"],["عن ثوبان رضي الله عنه عن النبي صلى الله عليه وسلم قَالَ: \"إنَّ المسلِمَ إذا عادَ أخاه المسلِمَ، لم يَزَلْ في خُرْفَةِ الجَنَّةِ حتى يرجعَ\"، قيل: يا رسولَ اللهِ ما خُرْفَةُ الجنَّةِ؟، قال: \"جَنَاها\".","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «حَقُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ خَمْسٌ: رَدُّ السَّلَامِ، وَعِيَادَةُ الْمَرِيضِ، وَاتِّبَاعُ الْجَنَائِزِ، وَإِجَابَةُ الدَّعْوَةِ، وَتَشْمِيتُ الْعَاطِسِ».","متفق عليه","صحيح"],["عن أنس رضي الله عنه أنه قَالَ لِثابِتٍ رحمه اللهُ: ألاَ أرْقِيكَ بِرُقْيَةِ رسولِ اللهِ صلى الله عليه وسلم ؟ قال: بلى، قال: «اللَّهُمَّ رَبَّ النَّاسِ، مُذْهِبَ البَأسِ، اشْفِ أنْتَ الشَّافِي، لاَ شَافِيَ إِلاَّ أنْتَ، شِفَاءً لاَ يُغَادِرُ سَقماً».","رواه البخاري","صحيح"],["عن علي رضي الله عنه قال: سمعتُ رسولَ اللهِ صلى الله عليه وسلم يقول: « مَا مِنْ مُسْلِم يَعُودُ مُسْلِماً غُدْوة إِلاَّ صَلَّى عَلَيْهِ سَبْعُونَ ألْفَ مَلَكٍ حَتَّى يُمْسِي، وَإنْ عَادَهُ عَشِيَّةً إِلاَّ صَلَّى عَلَيْهِ سَبْعُونَ ألْفَ مَلَكٍ حَتَّى يُصْبحَ، وَكَانَ لَهُ خَرِيفٌ في الْجَنَّةِ».","رواه أبو داود والترمذي وابن ماجه وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «مَنْ عَادَ مَرِيضًا أَو زَارَ أَخًا لَهُ فِي الله، نَادَاهُ مُنَادٍ: بِأَنْ طِبْتَ، وَطَابَ مَمْشَاكَ، وَتَبَوَّأتَ مِنَ الجَنَّةِ مَنْزِلاً».","رواه الترمذي وابن ماجه وأحمد","حسن"]]],["آداب اللباس",[["عن جابر رضي الله عنه : أن رسول الله صلى الله عليه وسلم نهى أن يَنْتَعِلَ الرَّجُل قائمًا.","رواه أبو داود والترمذي وابن ماجه","صحيح"],["عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «لا يمش أحدكم في نعل واحدة، لِيُنْعِلهما جميعًا، أو لِيَخْلَعْهُمَا جميعًا».","متفق عليه","صحيح"],["عن ابنِ عمرَ رضي الله عنهما ، قال: مَرَرْتُ على رسولِ اللهِ صلى الله عليه وسلم وفي إِزَارِي اسْتِرْخَاءٌ، فقال: «يا عبدَ اللهِ، ارْفَعْ إِزَارَكَ» فَرَفَعْتُهُ ثم قال: «زِدْ» فَزِدْتُ، فما زِلْتُ أَتَحَرَّاهَا بَعْدُ، فقال بعضُ القَوْمِ: إلى أين؟ فقال: إلى أَنْصَافِ السَّاقَيْنِ.","رواه مسلم","صحيح"]]]]],["الأدعية والأذكار",0,[["هدي النبي صلى الله عليه وسلم في الذكر",[["عن أنس رضي الله عنه قَالَ: قَالَ رسُولُ الله صلى الله عليه وسلم : «ألِظُّوا بـ (يَاذا الجَلاَلِ والإكْرامِ)».","ملاحظة: رواية النسائي وأحمد عن ربيعة بن عامر","صحيح"],["عن عبد الله بن مسعود رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم يقول: «اللهم ِإنِّي أَسأَلُك الهُدَى، والتُّقَى، والعَفَاف، والغِنَى».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «وَاللهِ إني لأَسْتَغْفِرُ اللهَ وأَتُوبُ إليهِ في اليومِ أَكْثَرَ من سَبْعِينَ مَرَّةً».","رواه البخاري","صحيح"],["عن المهاجر بن قنفذ أنه أتى النبي صلى الله عليه وسلم وهو يبول، فسلم عليه، فلم يرد عليه حتى توضأ، ثم اعتذر إليه فقال: \"إني كرهت أن أذكر الله عز وجل إلا على طهر\" أو قال: \"على طهارة\".","رواه أبو داود والنسائي وابن ماجه وأحمد","صحيح"],["عن علي بن أبي طالب رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا قام إلى الصلاة يكون من آخر ما يقول بين التشهد والتسليم: «اللهم اغفر لي ما قَدَّمتُ وما أخَّرْتُ، وما أسررتُ وما أعلنتُ، وما أسْرَفتُ، وما أنت أعلم به مني، أنت المُقَدِّم، وأنت المؤخر، لا إله إلا أنت».","رواه مسلم","صحيح"]]],["فوائد ذكر الله عز وجل",[["عن زيد مولى رسول الله صلى الله عليه وسلم قال: قال رسول الله صلى الله عليه وسلم : «من قال: أَسْتَغْفِرُ الله الذي لا إله إلا هو الحَيَّ القيَّومَ وأتوب إليه، غُفرت ذنوبه، وإن كان قد فَرَّ من الزَّحْف».","رواه أبو داود والترمذي","صحيح"],["عن أبي مالكٍ الأشعريِّ رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «الطُّهُورُ شَطْرُ الْإِيمَانِ، وَالْحَمْدُ لِلهِ تَمْلَأُ الْمِيزَانَ، وَسُبْحَانَ اللهِ وَالْحَمْدُ لِلهِ تَمْلَآنِ -أَوْ تَمْلَأُ- مَا بَيْنَ السَّمَاوَاتِ وَالْأَرْضِ، وَالصَّلَاةُ نُورٌ، وَالصَّدَقَةُ بُرْهَانٌ، وَالصَّبْرُ ضِيَاءٌ، وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ، كُلُّ النَّاسِ يَغْدُو، فَبَايِعٌ نَفْسَهُ فَمُعْتِقُهَا أَوْ مُوبِقُهَا».","رواه مسلم","صحيح"]]],["أذكار الصباح والمساء",[["عن جابر أن النبي صلى الله عليه وسلم كان لا ينام حتى يقرأ الم تنزيل، وتبارك الذي بيده الملك.","رواه الترمذي","صحيح"],["عن أبي مسعود رضي الله عنه قال: قال النبي صلى الله عليه وسلم: «مَنْ قَرَأَ بِالْآيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ».","متفق عليه","صحيح"],["عن عبد الله بن مسعود رضي الله عنه قال: كان نبي الله صلى الله عليه وسلم إذا أمسى قال: «أمسينا وأمسى الملك لله، والحمد لله، لا إله إلا الله وحده لا شريك له» قال الراوي: أَرَاهُ قال فِيهِنَّ: «له الملك وله الحمد وهو على كل شيء قدير، ربِّ أسألك خير ما في هذه الليلة وخير ما بعدها، وأعوذ بك من شر ما في هذه الليلة وشر ما بعدها، رب أعوذ بك من الكسل، وسُوءِ الكِبَرِ، رب أعوذ بك من عذاب في النار، وعذاب في القبر»، وإذا أصبح قال ذلك أيضا «أصبحنا وأصبح الملك لله».","رواه مسلم","صحيح"]]],["الأذكار المطلقة",[["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «لَأَنْ أَقُولَ: سُبْحَانَ اللهِ، وَالْحَمْدُ لِلهِ، وَلَا إِلَهَ إِلَّا اللهُ، وَاللهُ أَكْبَرُ، أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللهِ الْعَظِيمِ، سُبْحَانَ اللهِ وَبِحَمْدِهِ».","متفق عليه","صحيح"],["عن سَمُرَة بن جندبٍ رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «أَحَبُّ الْكَلَامِ إِلَى اللهِ أَرْبَعٌ: سُبْحَانَ اللهِ، وَالْحَمْدُ لِلهِ، وَلَا إِلَهَ إِلَّا اللهُ، وَاللهُ أَكْبَرُ، لَا يَضُرُّكَ بِأَيِّهِنَّ بَدَأْتَ».","رواه مسلم","صحيح"],["عن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : \"الْبَاقِيَاتُ الصَّالِحَاتُ، لَا إلَهَ إلَّا اللَّهُ، وَسُبْحَانَ اللَّهِ، وَاَللَّهُ أَكْبَرُ، وَالْحَمْدُ لِلَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إلَّا بِاَللَّهِ\".","رواه ابن حبان والحاكم، أما النسائي فرواه في الكبرى لكن من حديث أبي هريرة","صحيح بشواهده"],["عن جابر رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «أَفْضَلُ الذِّكْرِ: لَا إِلَهَ إِلَّا اللهُ، وَأَفْضَلُ الدُّعَاءِ: الْحَمْدُ لِلهِ».","رواه الترمذي والنسائي في الكبرى وابن ماجه","حسن"]]],["أذكار الدخول والخروج من الخلاء",[["عن زيد بن أرقم رضي الله عنه ، عن رسول الله صلى الله عليه وسلم قال:«إنَّ هذه الحُشُوشَ مُحْتَضَرَةٌ، فإذا أتى أحدُكم الخَلَاءَ فَلْيَقُلْ: أعوذُ باللهِ مِنَ الخُبُثِ والخَبَائث».","رواه أبو داود وابن ماجه وأحمد","صحيح"]]],["أذكار الدخول والخروج من المسجد",[["عن عبد الله بن عمرو بن العاص رضي الله عنهما: عن النبي صلى الله عليه وسلم أنه كان إذا دخل المسجد قال: «أعوذ بالله العظيم، وبوجهه الكريم، وسلطانه القديم، من الشيطان الرَّجِيم»، قال: أَقَطُّ؟ قلت: نعم، قال: فإذا قال ذلك قال الشيطان: حُفِظَ منِّي سائر اليوم.","رواه أبو داود","حسن"]]],["الأذكار التي تقال في أوقات الشدة",[["عن أنس بن مالك رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا غزا، قال: «اللهم أنت عَضُدِي ونَصِيرِي، بِكَ أَحُول، وبِكَ أَصُول، وبك أقاتل».","رواه أبو داود والترمذي","صحيح"],["عن أبي سعيد الخدري رضي الله عنه مرفوعاً: «كَيْفَ أَنْعَمُ! وصَاحِبُ القَرْنِ قَدِ التَقَمَ القَرْنَ، واسْتَمَعَ الإِذْنَ مَتَى يُؤْمَرُ بالنَّفْخِ فَيَنْفُخُ»، فَكَأَنَّ ذَلِكَ ثَقُلَ على أصحابِ رسولِ اللهِ صلى الله عليه وسلم فقال لهم: «قُولُوا: حَسْبُنَا اللهُ ونِعْمَ الوَكِيلُ».","رواه الترمذي وأحمد","صحيح"]]],["الأذكار للأمور العارضة",[["عن عائشة أن رسول الله صلى الله عليه وسلم كان إذا رأى المطر قال: «اللهم صَيِّبًا نافعًا».","رواه البخاري","صحيح"],["عن سلمة بن الأكوع يرفعه إلى النبي صلى الله عليه وسلم قال: كان إذا اشتدت الريح يقول: «اللهم لَقِحًا لا عقيمًا».","رواه ابن حبان","صحيح"],["عن أنس رضي الله عنه أن رسول الله صلى الله عليه وسلم كان إذا أوى إلى فراشه، قال: «الحمد لله الذي أطعمنا وسقانا، وكفانا وآوانَا، فَكَمْ مِمَّنْ لا كَافِيَ له وَلاَ مُؤْوِيَ».","رواه مسلم","صحيح"],["عن طلحة بن عبيد الله رضي الله عنه أن النبي صلى الله عليه وسلم كانَ إذا رأى الهلالَ، قال: «اللّهمَّ أهِلَّهُ عليْنا بالأمْن والإيمان، وَالسَّلامَةِ وَالإسلامِ، ربِّي وربُّكَ اللهُ، هِلالُ رُشْدٍ وخيرٍ».","رواه الترمذي وأحمد والدارمي، وليس عندهم لفظة: \"هلال رشد وخير\"، وجاءت عند ابن ابي شيبة بسند مرسل","صحيح"],["عن عبد الله بن سَرْجِس رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم إذا سافر يَتَعَوَّذ مِن وَعْثاء السَّفَر، وكآبة الـمُنْقَلَب، والحَوْر بعد الكَوْن، ودعوة المظلوم، وسُوء الـمَنْظَر في الأهل والمال.","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها ، قالت: كان النبي صلى الله عليه وسلم إذا عَصَفَت الرِّيح قال: «اللَّهُمَّ إنِّي أسْأَلُك خَيرها وخير ما فيها وخَير ما أُرسِلت به، وأعوذ بك من شرِّها وشرِّ ما فيها وشرِّ ما أُرسِلت به».","رواه مسلم","صحيح"],["عن أبي أمامة رضي الله عنه أن النبي صلى الله عليه وسلم كَانَ إذا رَفَعَ مَائِدَتَهُ، قال: «الحَمْدُ للهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ مَكْفِيٍّ، وَلَا مُوَدَّعٍ، وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا».","رواه البخاري","صحيح"],["عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: « الرِّيحُ من رَوْحِ الله، تأتي بالرَّحمة، وتأتي بالعَذَاب، فإذا رَأَيْتُمُوهَا فَلاَ تَسُبُّوهَا، وسَلُوا الله خَيرها، واسْتَعِيذُوا بالله من شرِّها».","رواه أبو داود والنسائي وأحمد","صحيح"],["عن جابر رضي الله عنه قَالَ: كُنَّا إِذَا صَعِدْنَا كَبَّرْنَا، وَإِذَا نَزَلْنَا سَبَّحْنَا. عن ابن عمر رضي الله عنهما قالَ: كانَ النبيُّ صلى الله عليه وسلم وجيُوشُهُ إِذَا عَلَوا الثَّنَايَا كَبَّرُوا، وَإِذَا هَبَطُوا سَبَّحُوا.","حديث جابر -رضي الله عنه- رواه البخاري.\nحديث ابن عمر -رضي الله عنهما- رواه أبو داود","صحيحان"]]],["أحكام الدعاء",[["عن أبي هريرة رضي الله عنه أنَّ النبيَّ صلى الله عليه وسلم كان إذا رفع رأسه من الركعة الآخِرة، يقول: «اللهمَّ أَنْجِ عَيَّاش بن أبي ربيعة، اللهمَّ أَنْجِ سَلَمَة بنَ هشام، اللهم أَنْجِ الوليد بن الوليد، اللهم أَنْجِ المستضعفين من المؤمنين، اللهمَّ اشْدُدْ وَطْأَتَك على مُضَر، اللهمَّ اجعلها سنين كسِنِي يوسف». وأنَّ النبيَّ صلى الله عليه وسلم قال: «غِفَارُ غفر الله لها، وأَسْلَمُ سالمها الله» قال ابن أبي الزناد عن أبيه: هذا كلُّه في الصبح.","متفق عليه","صحيح"]]],["أنواع الدعاء",[["عن عاصم قال: سألتُ أنساً رضي الله عنه عن القُنُوت، قال: قبل الركوع، فقلت: إن فلاناً يزعم أنك قلت بعد الركوع؟ فقال: كَذَبَ، ثم حَدَّثَنَا، عن النبي صلى الله عليه وسلم : «أنه قنت شهراً بعد الركوع، يدعو على أحياء من بني سليم»، قال: «بعث أربعين -أو سبعين يشك فيه- من القراء إلى أناس من المشركين»، فعرض لهم هؤلاء فقتلوهم، وكان بينهم وبين النبي صلى الله عليه وسلم عهد، «فما رأيته وجد على أحد ما وجد عليهم».","متفق عليه","صحيح"]]],["آداب الدعاء",[["عن أنس بن مالك قال: كان النبي صلى الله عليه وسلم لا يرفع يديه في شيء من دعائه إلا في الاستسقاء، وإنه يرفع حتى يرى بياض إبطيه.","متفق عليه","صحيح"],["عن أنس رضي الله عنه : أن النبيَّ صلى الله عليه وسلم جاءَ إلى سعد بنِ عبادة رضي الله عنه فَجَاءَ بِخُبْزٍ وَزَيْتٍ، فأكلَ، ثم قال النبيُّ صلى الله عليه وسلم : «أفْطَرَ عِنْدَكُمُ الصَّائِمُونَ؛ وَأكَلَ طَعَامَكُمُ الأَبرَارُ، وَصَلَّتْ عَلَيْكُمُ المَلاَئِكَةُ».","رواه أبو داود وابن ماجه وأحمد والدارمي","سنده صحيح"],["عن أبي هريرة رضي الله عنه مرفوعاً: يُستجاب لأحدكم ما لم يَعْجَلْ: يقول: قد دعوت ربي، فلم يستجب لي». وفي رواية لمسلم: «لا يزال يُستجاب للعبد ما لم يَدْعُ بإثم، أو قطيعة رحم، ما لم يَسْتَعْجِلْ» قيل: يا رسول الله ما الاستعجال؟ قال: «يقول: قد دعوت، وقد دعوت، فلم أر يستجب لي، فَيَسْتَحْسِرُ عند ذلك ويَدَعُ الدعاء».","متفق عليه","صحيح"],["عن أبي بن كعب رضي الله عنه : كان رسولُ اللهِ صلى الله عليه وسلم إذا ذَهَبَ ثُلثُ الليلِ قامَ، فقال: \"يا أيها الناسُ، اذكروا اللهَ، جاءت الرَّاجِفَةُ، تَتْبَعُها الرَّادِفَةُ، جاءَ الموتُ بما فيه، جاءَ الموتُ بما فيه\"، قلتُ: يا رسول الله، إني أُكْثِرُ الصلاةَ عليكَ، فكم أجعلُ لكَ من صلاتِي؟ فقالَ: \"ما شِئتَ\"، قلتُ: الرُّبُعَ؟، قالَ: \"ما شئتَ، فإنْ زِدتَ فهو خيرٌ لكَ\"، قلتُ: فالنّصفَ؟، قالَ: \"ما شئتَ، فإن زِدتَ فهو خيرٌ لكَ\"، قلتُ: فالثلثين؟ قالَ: \"ما شئتَ، فإن زدتَ فهو خيرٌ لكَ\"، قلتُ: أجعلُ لكَ صلاتِي كُلَّها؟ قالَ: \"إذاً تُكْفى هَمَّكَ، ويُغْفَرَ لكَ ذَنبُكَ\".","رواه الترمذي وأحمد","حسن"]]],["أسباب إجابة الدعاء وموانعه",[["عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا يُرد الدعاء بين الأذان والإقامة».","رواه أبو داود والترمذي وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ، فَأَكْثِرُوا الدُّعَاءَ».","رواه مسلم","صحيح"],["عن جابر رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إن في الليل لساعة، لا يُوَافِقُهَا رجُلٌ مُسلم يَسأل الله تعالى خيرًا من أمْرِ الدنيا والآخرة، إلا أعْطَاه إِياه، وذلك كُلَّ ليلة».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه: أن رسول الله صلى الله عليه وسلم قال: \"ينزل ربُّنا تبارك وتعالى كلَّ ليلة إلى السماء الدنيا حين يبقى ثلث الليل الآخر، يقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له\".","متفق عليه","صحيح"],["عن أبي بردة بن أبي موسى الأشعري قال: قال لي عبد الله بن عمر: أسمعت أباك يحدث عن رسول الله صلى الله عليه وسلم في شأن ساعة الجمعة؟ قال: قلت: نعم، سمعته يقول: سمعت رسول الله صلى الله عليه وسلم يقول: «هي ما بين أن يجلس الإمام إلى أن تقضى الصلاة».","رواه مسلم","صحيح بشواهده"],["عن بريدة رضي الله عنه قال: سمع النبي صلى الله عليه وسلم رجلاً يقول: اللهم إني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت، الأحد الصمد، الذي لم يلد، ولم يولد، ولم يكن له كفوًا أحد. فقال: «لقد سأل الله باسمه الذي إذا سُئِلَ به أعطى، وإذا دُعِيَ به أجاب»","رواه أبو داود والترمذي والنسائي وابن ماجه","صحيح"]]],["الأدعية المأثورة",[["عن أنس رضي الله عنه قَالَ: قَالَ رسُولُ الله صلى الله عليه وسلم : «ألِظُّوا بـ (يَاذا الجَلاَلِ والإكْرامِ)».","ملاحظة: رواية النسائي وأحمد عن ربيعة بن عامر","صحيح"],["عن عبد الله بن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم :«اللهم كما حَسَّنْت خَلْقِي فَحَسِّنْ خُلُقِي».","رواه أحمد","صحيح"],["عن عبد الله بن مسعود رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم يقول: «اللهم ِإنِّي أَسأَلُك الهُدَى، والتُّقَى، والعَفَاف، والغِنَى».","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها أن النبي صلى الله عليه وسلم كان يدعو بهذه الكلمات: «اللهم إني أعوذ بك من فتنة النار، وعذاب النار، ومن شر الغنى والفقر».","رواه أبو داود والترمذي وابن ماجه","صحيح"],["عن سعد بن أبي وقاص رضي الله عنه قَال: عَادَنِي رسول الله صلى الله عليه وسلم فقال: «اللَّهُمَّ اشْفِ سَعْداً، اللَّهُمَّ اشْفِ سَعْداً، اللَّهُمَّ اشْفِ سَعْداً».","متفق عليه واللفظ بنحوه لمسلم","صحيح"],["عن شكل بن حميد رضي الله عنه قال: قلت: يا رسول الله، عَلِّمْنِي دعاء، قال: (قل: اللهم إني أعوذ بك من شر سمعي، ومن شر بصري، ومن شر لساني، ومن شر قلبي، ومن شر مَنِيِّي).","رواه أبو داود والترمذي والنسائي وأحمد","صحيح"],["عن أبي بكر الصديق رضي الله عنه: أنه قال لرسول الله صلى الله عليه وسلم: علمني دعاء أدعو به في صلاتي، قال: \"قل: اللهم إني ظلمت نفسي ظلما كثيرا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني إنك أنت الغفور الرحيم\".","متفق عليه","صحيح"]]]]],["الرقائق والمواعظ",0,[["أعمال القلوب",[["عن جابر قال: قال رسول الله صلى الله عليه وسلم: «إذا قضى أحدكم الصلاة في مسجده فليجعل لبيته نصيبًا من صلاته، فإن الله جاعلٌ في بيته من صلاته خيرًا».","رواه مسلم","صحيح"],["عن أنس رضي الله عنه قال: قال النبي صلى الله عليه وسلم: «لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إِنَّ اللهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ، وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «قَالَ اللهُ تَبَارَكَ وَتَعَالَى: أَنَا أَغْنَى الشُّرَكَاءِ عَنِ الشِّرْكِ، مَنْ عَمِلَ عَمَلًا أَشْرَكَ فِيهِ مَعِي غَيْرِي تَرَكْتُهُ وَشِرْكَهُ».","رواه مسلم","صحيح"],["عن ابن عباس حسبنا الله ونعم الوكيل: «قالها إبراهيم عليه السلام حين أُلقي في النار، وقالها محمد صلى الله عليه وسلم حين قالوا: {إن الناس قد جمعوا لكم فاخشوهم فزادهم إيمانا، وقالوا: حسبنا الله ونعم الوكيل} [آل عمران: 173]».","رواه البخاري","صحيح"]]],["أمراض القلوب",[["عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إن أول الناس يُقضى يوم القيامة عليه رجُل اسْتُشْهِدَ، فأُتي به، فعرَّفه نِعمته، فعرَفَها، قال: فما عَمِلت فيها؟ قال: قَاتَلْتُ فيك حتى اسْتُشْهِدْتُ. قال: كَذبْتَ، ولكنك قَاتَلْتَ لأن يقال: جَرِيء! فقد قيل، ثم أُمِرَ به فَسُحِب على وجهه حتى أُلقي في النار. ورجل تعلم العلم وعلمه، وقرأ القرآن، فأُتي به فعرَّفه نِعَمه فعرَفَها. قال: فما عملت فيها؟ قال: تعلمت العلم وعلمته، وقرأت فيك القرآن، قال: كَذَبْتَ، ولكنك تعلمت ليقال: عالم! وقرأت القرآن ليقال: هو قارئ؛ فقد قيل، ثم أُمِر به فَسُحِب على وجهه حتى ألقي في النار. ورجل وَسَّعَ الله عليه، وأعطاه من أصناف المال، فأُتي به فعرَّفه نِعَمه، فعرَفَها. قال: فما عملت فيها؟ قال: ما تركت من سبيل تُحِبُّ أن يُنْفَقَ فيها إلا أنفقت فيها لك. قال: كَذَبْتَ، ولكنك فعلت ليقال: جواد! فقد قيل، ثم أُمِر به فَسُحِب على وجهه حتى ألقي في النار».","رواه مسلم","صحيح"],["عن حذيفة بن اليمان رضي الله عنه قال: حَدَثَنا رسول الله صلى الله عليه وسلم حدِيثَين قَد رَأَيتُ أَحَدَهُما وأنا أنتظر الآخر: حدثنا أنَّ الأمَانة نَزَلَت في جَذر قُلُوب الرِّجال، ثمَّ نزل القرآن فَعَلِموا مِن القرآن، وعَلِمُوا مِن السُنَّة، ثمَّ حدَّثنا عن رفع الأمانة، فقال: «يَنَامُ الرَّجُلُ النَّومَة فَتُقْبَضُ الأَمَانَةُ مِنْ قَلْبِهِ، فَيَظَلُّ أَثَرُهَا مِثلَ الوَكْتِ، ثُمَّ يَنَامُ النَّومَةَ فَتُقبَض الأَمَانَة مِن قَلْبِه، فَيَظَلُّ أَثَرُها مِثل أَثَر المَجْلِ، كَجَمْرٍ دَحْرَجْتَهُ عَلى رِجْلِكَ فَنَفِطَ، فَتَرَاهُ مُنْتَبِراً وَلَيس فِيه شَيء»، ثم أَخَذ حَصَاةً فَدَحْرَجَه على رجله «فَيَصبَح النَّاس يَتَبَايَعُون، فَلاَ يَكَاد أَحَدٌ يُؤَدِّي الأَمَانَةَ حَتَّى يُقَال: إِنَّ فِي بَنِي فُلاَن رَجُلاً أَمِيناً، حَتَّى يُقَال للرَّجُل: مَا أَجْلَدَهُ! مَا أَظْرَفَه! مَا أَعْقَلَه! وَمَا فِي قَلبِه مِثْقَالُ حَبَّة مِن خَرْدَل مِنْ إيمان»، ولَقَد أتى عَلَيَّ زَمَان وما أُبَالي أَيُّكُم بَايعت: لئِن كان مُسلِمًا لَيَرُدَنَّه عَلَيَّ دِينه، وَإِن كان نصرانيا أو يهوديا ليَرُدنَّه عَلَيَّ سَاعِيه، وأَمَّا اليوم فَمَا كُنت أَبَايِعُ مِنكُم إِلاَّ فُلاَنا وفُلاَناً».","متفق عليه","صحيح"],["عن حذيفة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «إنَّ ما أَتَخوَّفُ عليكم رجلٌ قَرَأ القرآنَ حتى إذا رُئِيَتْ بَهْجتُه عليه، وكان رِدْئًا للإِسلام، غَيَّرَه إلى ما شاء الله، فانْسَلَخَ مِنْه ونَبَذَه وراءَ ظَهْرِه، وسَعَى على جاره بالسَّيف، ورمَاه بالشِّرك»، قال: قلتُ: يا نبيَّ الله، أيُّهما أوْلى بالشِّرك، المَرْمِي أم الرَّامي؟ قال: «بل الرَّامي».","رواه ابن حبان","حسن"]]],["الزهد والورع",[["عن عبد الله بن مسعود رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم يقول: «اللهم ِإنِّي أَسأَلُك الهُدَى، والتُّقَى، والعَفَاف، والغِنَى».","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها : أنهم ذبحوا شاة فقال النبي صلى الله عليه وسلم : «ما بقي منها؟» قالت: ما بقي منها إلا كتفها. قال: «بقي كلها غير كتفها».","رواه الترمذي","صحيح"],["وعَنْ فَضَالَةَ بْنِ عُبَيْدٍ، أَنَّهُ سَمِعَ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ «طُوبَى لِمَنْ هُدِيَ إِلَى الْإِسْلَامِ، وَكَانَ عَيْشُهُ كَفَافًا وقَنِعَ».","رواه الترمذي وأحمد","صحيح"],["عن ثوبان رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من تَكَفَّلَ لي أن لا يسأل الناس شيئًا، وأَتَكَفَّلُ له بالجنة؟» فقلت: أنا، فكان لا يَسأل أحدًا شيئًا.","رواه أبو داود وأحمد والنسائي وابن ماجه وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: «لو كان لي مِثْلُ أحدٍ ذهبًا، لسرني أن لا تمر عليَّ ثلاث ليالٍ وعندي منه شيءٌ إلا شيء أرْصُدُهُ لِدَيْنٍ».","متفق عليه واللفظ للبخاري","صحيح"],["عن عبد الله بن عمرو بن العاص رضي الله عنهما قال: مرَّ علينا رسول الله صلى الله عليه وسلم ونحن نُعالج خُصًّا لنا، فقال: «ما هذا؟» فقلنا: قد وَهَى، فنحن نُصلحه، فقال: «ما أرى الأمر إلا أَعْجَل من ذلك».","راوه أبو داود والترمذي وابن ماجه","صحيح"],["عن قتادة عن أنس رضي الله عنه قال: ما علمتُ النبيَّ صلى الله عليه وسلم أَكَلَ على سُكُرُّجَةٍ قط، ولا خُبِزَ له مُرَقَّقٌ قط، ولا أكل على خِوَانٍ قط. قيل لقتادة: فعلام كانوا يأكلون؟ قال: على السُّفَر.","رواه البخاري","صحيح"],["عن البراء بن عازب رضي الله عنهما قال: أُتِيَ رسول الله صلى الله عليه وسلم بثوب من حريرٍ، فجعلوا يعجبون من حُسْنِه ولِيْنِه، فقال رسول الله صلى الله عليه وسلم: «لمناديل سعد بن معاذ في الجنة أفضل من هذا».","متفق عليه","صحيح"]]],["أحوال الصالحين",[["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لقد كان فيما قبلكم من الأمم ناس محدثون، فإن يك في أمتي أحد فإنه عمر».","متفق عليه، لكنه عند البخاري من حديث أبي هريرة وعند مسلم من حديث عائشة","صحيح"],["عن أبي سعيد الخدري رضي الله عنه قالَ: قالَ رسولُ اللهِ صلى الله عليه وسلم : \"يُوشَكُ أنْ يكونَ خيرَ مالِ المسلمِ غَنَمٌ يَتَّبعُ بها شَعَفَ الجبالِ، ومواقعَ القطرِ يَفِرُّ بدينِهِ من الفتنِ\".","رواه البخاري","صحيح"],["عن معاذ بن جبل رضي الله عنه عن رسول الله صلى الله عليه وسلم أنه قال: «قَالَ اللهُ -عَزَّ وجَلَّ-: المُتَحَابُّون فِي جَلاَلِي، لَهُم مَنَابِرُ مِن نُورٍ يَغْبِطُهُم النَبِيُّونَ والشُهَدَاء».","رواه الترمذي وأحمد","صحيح"],["عن عبد الرزاق قال: (أهل مكة يقولون: أخذ ابن جريج الصلاة من عطاء، وأخذها عطاء من ابن الزبير، وأخذها ابن الزبير من أبي بكر، وأخذها أبو بكر من النبي صلى الله عليه وسلم، ما رأيت أحدا أحسن صلاة من ابن جريج).","رواه أحمد","صحيح"],["عن أنس بن مالك رضي الله عنه أنَّ رَجُلاً كَانَ عِند النَبِيَّ صلى الله عليه وسلم فَمَرَّ رَجُلٌ بِهِ، فقال: يا رسول الله، أنِّي لَأُحِبُّ هَذَا، فَقَال لَهُ النَبِيُّ صلى الله عليه وسلم : «أَأَعْلَمْتَهُ؟» قال: لا. قال: «أَعْلِمْهُ»، فَلَحِقَهُ، فقال: إِنِّي أُحِبُّك فِي الله، فقال: أّحَبَّك الَّذِي أَحْبَبْتَنِي لَهُ.","رواه أبو داود والنسائي في الكبرى وأحمد","صحيح"]]],["ذم المعاصي",[["عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: «الجَرَسُ مَزَامِيرُ الشَّيطَان».","رواه مسلم","صحيح"],["عن ابن مسعود رضي الله عنه عن النبي صلى الله عليه وسلم قال: «ألا هل أُنَبِّئُكم ما العَضْهُ؟ هي النَّميمة القَالَةُ بين النّاس».","رواه مسلم","صحيح"],["عن أبي هريرة عن النبي صلى الله عليه وسلم قال: «لعن الله السارق، يسرق البَيْضَةَ فَتُقْطَعُ يده، ويسرِقُ الحَبْلَ فَتُقْطَعُ يَدُهُ».","متفق عليه","صحيح"],["عن عبد الله بن عمر رضي الله عنهما قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إذا أراد اللهُ بقومٍ عذابًا، أصابَ العذابُ من كان فيهم، ثم بُعِثوا على أعمالهم».","متفق عليه","صحيح"],["عن عبد الله بن عمرو بن العاص رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «الْكَبَائِرُ: الْإِشْرَاكُ بِاللهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَقَتْلُ النَّفْسِ، وَالْيَمِينُ الْغَمُوسُ».","رواه البخاري","صحيح"],["عن أبي بَكرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إِذَا الْتَقَى الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَالْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ»، فَقُلْتُ: يَا رَسُولَ اللهِ هَذَا الْقَاتِلُ، فَمَا بَالُ الْمَقْتُولِ؟ قَالَ: «إِنَّهُ كَانَ حَرِيصًا عَلَى قَتْلِ صَاحِبِهِ».","متفق عليه","صحيح"],["عن أبي بكرة رضي الله عنه قال: قال النبي صلى الله عليه وسلم: «‌أَلَا ‌أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ؟» ثَلَاثًا، قَالُوا: بَلَى يَا رَسُولَ اللهِ، قَالَ: «الْإِشْرَاكُ بِاللهِ، وَعُقُوقُ الْوَالِدَيْنِ» وَجَلَسَ وَكَانَ مُتَّكِئًا، فَقَالَ: «أَلَا وَقَوْلُ الزُّورِ»، قَالَ: فَمَا زَالَ يُكَرِّرُهَا حَتَّى قُلْنَا: لَيْتَهُ سَكَتَ.","متفق عليه","صحيح"]]],["ذم حب الدنيا",[["عن كعب بن عياض رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إن لكل أُمَّة فتنة، وفِتنة أُمَّتي: المال».","رواه الترمذي والنسائي في الكبرى وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: «لو كان لي مِثْلُ أحدٍ ذهبًا، لسرني أن لا تمر عليَّ ثلاث ليالٍ وعندي منه شيءٌ إلا شيء أرْصُدُهُ لِدَيْنٍ».","متفق عليه واللفظ للبخاري","صحيح"],["عن المُسْتَوْرِد بن شَدَّاد رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ما الدنيا في الآخرة إلا مِثْل ما يجعل أحدكم أُصْبُعَهُ في اليَمِّ، فلينظر بِمَ يَرْجع!».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إنكم سَتَحْرِصُونَ على الإِمَارَة، وستكون نَدَامَةً يوم القيامة، فَنِعْمَ المُرْضِعَةُ وَبِئْسَتِ الفَاطِمَةُ».","رواه البخاري","صحيح"],["عن خَولة الأنصاريةِ رضي الله عنها قالت: سمعت النبي صلى الله عليه وسلم يقول: «إِنَّ رِجَالًا يَتَخَوَّضُونَ فِي مَالِ اللهِ بِغَيْرِ حَقٍّ، فَلَهُمُ النَّارُ يَوْمَ الْقِيَامَةِ».","رواه البخاري","صحيح"]]],["ذَمُّ الهوى والشَّهوات",[["عن أسامة بن زيد رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «مَا تَرَكْتُ بَعْدِي فِتْنَةً أَضَرَّ عَلَى الرِّجَالِ مِنَ النِّسَاءِ».","متفق عليه","صحيح"],["عن ابن عمر أن رسول الله صلى الله عليه وسلم، قال وهو مستقبل المشرق: «ها إن الفتنة هاهنا، ها إن الفتنة هاهنا، ها إن الفتنة هاهنا، من حيث يطلع قرن الشيطان».","متفق عليه","صحيح"],["عن عقبة بن عامر، يقول: إن رسول الله صلى الله عليه وسلم قال: «إنِّي أخاف على أُمَّتي اثنَتَيْن: القرآنَ واللَّبَن، أما اللَّبَن فيَبْتَغُون الرِّيفَ ويتَّبِعون الشَّهَوَاتِ ويَتْركون الصلوات، وأما القرآن فيتعلَّمه المنافقون فيُجادِلون به المؤمنين».","رواه أحمد","صحيح"],["عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: «كُتب على ابن آدم نَصِيبُه من الزِنا مُدْرِكُ ذلك لا مَحَالة: العينان زِناهما النَظر، والأُذنان زِناهما الاستماع، واللسان زِناه الكلام، واليَدُ زِناها البَطْش، والرِّجل زِناها الخُطَا، والقلب يَهْوَى ويتمنى، ويُصَدِّق ذلك الفَرْج أو يُكذِّبُه».","متفق عليه","صحيح"]]],["التوبة",[["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «مَنْ تَابَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا تَابَ اللهُ عَلَيْهِ».","رواه مسلم","صحيح"],["عن عائشة، زوج النبي صلى الله عليه وسلم أنها كانت لا تسمع شيئا لا تعرفه، إلا راجعت فيه حتى تعرفه، وأن النبي صلى الله عليه وسلم قال: «من حوسب عذب» قالت عائشة: فقلت أوليس يقول الله تعالى: {فسوف يحاسب حسابا يسيرا} [الانشقاق: 8] قالت: فقال: «إنما ذلك العرض، ولكن: من نوقش الحساب يهلك».","متفق عليه","صحيح"],["عن ابن مسعود رضي الله عنه مرفوعاً: أن رجلاً أصاب من امرأةٍ قُبْلَةً، فأتى النبي صلى الله عليه وسلم فأخبره، فأنزل الله تعالى : (وأقم الصلاة طَرَفَيِ النَّهَار وزُلَفًا مِنَ اللَّيلِ إِنَّ الحَسَنَاتِ يُذْهِبنَ السَّيِئَات) [هود: 114] فقال الرجل: ألي هذا يا رسول الله؟ قال: «لِجَمِيعِ أُمَّتِي كُلِّهِم».","متفق عليه","صحيح"],["عن أنس رضي الله عنه مرفوعاً: جاء رجل إلى النبي صلى الله عليه وسلم فقال: يا رسول الله، أصَبْتُ حدًّا، فَأَقِمْه عليَّ، وحضرت الصلاة، فصلى مع رسول الله صلى الله عليه وسلم فلمَّا قضى الصلاة، قال: يا رسول الله، إني أصَبْتُ حَدًّا فأقم فيَّ كتاب الله. قال: «هل حَضَرْتَ مَعَنَا الصلاة»؟ قال: نعم. قال: «قد غُفِر لك».","متفق عليه","صحيح"],["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رضي الله عنهما أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَامَ بَعْدَ أَنْ رَجَمَ الْأَسْلَمِيَّ فَقَالَ: «اجْتَنِبُوا ‌هَذِهِ ‌الْقَاذُورَةَ الَّتِي نَهَى اللَّهُ عَنْهَا فَمَنْ أَلَمَّ فَلْيَسْتَتِرْ بِسِتْرِ اللَّهِ وَلْيُتُبْ إِلَى اللَّهِ، فَإِنَّهُ مَنْ يُبْدِ لْنَا صَفْحَتَهُ نُقِمْ عَلَيْهِ كِتَابَ اللَّهِ عز وجل».","رواه الحاكم والبيهقي","صحيح"],["عن أنس بن مالك رضي الله عنه قال: كنت عند النبي صلى الله عليه وسلم فجاءه رجل فقال: يا رسول الله، إني أصبتُ حدًّا فأقِمْهُ عليَّ. قال: ولم يسأله عنه، قال: وحضرت الصلاة، فصلى مع النبي صلى الله عليه وسلم، فلما قضى النبي صلى الله عليه وسلم الصلاة قام إليه الرجل فقال: يا رسول الله، إني أصبتُ حدًّا، فأقم فيَّ كتاب الله. قال: «أليس قد صليت معنا؟» قال: نعم، قال: «فإن الله قد غفر لك ذنبك» أو قال: «حدك».","متفق عليه","صحيح"],["عن أنس بن مالك رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «للَّهُ أَفْرَحُ بِتَوْبَةِ عَبْدِهِ مِنْ أَحَدِكُمْ، سَقَطَ عَلَى بَعِيرِهِ، وَقَدْ أَضَلَّهُ فِي أَرْضِ فَلاَةٍ». وفي رواية: «لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ حِينَ يَتُوبُ إِلَيْهِ، مِنْ أَحَدِكُمْ كَانَ عَلَى رَاحِلَتِهِ بِأَرْضِ فَلَاةٍ، فَانْفَلَتَتْ مِنْهُ وَعَلَيْهَا طَعَامُهُ وَشَرَابُهُ، فَأَيِسَ مِنْهَا، فَأَتَى شَجَرَةً، فَاضْطَجَعَ فِي ظِلِّهَا، وقَدْ أَيِسَ مِنْ رَاحِلَتِهِ، فَبَيْنَا هُوَ كَذَلِكَ إِذَا هُوَ بِهَا، قَائِمَةً عِنْدَهُ، فَأَخَذَ بِخِطَامِهَا، ثُمَّ قَالَ مِنْ شِدَّةِ الْفَرَحِ: اللهُمَّ أَنْتَ عَبْدِي وَأَنَا رَبُّكَ! أَخْطَأَ مِنْ شِدَّةِ الْفَرَح».","متفق عليه والرواية الأولى لفظ البخاري، والرواية الثانية لفظ مسلم","صحيح"]]],["تزكية النفوس",[["عن أنس بن مالك رضي الله عنه قال: «إنكم لتعملون أعمالا هي أَدَقُّ في أعينكم من الشَّعْرِ، كنا نَعُدُّهَا على عهد رسول الله - صلى الله عليه وسلم - من المُوبِقَاتِ».","رواه البخاري","صحيح وهو موقوف هلى أنس بن مالك"],["عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم: (إن أول ما يُسأل عنه يوم القيامة -يعني العبد- من النعيم أن يقال له: ألم نُصِحَّ لك جسمك، ونُرْوِيك من الماء البارد؟).","رواه الترمذي","صحيح"],["عن أنس -رضي الله عنه - أن رسول الله صلى الله عليه وسلم قال: \"إذا أراد الله بعبده الخير عجل له العقوبة في الدنيا، وإذا أراد بعبده الشر أمسك عنه بذنبه حتى يُوَافِيَ به يومَ القيامة\".","رواه الترمذي","صحيح"],["عن صعصعة بن معاوية عم الفرزدق -أو عم الأحنف- أنه أتى النبي صلى الله عليه وسلم، فقرأ عليه: {فمن يعمل مثقال ذرة خيرًا يره ومن يعمل مثقال ذرة شرًّا يره} [الزلزلة: 8]، قال: حسبي، لا أبالي ألا أسمع غيرها.","رواه أحمد والطبراني","صحيح"]]],["أهوال القبور",[["عن البراء بن عازب رضي الله عنه ، قال: خرجنا مع رسول الله صلى الله عليه وسلم في جنازة رجل من الأنصار، فانتهينا إلى القبر ولمَّا يُلْحَد، فجلس رسول الله صلى الله عليه وسلم وجلسنا حوله كأنما على رءوسنا الطير، وفي يده عود يَنكتُ به في الأرض، فرفع رأسه، فقال: «استعيذوا بالله من عذاب القبر» مرتين، أو ثلاثا، زاد في رواية: \"وإنه ليسمع خَفْقَ نعالهم إذا وَلَّوا مُدْبِرين حين يقال له: يا هذا، من ربك؟ وما دينك؟ ومن نبيك؟\" قال هناد: قال: \"ويأتيه ملكان فيُجلِسانه فيقولان له: من ربك؟ فيقول: ربي الله، فيقولان له: ما دينك؟ فيقول: ديني الإسلام، فيقولان له: ما هذا الرجل الذي بُعث فيكم؟\" قال: \"فيقول: هو رسول الله صلى الله عليه وسلم ، فيقولان: وما يُدريك؟ فيقول: قرأتُ كتاب الله فآمنت به وصدقت، «زاد في حديث جرير» فذلك قول الله عز وجل {يُثَبِّتُ اللهُ الذين آمنوا} [إبراهيم: 27]\" الآية -ثم اتفقا- قال: \"فينادي مُناد من السماء: أن قد صدق عبدي، فأفرشوه من الجنة، وافتحوا له بابا إلى الجنة، وألبسوه من الجنة\" قال: «فيأتيه من رَوْحها وطِيبها» قال: «ويُفتَح له فيها مدَّ بصره» قال: «وإن الكافر» فذكر موته قال: \"وتُعاد روحه في جسده، ويأتيه ملكان فيُجلسانه فيقولان: له من ربُّك؟ فيقول: هَاهْ هَاهْ هَاهْ، لا أدري، فيقولان له: ما دينك؟ فيقول: هَاهْ هَاهْ، لا أدري، فيقولان: ما هذا الرجل الذي بُعث فيكم؟ فيقول: هَاهْ هَاهْ، لا أدري، فينادي مناد من السماء: أن كذب، فأفرشوه من النار، وألبسوه من النار، وافتحوا له بابا إلى النار\" قال: «فيأتيه من حَرِّها وسَمُومها» قال: «ويُضيَّق عليه قبره حتى تختلف فيه أضلاعه» زاد في حديث جرير قال: «ثم يُقَيَّض له أعمى أَبْكَم معه مِرْزَبّة من حديد، لو ضُرب بها جبل لصار ترابا» قال: «فيضربه بها ضربة يسمعها ما بين المشرق والمغرب إلا الثَّقَلين، فيصير ترابا» قال: «ثم تُعاد فيه الروح».","رواه أبو داود وأحمد","صحيح"],["عَن هَانِئ مَوْلَى عُثْمَانَ رَضيَ اللهُ عنهُ قَالَ: كَانَ عُثْمَانُ إِذَا وَقَفَ عَلَى قَبْرٍ بَكَى حَتَّى يَبُلَّ لِحْيَتَهُ، فَقِيلَ لَهُ: تُذْكَرُ الْجَنَّةُ وَالنَّارُ فَلَا تَبْكِي، وَتَبْكِي مِنْ هَذَا؟ فَقَالَ: إِنَّ رَسُولَ اللهِ صلى الله عليه وسلم قَالَ: «إِنَّ الْقَبْرَ أَوَّلُ مَنْزِلٍ مِنْ مَنَازِلِ الْآخِرَةِ، فَإِنْ نَجَا مِنْهُ فَمَا بَعْدَهُ أَيْسَرُ مِنْهُ، وَإِنْ لَمْ يَنْجُ مِنْهُ فَمَا بَعْدَهُ أَشَدُّ مِنْهُ».","رواه الترمذي وابن ماجه","حسن"]]],["صفات الجنة والنار",[["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لَقَابُ قَوْسٍ في الجنة خيرٌ مما تَطلُع عليه الشمس أو تَغْرُب».","رواه البخاري","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « سَيْحَانُ وَجَيْحَانُ وَالفُرَاتُ والنِّيل كلٌّ من أنهار الجنة».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «حُجِبَتِ النَّارُ بِالشَّهَوَاتِ، وَحُجِبَتِ الْجَنَّةُ بِالْمَكَارِهِ».","رواه البخاري","صحيح"],["عن أبي موسى الأشعري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ثلاثة لا يدخلون الجنة مُدْمِنُ خمر، وقاطع الرحم، ومُصَدِّق بالسِّحْر».","رواه أحمد وابن حبان","صحيح لغيره"],["عن ابن مسعود رضي الله عنه قال: قال النبي صلى الله عليه وسلم: «الْجَنَّةُ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ شِرَاكِ نَعْلِهِ، وَالنَّارُ مِثْلُ ذَلِكَ».","رواه البخاري","صحيح"],["عن سهل بن سعد رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: «مَنْ يَضْمَنْ لِي مَا بَيْنَ لَحْيَيْهِ وَمَا بَيْنَ رِجْلَيْهِ أَضْمَنْ لَهُ الْجَنَّةَ».","رواه البخاري","صحيح"],["عن ابن عباس وعمران بن الحصين رضي الله عنهم عن النبي صلى الله عليه وسلم قال: «اطَّلَعت في الجنة فرأيتُ أكثرَ أهلِها الفقراءَ، واطَّلعتُ في النار فرأيتُ أكثرَ أهلها النِّساءَ».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إنَّ في الجنَّة مائةَ دَرَجَة أعَدَّهَا الله للمُجاهِدين في سَبِيل الله ما بَيْنَ الدَّرَجَتَيْنِ كما بين السماء والأرض».","رواه البخاري","صحيح"],["عن جابر بن عبد الله رضي الله عنهما قال: سمعت رسول الله صلى الله عليه وسلم يقول: «مَنْ لَقِيَ اللهَ لَا يُشْرِكُ بِهِ شَيْئًا دَخَلَ الْجَنَّةَ، وَمَنْ لَقِيَهُ يُشْرِكُ بِهِ دَخَلَ النَّارَ».","رواه مسلم","صحيح"]]]]],["فضائل القرآن",0,[["فضل العناية بالقرآن",[["عن عثمان رضي الله عنه عن النبي صلى الله عليه وسلم قال: «خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ».","رواه البخاري","صحيح"],["عن أبي لبابة بشير بن عبد المنذر رضي الله عنه : أن النبي صلى الله عليه وسلم قال: «مَن لَم يَتَغنَّ بِالقُرآنِ فَليسَ مِنَّا».","رواه أبو داود","صحيح"],["عن عمر بن الخطاب رضي الله عنه : أن النبي صلى الله عليه وسلم قال: «إن اللهَ يَرفعُ بهذا الكِتابِ أقْواماً ويَضَعُ به آخَرِينَ».","رواه مسلم","صحيح"],["عن عبد الرحمن بن شبل الأنصاري قال: سمعت رسول الله صلى الله عليه وسلم يقول: \"اقرؤوا القرآن، ولا تغلوا فيه، ولا تجفوا عنه، ولا تأكلوا به، ولا تستكثروا به\".","رواه أحمد","صحيح"],["عن أبي أمامة رضي الله عنه قال: سمعتُ رسولَ اللهِ صلى الله عليه وسلم يقولُ: «اقْرَؤُوا القرْآنَ؛ فَإنَّهُ يَأتِي يَوْمَ القِيَامَةِ شَفِيعًا لأَصْحَابِهِ».","رواه مسلم","صحيح"],["عن أبي هريرة، قال: كان يعرض على النبي صلى الله عليه وسلم القرآن كل عام مرة، فعرض عليه مرتين في العام الذي قبض فيه، وكان يعتكف كل عام عشرا، فاعتكف عشرين في العام الذي قبض فيه.","رواه البخاري","صحيح"],["عن أنس رضي الله عنه أن أبا موسى رضي الله عنه كان يقرأ ذات ليلة فمشى رسول الله صلى الله عليه وسلم يسمع فلما أصبح قيل له قال: لو علمتُ لحبَّرتُ لك تحبيرًا ولشوَّقتُ لك تشويقًا.","رواه ابن أبي شيبة والضياء المقدسي","صحيح"],["عن أبي موسى الأشعري رضي الله عنه عن النبي صلى الله عليه وسلم قال: «تَعَاهَدُوا هَذَا الْقُرْآنَ، فَوَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَهُوَ أَشَدُّ تَفَلُّتًا مِنَ الْإِبِلِ فِي عُقُلِهَا».","متفق عليه","صحيح"],["عن النواس بن سمعان رضي الله عنه قال: سمعتُ رسولَ اللهِ صلى الله عليه وسلم يقولُ: «يُؤتى يوم القيامة بالقرآن وأهلِه الذين كانوا يعملون به في الدنيا، تَقْدُمُه سورةُ البقرة وآلِ عمران، تُحاجَّانِ عن صاحِبِهِما».","رواه مسلم، ولفظة: \"في الدنيا\" لا توجد في مسلم، ولعل النووي أخذها من ابن الأثير، انظر: جامع الأصول (8/472 رقم6242)","صحيح"],["عن عبد الله بن مسعود رضي الله عنه قال: قال النبي صلى الله عليه وسلم : «بِئْسَ ما لأحَدِهم أنْ يقول نَسِيتُ آيةَ كَيْتَ وكَيْتَ، بل نُسِّيَ، واستذكِروا القرآن، فإنه أشدُّ تَفَصِّيًا مِن صدور الرِّجال من النَّعَم».","متفق عليه","صحيح"],["عن جابر بن عبد الله قال: خَرَجَ علينا رسول الله صلى الله عليه وسلم ونحن نقرأُ القرآنَ وفينا الأعرابي والعَجَمي، فقال: \"اقرَؤوا، فكُل حَسَنٌ، وسيَجيءُ أقوام يُقِيمُونَه كما يقامُ القِدْحُ، يَتَعجلونَه ولا يَتأجّلونَه\".","رواه أبو داود وأحمد","صحيح"],["عن أبي موسى الأشعري رضي الله عنه : أن رسول الله صلى الله عليه وسلم قال له: «لقد أُوتيتَ مِزْمَاراً من مزامير آل داود». وفي رواية لمسلم: أنّ رسول الله صلى الله عليه وسلم قال له: «لو رَأيتَنِي وأنا أستمع لقراءتك البارحة».","متفق عليه","صحيح"]]],["فضائل السور والآيات",[["عن أبي مسعود رضي الله عنه قال: قال النبي صلى الله عليه وسلم: «مَنْ قَرَأَ بِالْآيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ».","متفق عليه","صحيح"],["عن أبي الدرداء عن النبي صلى الله عليه وسلم قال: «أيعجز أحدكم أن يقرأ في ليلة ثلث القرآن؟» قالوا: وكيف يقرأ ثلث القرآن؟ قال: «قل هو الله أحد تعدل ثلث القرآن».","رواه مسلم","صحيح"],["عن أبي الدرداء رضي الله عنه أن النبي صلى الله عليه وسلم قال: «مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الكَهْفِ، عُصِمَ مِنَ الدَّجَّالِ». وفي رواية: «مِنْ آخِرِ سُورَةِ الكَهْف».","رواه مسلم","صحيح"],["عن عقبة بن عامر رضي الله عنه : أن رسول الله صلى الله عليه وسلم قال: «ألَمْ تَرَ آيَاتٍ أُنْزِلَتْ هذِهِ اللَّيْلَةَ لَمْ يُرَ مِثْلُهُنَّ قَطُّ؟ (قل أعوذ برب الفلق) و(قل أعوذ برب الناس)».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه: أن رسول الله صلى الله عليه وسلم قال: «لَا تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ، إِنَّ الشَّيْطَانَ يَنْفِرُ مِنَ الْبَيْتِ الَّذِي تُقْرَأُ فِيهِ سُورَةُ الْبَقَرَةِ».","رواه مسلم","صحيح"],["عن البراء بن عازب –رضي الله عنهما- قال: كانَ رجلٌ يَقرَأُ سُورةَ الكهفِ، وعندَه فَرَسٌ مَربُوطٌ بِشَطَنَيْنِ، فَتَغَشَّتْهُ سَحَابَةٌ فَجَعَلَتْ تَدْنُو، وجَعلَ فَرَسُه يَنفِرُ منها، فلمّا أصبحَ أتَى النبيَّ صلى الله عليه وسلم فَذَكرَ ذلك له، فقالَ: «تِلكَ السَّكِينةُ تَنَزَّلَتْ للقُرآنِ».","متفق عليه","صحيح"],["عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم: «احْشُدوا، فإني سأقرأ عليكم ثلث القرآن»، فحَشَدَ مَن حَشَدَ، ثم خرج نبي الله صلى الله عليه وسلم، فقرأ (قل هو الله أحد) ثم دخل، فقال بعضنا لبعض: إني أرى هذا خبر جاءه من السماء فذاك الذي أدخله، ثم خرج نبي الله صلى الله عليه وسلم، فقال: «إني قلت لكم سأقرأ عليكم ثلث القرآن، ألا إنها تعدل ثلث القرآن».","رواه مسلم","صحيح"],["عن عائشة رضي الله عنها «أن رسول الله صلى الله عليه وسلم بعث رجلا على سَرِيَّةٍ فكان يَقْرَأ لأصحابه في صلاتهم، فَيَخْتِمُ بـ«قل هو الله أحد» فلما رجعوا ذكروا ذلك لرسول الله صلى الله عليه وسلم فقال: سَلُوهُ لأَيِّ شيء صَنَع ذلك؟ فسألُوه، فقال: لِأنَّها صِفَةُ الرحمن عز وجل ، فأنا أُحِب أَنْ أَقْرَأ بها، فقال رسول الله صلى الله عليه وسلم : أَخْبِرُوه: أنَّ الله تعالى يُحِبُّه».","متفق عليه","صحيح"],["عن أبي أمامة الباهلي رضي الله عنه قال: سمعتُ رسول الله صلى الله عليه وسلم يقول: «اقرؤوا القرآنَ فإنَّه يأتي يوم القيامة شَفِيعًا لأصحابه، اقرؤوا الزَّهرَاوَين البقرةَ وسورةَ آل عِمران، فإنهما تأتِيان يوم القيامة كأنهما غَمَامَتان، أو كأنهما غَيَايَتانِ، أو كأنهما فِرْقانِ من طَيْر صَوافٍّ، تُحاجَّان عن أصحابهما، اقرؤوا سورة البقرة، فإن أخذها بَرَكة، وتركها حَسْرة، ولا تستطيعها البَطَلَة».","رواه مسلم","صحيح"],["عن أبي سعيد رافع بن المعلى رضي الله عنه قال: قال لي رسول الله صلى الله عليه وسلم : «أَلاَ أُعَلِّمُكَ أَعْظَمَ سُورَةٍ في القُرْآن قَبْلَ أنْ تَخْرُجَ مِنَ الْمَسْجِد؟» فَأخَذَ بِيَدِي، فَلَمَّا أرَدْنَا أنْ نَخْرُجَ، قُلْتُ: يَا رَسُولَ اللهِ، إنَّكَ قُلْتَ: لأُعَلِّمَنَّكَ أعْظَمَ سُورَةٍ في القُرْآنِ؟ قالَ: «الحَمْدُ للهِ رَبِّ العَالَمِينَ، هِيَ السَّبْعُ المَثَانِي وَالقُرْآنُ العَظِيمُ الَّذِي أُوتِيتُهُ».","رواه البخاري","صحيح"]]]]],["الإيمان بالله",0,[["توحيد الألوهية",[["عن بُريدة رضي الله عنه : أن النبي صلى الله عليه وسلم كان لا يَتَطَيَّر.","رواه أبو داود","صحيح"],["عن عبد الله بن مسعود قال: قال رسول الله صلى الله عليه وسلم: «هَلَكَ الْمُتَنَطِّعُون» قالها ثلاثًا.","رواه مسلم","صحيح"],["عن أبي مَرْثَدٍ الغَنَوِيّ رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «لَا تَجْلِسُوا عَلَى الْقُبُورِ، وَلَا تُصَلُّوا إِلَيْهَا».","رواه مسلم","صحيح"],["عن ابن عمر رضي الله عنهما : أن رسول الله صلى الله عليه وسلم قال: «إن الذين يَصْنَعُون هذه الصُّور يُعَذَّبُونَ يوم القيامة، يُقال لهم: أَحْيُوا ما خَلَقْتُم».","متفق عليه","صحيح"],["عن عبد الله بن مسعود رضي الله عنه عن النبي صلى الله عليه وسلم أنه قال: \"أكبر الكبائر: الإشراك بالله، والأمن من مَكْرِ الله، والقُنُوطُ من رحمة الله، واليَأْسُ من رَوْحِ الله\".","رواه عبد الرزاق","إسناده صحيح"],["عن ابن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «من أصابته فَاقَة فأنْزَلها بالناس لم تُسَدَّ فَاقَتُهُ، ومن أنْزَلها بالله، فَيُوشِكُ الله له بِرزق عاجل أو آجل».","رواه أبو داود والترمذي وأحمد","صحيح"],["عن أم ثابتٍ كَبْشَةَ بنتِ ثابتٍ أُخْتِ حَسَّانَ بنِ ثابتٍ رضي الله عنهما ، قالت: دَخَلَ عَلَيَّ رسولُ اللهِ صلى الله عليه وسلم فَشَرِبَ مِنْ فِي قِرْبَةٍ مُعَلَّقَةٍ قائمًا، فقُمتُ إلى فِيها فَقَطَعْتُهُ.","رواه الترمذي وابن ماجه وأحمد","صحيح"]]],["توحيد الأسماء والصفات",[["عن أبي هريرة رضي الله عنه قَال رسول الله صلى الله عليه وسلم : «العز إزاري، والكبرياء ردائي، فمن نازعني بشيء منهما عذبته».","رواه مسلم وفي لفظه اختلاف يسير، وهذا لفظ البخاري في الأدب المفرد","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إن لله تِسْعَةً، وتِسْعِينَ، اسْمًا، مِائَةً إلا واحدا مَنْ أَحْصَاهَا دخل الجنة».","متفق عليه","صحيح"],["عن عبد الله بن عمرو رضي الله عنهما أن النبي صلى الله عليه وسلم قال: «الرَّاحِمُونَ يَرْحَمُهمُ الرَّحمنُ، ارحَمُوا أهلَ الأرضِ يَرْحْمْكُم مَن في السّماء».","رواه أبو داود والترمذي وأحمد","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إِنَّ اللهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ، وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ».","رواه مسلم","صحيح"]]]]],["اليوم الآخر",0,[["الحياة البرزخية",[["عن أبي أيوب رضي الله عنه، قال: خرج النبي صلى الله عليه وسلم وقد وَجَبَت الشمس، فسمع صوتا فقال: «يهودُ تُعذَّب في قبورها».","متفق عليه","صحيح"],["عن عبدِ الله بن مسعود عن النبيِّ -صلَّى الله عليه وسلم- قال: \"لو لم يبقَ من الدُّنيا إلا يومٌ لطوَّل الله ذلك اليومَ حتى يبعثَ اللهُ فيه رجُلاً مني أو من أهلِ بيتي، يواطئُ اسمُه اسمي، واسمُ أبيه اسمَ أبي يَملأ الأرضَ قِسطاً وعَدلاً، كما مُلِئَت ظلماً وجَوْراً\".","رواه أبو داود والترمذي","صحيح"]]],["أشراط الساعة",[["عن عائشة عن النبي صلى الله عليه وسلم قال: \"إن للقبر ضَغْطةً، ولو كان أحد ناجيًا منها نجا منها سعد بن معاذ\".","رواه أحمد","صحيح"],["عن سهل بن سعد رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: «بُعِثْتُ أنا والساعةَ هكذا»، ويُشير بإصبعيه فيَمُدُّ بهما.","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «على أَنْقَابِ المدينةِ ملائكةٌ لا يدخلُها الطَّاعونُ، ولا الدَّجَّالُ».","متفق عليه","صحيح"],["عن ثوبان مولى رسول الله صلى الله عليه وسلم مرفوعًا: «عِصابتان من أُمَّتي أحرزهما اللهُ من النار: عصابةٌ تغزو الهندَ، وعصابةٌ تكون مع عيسى ابن مريم عليهما السلام».","رواه النسائي وأحمد","صحيح"],["عن أبي هريرة، قال: قال النبي صلى الله عليه وسلم : «والذي نفسي بيده ليأتينَّ على الناس زمانٌ لا يدري القاتلُ في أيِّ شيء قَتَل، ولا يدري المقتولُ على أيِّ شيء قُتِل».","رواه مسلم","صحيح"],["عن أبي الدرداء رضي الله عنه أن النبي صلى الله عليه وسلم قال: «مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الكَهْفِ، عُصِمَ مِنَ الدَّجَّالِ». وفي رواية: «مِنْ آخِرِ سُورَةِ الكَهْف».","رواه مسلم","صحيح"],["عن خالد بن عُرْفُطَةَ رضي الله عنه قال: قال لي رسول الله صلى الله عليه وسلم : \"يا خالد إنها ستكون بَعْدِي أَحْدَاثٌ وفِتَنٌ واختلاف، فَإِنِ اسْتَطَعْتَ أن تكون عبد الله المقتول لا القاتل فَافْعَلْ\".","رواه أحمد","صحيح"]]],["الحياة الآخرة",[["عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : « سَيْحَانُ وَجَيْحَانُ وَالفُرَاتُ والنِّيل كلٌّ من أنهار الجنة».","رواه مسلم","صحيح"],["عن أبي هريرة رضي الله عنه عن رسول الله صلى الله عليه وسلم قال: «إنه لَيَأتي الرَّجلُ السَّمين العظيم يوم القيامة لا يَزِنُ عند الله جَناح بَعُوضة».","متفق عليه","صحيح"],["عن عبد الله بن عمر رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «يقوم الناس لرب العالمين حتى يَغِيبَ أحدهم في رَشْحِهِ إلى أَنْصَافِ أُذُنَيْهِ».","متفق عليه","صحيح"],["عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إنَّ في الجنَّة مائةَ دَرَجَة أعَدَّهَا الله للمُجاهِدين في سَبِيل الله ما بَيْنَ الدَّرَجَتَيْنِ كما بين السماء والأرض».","رواه البخاري","صحيح"],["عن معاذ بن جبل رضي الله عنه عن رسول الله صلى الله عليه وسلم أنه قال: «قَالَ اللهُ -عَزَّ وجَلَّ-: المُتَحَابُّون فِي جَلاَلِي، لَهُم مَنَابِرُ مِن نُورٍ يَغْبِطُهُم النَبِيُّونَ والشُهَدَاء».","رواه الترمذي وأحمد","صحيح"]]]]]];